#region TraceProxy Command Class
#if ISOLATED_INTERPRETERS || ISOLATED_PLUGINS
namespace Licensing.Transient.Commands
{
    /// <summary>
    /// Wraps an underlying command or callback so that each execution can be
    /// traced.
    /// </summary>
#if OBFUSCATION
    [Obfuscation(Feature = "renaming")]
#endif
    [ObjectId("8102891c-37c6-4a15-a012-60aba82c0ab2")]
    [CommandFlags(CommandFlags.Unsafe
        | CommandFlags.Proxy
        | CommandFlags.NoAdd
#if ENTERPRISE_LOCKDOWN
        | CommandFlags.NoRename
        | CommandFlags.NoRemove
#endif
    )]
    [ObjectGroup("proxy")]
    internal sealed class TraceProxy : Eagle._Commands.Default
    {
        #region Private Data
        /// <summary>
        /// The underlying command wrapped by this proxy.
        /// </summary>
        private readonly ICommand command;
        #endregion

        ///////////////////////////////////////////////////////////////////////

        #region Public Constructors
        /// <summary>
        /// Constructs an instance of the <see cref="TraceProxy" /> class.
        /// </summary>
        /// <param name="commandData">
        /// The data used to initialize the command, including its name and
        /// other associated metadata.
        /// </param>
        /// <param name="command">
        /// The underlying command to be wrapped.
        /// </param>
        public TraceProxy( /* CORE */
            ICommandData commandData, /* in */
            ICommand command          /* in */
            )
            : base(commandData)
        {
            this.Flags |= Utility.GetCommandFlags(GetType().BaseType) |
                Utility.GetCommandFlags(this);

            this.command = command;
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////

        #region Private Methods
        /// <summary>
        /// Verifies that the underlying command is valid.
        /// </summary>
        /// <exception cref="ScriptException">
        /// Thrown if the operation cannot be completed successfully.
        /// </exception>
        private void CheckCommand()
        {
            if (command == null)
                throw new ScriptException("invalid underlying command");
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////

        #region IState Members
        /// <summary>
        /// Gets or sets a value indicating whether the underlying command has
        /// been initialized.
        /// </summary>
        public override bool Initialized
        {
            get { CheckCommand(); return command.Initialized; }
            set { CheckCommand(); command.Initialized = value; }
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Initializes this command.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public override ReturnCode Initialize(
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ref Result result        /* out */
            )
        {
            if (command == null)
            {
                result = "invalid underlying command";
                return ReturnCode.Error;
            }

            return command.Initialize(interpreter, clientData, ref result);
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Terminates this command.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public override ReturnCode Terminate(
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ref Result result        /* out */
            )
        {
            if (command == null)
            {
                result = "invalid underlying command";
                return ReturnCode.Error;
            }

            return command.Terminate(interpreter, clientData, ref result);
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////

        #region IExecute Members
        /// <summary>
        /// Executes the command and returns the result of the operation.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public override ReturnCode Execute(
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (command == null)
            {
                result = "invalid underlying command";
                return ReturnCode.Error;
            }

            long entryId = 0;

            Helpers.Trace(
                interpreter, clientData, arguments, ref entryId);

            ReturnCode code = command.Execute(
                interpreter, clientData, arguments, ref result);

            Helpers.Trace(
                interpreter, clientData, arguments, code, result,
                ref entryId);

            return code;
        }
        #endregion
    }
}
#endif
#endregion

