///////////////////////////////////////////////////////////////////////////////

namespace Licensing.Components.Private.Commands
{
    #region Helpers Class (Configuration)
    /// <summary>
    /// Provides helper methods shared by the licensing command
    /// implementations.
    /// </summary>
    [ObjectId("a4f98600-1977-4df6-9d2d-afa4e9146fd8")]
    internal static class Helpers
    {
        #region Installation Helper Class
        /// <summary>
        /// Represents the state of a single in-progress file installation
        /// performed by the licensing subsystem.
        /// </summary>
#if XML && NETWORK && WEB
        [ObjectId("10d306c5-2d7b-4b14-9871-f6b11c4a93e0")]
        private sealed class Installation : IDisposable
        {
            #region Private Data
            /// <summary>
            /// The object used to synchronize access to the state of this
            /// instance.
            /// </summary>
            private readonly object syncRoot = new object();

            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// The time at which this installation was started.
            /// </summary>
            private readonly DateTime started; /* Constructor */
            /// <summary>
            /// The interpreter associated with this installation.
            /// </summary>
            private Interpreter interpreter;   /* Constructor */
            /// <summary>
            /// The extra data associated with this installation.
            /// </summary>
            private IClientData clientData;    /* Constructor */
            /// <summary>
            /// The source directory for this installation.
            /// </summary>
            private string sourceDirectory;    /* Constructor */
            /// <summary>
            /// The target directory for this installation.
            /// </summary>
            private string targetDirectory;    /* Constructor */
            /// <summary>
            /// The optional timeout, in milliseconds, for this installation.
            /// </summary>
            private int? timeout;              /* Constructor */
            /// <summary>
            /// The flags that control the behavior of this installation.
            /// </summary>
            private InstallFlags installFlags; /* Constructor */

            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// The context data used when evaluating manifest scripts.
            /// </summary>
            private EvaluateClientData evaluateClientData; /* Pass 0+ */
            /// <summary>
            /// The list of manifest file names for this installation.
            /// </summary>
            private StringList manifestFileNames;          /* Pass 0+ */
            /// <summary>
            /// The list of source file names for this installation.
            /// </summary>
            private StringList sourceFileNames;            /* Pass 0+ */
            /// <summary>
            /// The list of relative file names for this installation.
            /// </summary>
            private StringList relativeFileNames;          /* Pass 1+ */
            /// <summary>
            /// The list of existing target file names for this installation.
            /// </summary>
            private StringList existingFileNames;          /* Pass 1+ */
            /// <summary>
            /// The list of backup file names for this installation.
            /// </summary>
            private StringList backupFileNames;            /* Pass 2+ */
            /// <summary>
            /// The list of target file names for this installation.
            /// </summary>
            private StringList targetFileNames;            /* Pass 3+ */
            /// <summary>
            /// Non-zero if a rollback should be performed for this
            /// installation.
            /// </summary>
            private bool rollback;                         /* Pass 3+ */
            /// <summary>
            /// The list of rollback file names for this installation.
            /// </summary>
            private StringList rollbackFileNames;          /* Pass 4+ */
            #endregion

            ///////////////////////////////////////////////////////////////////

            #region Public Constructors
            /// <summary>
            /// Constructs an instance of the <see cref="Installation" />
            /// class.
            /// </summary>
            /// <param name="interpreter">
            /// The interpreter in which the operation is being performed.
            /// </param>
            /// <param name="clientData">
            /// The extra data supplied by the caller, if any.
            /// </param>
            /// <param name="sourceDirectory">
            /// The source directory.
            /// </param>
            /// <param name="targetDirectory">
            /// The target directory.
            /// </param>
            /// <param name="timeout">
            /// The timeout.
            /// </param>
            /// <param name="installFlags">
            /// The install flags.
            /// </param>
            public Installation( /* CORE */
                Interpreter interpreter,  /* in */
                IClientData clientData,   /* in */
                string sourceDirectory,   /* in */
                string targetDirectory,   /* in */
                int? timeout,             /* in: OPTIONAL */
                InstallFlags installFlags /* in */
                )
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    this.started = Utility.GetUtcNow();
                    this.interpreter = interpreter;
                    this.clientData = clientData;
                    this.sourceDirectory = sourceDirectory;
                    this.targetDirectory = targetDirectory;
                    this.timeout = timeout;
                    this.installFlags = installFlags;
                }
            }
            #endregion

            ///////////////////////////////////////////////////////////////////

            #region Private Methods
            /// <summary>
            /// Gets the time that has elapsed since this installation was
            /// started.
            /// </summary>
            /// <returns>
            /// The elapsed produced by the operation.
            /// </returns>
            private TimeSpan GetElapsed() /* CORE */
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    return Utility.GetUtcNow().Subtract(started);
                }
            }

            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// Determines whether the flags is present.
            /// </summary>
            /// <param name="hasFlags">
            /// The has flags.
            /// </param>
            /// <returns>
            /// <see langword="true" /> if the condition is satisfied;
            /// otherwise, <see langword="false" />.
            /// </returns>
            private bool HasFlags( /* CORE */
                InstallFlags hasFlags /* in */
                )
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    return SharedOps.HasFlags(
                        installFlags, hasFlags, true);
                }
            }

            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// Verifies the state.
            /// </summary>
            /// <param name="pass">
            /// The pass.
            /// </param>
            /// <param name="returnCode">
            /// The return code.
            /// </param>
            /// <param name="error">
            /// Upon failure, receives information about the error that was
            /// encountered.
            /// </param>
            /// <returns>
            /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
            /// <see cref="ReturnCode" /> value that indicates the type of
            /// failure.
            /// </returns>
            private ReturnCode VerifyState( /* CORE */
                InstallPass pass,      /* in */
                ReturnCode returnCode, /* in */
                ref Result error       /* out */
                )
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    if (String.IsNullOrEmpty(sourceDirectory))
                    {
                        error = "source directory is invalid";
                        return ReturnCode.Error;
                    }

                    if (!Directory.Exists(sourceDirectory))
                    {
                        error = "source directory does not exist";
                        return ReturnCode.Error;
                    }

                    if (String.IsNullOrEmpty(targetDirectory))
                    {
                        error = "target directory is invalid";
                        return ReturnCode.Error;
                    }

                    if (!Directory.Exists(targetDirectory))
                    {
                        error = "target directory does not exist";
                        return ReturnCode.Error;
                    }

                    if (evaluateClientData == null)
                    {
                        error = "missing context clientData";
                        return ReturnCode.Error;
                    }

                    if ((pass > InstallPass.Pass0) &&
                        (manifestFileNames == null))
                    {
                        error = "invalid manifest file names";
                        return ReturnCode.Error;
                    }

                    if ((pass > InstallPass.Pass0) &&
                        (sourceFileNames == null))
                    {
                        error = "invalid source file names";
                        return ReturnCode.Error;
                    }

                    if ((pass > InstallPass.Pass1) &&
                        (relativeFileNames == null))
                    {
                        error = "invalid relative file names";
                        return ReturnCode.Error;
                    }

                    if ((pass > InstallPass.Pass1) &&
                        (existingFileNames == null))
                    {
                        error = "invalid existing file names";
                        return ReturnCode.Error;
                    }

                    if ((pass > InstallPass.Pass2) &&
                        (backupFileNames == null))
                    {
                        error = "invalid backup file names";
                        return ReturnCode.Error;
                    }

                    if ((pass > InstallPass.Pass3) &&
                        (targetFileNames == null))
                    {
                        error = "invalid target file names";
                        return ReturnCode.Error;
                    }

                    if ((pass > InstallPass.Pass4) &&
                        (rollbackFileNames == null))
                    {
                        error = "invalid rollback file names";
                        return ReturnCode.Error;
                    }

                    if ((pass != InstallPass.Pass0) &&
                        (pass != InstallPass.Pass6) &&
                        (returnCode != ReturnCode.Ok))
                    {
                        if (pass != InstallPass.Pass4)
                        {
                            error = String.Format(
                                "detected failure before {0}",
                                Utility.FormatWrapOrNull(pass));

                            return returnCode;
                        }
                        else if (!rollback)
                        {
                            error = String.Format(
                                "rollback disabled before {0}",
                                Utility.FormatWrapOrNull(pass));

                            return returnCode;
                        }
                    }

                    return ReturnCode.Ok;
                }
            }

            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// Gets the manifest script return code.
            /// </summary>
            /// <param name="returnCode">
            /// The return code.
            /// </param>
            /// <returns>
            /// The manifest script return code produced by the operation.
            /// </returns>
            private object GetManifestScriptReturnCode( /* CORE */
                ReturnCode returnCode /* in */
                )
            {
                if (HasFlags(InstallFlags.WhatIf))
                {
                    StringList result = new StringList();

                    result.Add(ReturnCode.WhatIf.ToString());
                    result.Add(returnCode.ToString());

                    return result;
                }
                else
                {
                    return returnCode;
                }
            }

            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// Conditionally evaluates the manifest scripts.
            /// </summary>
            /// <param name="pass">
            /// The pass.
            /// </param>
            /// <param name="returnCode">
            /// The return code.
            /// </param>
            /// <param name="error">
            /// Upon failure, receives information about the error that was
            /// encountered.
            /// </param>
            /// <returns>
            /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
            /// <see cref="ReturnCode" /> value that indicates the type of
            /// failure.
            /// </returns>
            private ReturnCode MaybeEvaluateManifestScripts( /* CORE */
                InstallPass pass,      /* in */
                ReturnCode returnCode, /* in */
                ref Result error       /* in, out */
                )
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    if (HasFlags(InstallFlags.NoEvaluateManifests))
                        return ReturnCode.Ok;

                    if (String.IsNullOrEmpty(sourceDirectory))
                    {
                        error = "invalid source directory";
                        return ReturnCode.Error;
                    }

                    if (evaluateClientData == null)
                    {
                        error = "missing context clientData";
                        return ReturnCode.Error;
                    }

                    manifestFileNames = FileOps.GetFileNames(
                        sourceDirectory, Constants.ManifestFileName,
                        true, ref error);

                    if (manifestFileNames == null)
                        return ReturnCode.Error;

                    if (manifestFileNames.Count == 0)
                        return ReturnCode.Ok;

                    ObjectDictionary variables = null;

                    try
                    {
                        variables = new ObjectDictionary();

                        variables.Add(
                            Constants.InstallPassVariableName,
                            pass.ToString());

                        variables.Add(
                            Constants.SourceDirectoryVariableName,
                            sourceDirectory);

                        variables.Add(
                            Constants.TargetDirectoryVariableName,
                            targetDirectory);

                        variables.Add(
                            Constants.RelativeFileNamesVariableName,
                            (relativeFileNames != null) ?
                                relativeFileNames.ToString() : null);

                        variables.Add(
                            Constants.RollbackVariableName, rollback);

                        variables.Add(
                            Constants.ReturnCodeVariableName,
                            GetManifestScriptReturnCode(returnCode));

                        variables.Add(
                            Constants.ErrorVariableName, error);

                        if (ScriptContext.SetVariables(
                                interpreter, variables, true,
                                ref error) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }

                        bool? savedNoScript;

                        evaluateClientData.BeginNoScript(
                            out savedNoScript);

                        try
                        {
                            if (Helpers.EvaluateForEachFile(
                                    interpreter, evaluateClientData,
                                    manifestFileNames, null, null,
                                    null, ref error) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }
                        }
                        finally
                        {
                            evaluateClientData.EndNoScript(
                                ref savedNoScript);
                        }

                        bool localRollback = false;

                        if (ScriptContext.GetVariableAsBoolean(
                                interpreter,
                                Constants.RollbackVariableName,
                                evaluateClientData.CultureInfo,
                                true, ref localRollback,
                                ref error) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }

                        rollback = localRollback;
                        return ReturnCode.Ok;
                    }
                    finally
                    {
                        ReturnCode unsetCode;
                        Result unsetError = null;

                        unsetCode = ScriptContext.UnsetVariables(
                            interpreter, variables, ref unsetError);

                        if (unsetCode != ReturnCode.Ok)
                        {
                            Utility.Complain(
                                interpreter, unsetCode, unsetError);
                        }
                    }
                }
            }

            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// Populates the source files.
            /// </summary>
            /// <param name="error">
            /// Upon failure, receives information about the error that was
            /// encountered.
            /// </param>
            /// <returns>
            /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
            /// <see cref="ReturnCode" /> value that indicates the type of
            /// failure.
            /// </returns>
            private ReturnCode PopulateSourceFiles( /* CORE */
                ref Result error /* out */
                )
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    if (String.IsNullOrEmpty(sourceDirectory))
                    {
                        error = "invalid source directory";
                        return ReturnCode.Error;
                    }

                    sourceFileNames = FileOps.GetFileNames(
                        sourceDirectory, Characters.Asterisk.ToString(),
                        true, ref error);

                    if (sourceFileNames == null)
                        return ReturnCode.Error;

                    sourceFileNames.Sort(); /* O(N log N) */
                    return ReturnCode.Ok;
                }
            }

            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// Gets the relative file name.
            /// </summary>
            /// <param name="fileName">
            /// The file name.
            /// </param>
            /// <param name="newFileName">
            /// Upon return, receives the new file name.
            /// </param>
            /// <param name="error">
            /// Upon failure, receives information about the error that was
            /// encountered.
            /// </param>
            /// <returns>
            /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
            /// <see cref="ReturnCode" /> value that indicates the type of
            /// failure.
            /// </returns>
            private ReturnCode GetRelativeFileName( /* CORE */
                string fileName,        /* in */
                ref string newFileName, /* out */
                ref Result error        /* out */
                )
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    if (String.IsNullOrEmpty(sourceDirectory))
                    {
                        error = "invalid source directory";
                        return ReturnCode.Error;
                    }

                    newFileName = fileName.Substring(
                        sourceDirectory.Length).TrimStart(
                        Characters.DirectorySeparatorChars);

                    if (String.IsNullOrEmpty(newFileName))
                    {
                        error = String.Format(
                            "invalid relative file name for {0}",
                            Utility.FormatWrapOrNull(fileName));

                        return ReturnCode.Error;
                    }

                    return ReturnCode.Ok;
                }
            }

            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// Checks the target file name.
            /// </summary>
            /// <param name="fileName">
            /// The file name.
            /// </param>
            /// <param name="error">
            /// Upon failure, receives information about the error that was
            /// encountered.
            /// </param>
            /// <returns>
            /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
            /// <see cref="ReturnCode" /> value that indicates the type of
            /// failure.
            /// </returns>
            private ReturnCode CheckTargetFileName( /* CORE */
                string fileName, /* in */
                ref Result error /* out */
                )
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    try
                    {
                        if (String.IsNullOrEmpty(targetDirectory))
                        {
                            error = "invalid target directory";
                            return ReturnCode.Error;
                        }

                        if (String.IsNullOrEmpty(fileName))
                        {
                            error = "invalid target relative file name";
                            return ReturnCode.Error;
                        }

                        string targetFileName = Path.Combine(
                            targetDirectory, fileName);

                        if (FileOps.PathExists(targetFileName))
                        {
                            if (HasFlags(InstallFlags.AllowOverwrite) &&
                                !Directory.Exists(targetFileName))
                            {
                                if (existingFileNames == null)
                                    existingFileNames = new StringList();

                                existingFileNames.Add(targetFileName);
                            }
                            else
                            {
                                error = String.Format(
                                    "cannot overwrite existing target {0}",
                                    Utility.FormatWrapOrNull(targetFileName));

                                return ReturnCode.Error;
                            }
                        }

                        return ReturnCode.Ok;
                    }
                    catch (Exception e)
                    {
#if DEBUG || FORCE_TRACE
                        CertificateTraceOps.DebugTrace(
                            e, typeof(Installation).Name,
                            TracePriority.Highest);
#endif

                        error = e;
                        return ReturnCode.Error;
                    }
                }
            }

            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// Conditionally checks the trusted files.
            /// </summary>
            /// <param name="fileName">
            /// The file name.
            /// </param>
            /// <param name="count">
            /// On input, supplies the count; upon return, receives the
            /// updated value.
            /// </param>
            /// <param name="error">
            /// Upon failure, receives information about the error that was
            /// encountered.
            /// </param>
            /// <returns>
            /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
            /// <see cref="ReturnCode" /> value that indicates the type of
            /// failure.
            /// </returns>
            private ReturnCode MaybeCheckTrustedFiles( /* CORE */
                string fileName, /* in */
                ref int count,   /* in, out */
                ref Result error /* out */
                )
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    if (String.IsNullOrEmpty(fileName))
                    {
                        error = "invalid source file name";
                        return ReturnCode.Error;
                    }

                    if (!HasFlags(InstallFlags.AllowTrustedFiles))
                        return ReturnCode.Ok;

                    if (Utility.IsFileTrusted(interpreter, fileName))
                        count++;

                    return ReturnCode.Ok;
                }
            }

            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// Conditionally verifies the signature.
            /// </summary>
            /// <param name="fileName">
            /// The file name.
            /// </param>
            /// <param name="timeout">
            /// The timeout.
            /// </param>
            /// <param name="count">
            /// On input, supplies the count; upon return, receives the
            /// updated value.
            /// </param>
            /// <param name="error">
            /// Upon failure, receives information about the error that was
            /// encountered.
            /// </param>
            /// <returns>
            /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
            /// <see cref="ReturnCode" /> value that indicates the type of
            /// failure.
            /// </returns>
#if CERTIFICATE_PLUGIN && CERTIFICATE_POLICY
            private ReturnCode MaybeVerifySignature( /* CORE */
                string fileName, /* in */
                int? timeout,    /* in: OPTIONAL */
                ref int count,   /* in, out */
                ref Result error /* out */
                )
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    if (String.IsNullOrEmpty(fileName))
                    {
                        error = "invalid source file name";
                        return ReturnCode.Error;
                    }

                    string signatureFileName = String.Format(
                        "{0}{1}", fileName, FileExtension.Signature);

                    if (!File.Exists(signatureFileName))
                        return ReturnCode.Ok;

                    Result localResult = null;

                    if (SharedOps.CheckFileAgainstPolicy(
                            interpreter, null, fileName, timeout,
                            ref localResult) != ReturnCode.Ok)
                    {
                        error = String.Format(
                            "cannot install file {0}: {1}",
                            Utility.FormatWrapOrNull(fileName),
                            Utility.FormatWrapOrNull(localResult));

                        return ReturnCode.Error;
                    }

                    count++;
                    return ReturnCode.Ok;
                }
            }
#endif

            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// Conditionally verifies the base64 signature.
            /// </summary>
            /// <param name="fileName">
            /// The file name.
            /// </param>
            /// <param name="count">
            /// On input, supplies the count; upon return, receives the
            /// updated value.
            /// </param>
            /// <param name="error">
            /// Upon failure, receives information about the error that was
            /// encountered.
            /// </param>
            /// <returns>
            /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
            /// <see cref="ReturnCode" /> value that indicates the type of
            /// failure.
            /// </returns>
            private ReturnCode MaybeVerifyBase64Signature( /* CORE */
                string fileName, /* in */
                ref int count,   /* in, out */
                ref Result error /* out */
                )
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    if (String.IsNullOrEmpty(fileName))
                    {
                        error = "invalid source file name";
                        return ReturnCode.Error;
                    }

                    string signatureFileName =
                        DataOps.FormatSignatureFileName(fileName);

                    if (String.IsNullOrEmpty(signatureFileName))
                    {
                        error = "invalid signature file name";
                        return ReturnCode.Error;
                    }

                    if (!File.Exists(signatureFileName))
                        return ReturnCode.Ok;

                    Result localError = null;

                    if (ScriptOps.ReadSignatureAndVerifyFile(
                            interpreter, evaluateClientData,
                            fileName, ref localError) != ReturnCode.Ok)
                    {
                        error = String.Format(
                            "cannot install file {0}: {1}",
                            Utility.FormatWrapOrNull(fileName),
                            Utility.FormatWrapOrNull(localError));

                        return ReturnCode.Error;
                    }

                    count++;
                    return ReturnCode.Ok;
                }
            }

            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// Backs up the file for pass2.
            /// </summary>
            /// <param name="targetFileName">
            /// The target file name.
            /// </param>
            /// <param name="id">
            /// The id.
            /// </param>
            /// <param name="error">
            /// Upon failure, receives information about the error that was
            /// encountered.
            /// </param>
            /// <returns>
            /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
            /// <see cref="ReturnCode" /> value that indicates the type of
            /// failure.
            /// </returns>
            private ReturnCode BackupFileForPass2( /* CORE */
                string targetFileName, /* in */
                Guid id,               /* in */
                ref Result error       /* out */
                )
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    string backupFileName = null;

                    if (FileOps.CheckBackupFileName(
                            targetFileName, id, ref backupFileName,
                            ref error) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    ///////////////////////////////////////////////////////////

                    try
                    {
                        if (!HasFlags(InstallFlags.WhatIf))
                        {
                            File.Move(targetFileName,
                                backupFileName); /* throw */
                        }

                        if (backupFileNames == null)
                            backupFileNames = new StringList();

                        backupFileNames.Add(backupFileName);
                        return ReturnCode.Ok;
                    }
                    catch (Exception e)
                    {
#if DEBUG || FORCE_TRACE
                        CertificateTraceOps.DebugTrace(
                            e, typeof(Installation).Name,
                            TracePriority.Highest);
#endif

                        error = e;
                        return ReturnCode.Error;
                    }
                }
            }

            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// Copies the file for pass3.
            /// </summary>
            /// <param name="sourceFileName">
            /// The source file name.
            /// </param>
            /// <param name="relativeFileName">
            /// The relative file name.
            /// </param>
            /// <param name="error">
            /// Upon failure, receives information about the error that was
            /// encountered.
            /// </param>
            /// <returns>
            /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
            /// <see cref="ReturnCode" /> value that indicates the type of
            /// failure.
            /// </returns>
            private ReturnCode CopyFileForPass3( /* CORE */
                string sourceFileName,     /* in */
                string relativeFileName,   /* in */
                ref Result error           /* out */
                )
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    if (String.IsNullOrEmpty(targetDirectory))
                    {
                        error = "invalid target directory";
                        return ReturnCode.Error;
                    }

                    if (String.IsNullOrEmpty(relativeFileName))
                    {
                        error = "invalid target relative file name";
                        return ReturnCode.Error;
                    }

                    ///////////////////////////////////////////////////////////

                    try
                    {
                        string targetFileName = Path.Combine(
                            targetDirectory, relativeFileName);

                        if (!HasFlags(InstallFlags.WhatIf))
                        {
                            Directory.CreateDirectory(
                                Path.GetDirectoryName(
                                    targetFileName)); /* throw */

                            File.Copy(sourceFileName,
                                targetFileName); /* throw */
                        }

                        if (targetFileNames == null)
                            targetFileNames = new StringList();

                        targetFileNames.Add(targetFileName);
                        return ReturnCode.Ok;
                    }
                    catch (Exception e)
                    {
#if DEBUG || FORCE_TRACE
                        CertificateTraceOps.DebugTrace(
                            e, typeof(Installation).Name,
                            TracePriority.Highest);
#endif

                        error = e;
                        return ReturnCode.Error;
                    }
                }
            }

            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// Rolls back the file for pass4.
            /// </summary>
            /// <param name="backupFileName">
            /// The backup file name.
            /// </param>
            /// <param name="id">
            /// The id.
            /// </param>
            /// <param name="error">
            /// Upon failure, receives information about the error that was
            /// encountered.
            /// </param>
            /// <returns>
            /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
            /// <see cref="ReturnCode" /> value that indicates the type of
            /// failure.
            /// </returns>
            private ReturnCode RollbackFileForPass4( /* CORE */
                string backupFileName, /* in */
                Guid id,               /* in */
                ref Result error       /* out */
                )
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    string originalFileName = null;

                    if (FileOps.CheckOriginalFileName(
                            backupFileName, id, ref originalFileName,
                            ref error) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    ///////////////////////////////////////////////////////////

                    try
                    {
                        if (!HasFlags(InstallFlags.WhatIf))
                        {
                            File.Move(backupFileName,
                                originalFileName); /* throw */
                        }

                        if (rollbackFileNames == null)
                            rollbackFileNames = new StringList();

                        rollbackFileNames.Add(originalFileName);
                        return ReturnCode.Ok;
                    }
                    catch (Exception e)
                    {
#if DEBUG || FORCE_TRACE
                        CertificateTraceOps.DebugTrace(
                            e, typeof(Installation).Name,
                            TracePriority.Highest);
#endif

                        error = e;
                        return ReturnCode.Error;
                    }
                }
            }

