            private ReturnCode DeleteFileForPass4( /* CORE */
                string fileName, /* in */
                ref Result error /* out */
                )
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    if (!HasFlags(InstallFlags.WhatIf))
