            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// Deletes the directory for pass4.
            /// </summary>
            /// <param name="directory">
            /// The directory.
            /// </param>
            /// <param name="recursive">
            /// The recursive.
            /// </param>
            /// <param name="error">
            /// Upon failure, receives information about the error that was
            /// encountered.
            /// </param>
