            #endregion

            ///////////////////////////////////////////////////////////////////

            #region Public Methods
            #region Installation Pass Handling Methods (Look Here)
            ///////////////////////////////////////////////////////////////////
            // Pass #0, PRE-INSTALL                                          //
            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// Performs the pass0.
            /// </summary>
            /// <param name="returnCode">
            /// The return code.
            /// </param>
            /// <param name="error">
            /// Upon failure, receives information about the error that was
            /// encountered.
            /// </param>
            /// <returns>
            /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
            /// <see cref="ReturnCode" /> value that indicates the type of
            /// failure.
            /// </returns>
            public ReturnCode PerformPass0( /* CORE */
                ReturnCode returnCode, /* in */
                ref Result error       /* in, out */
                )
            {
                CheckDisposed();

                lock (syncRoot) /* TRANSACTIONAL */
                {
                    evaluateClientData = clientData as EvaluateClientData;

                    ///////////////////////////////////////////////////////////

                    if (VerifyState(
                            InstallPass.Pass0, returnCode,
                            ref error) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    ///////////////////////////////////////////////////////////

                    if (MaybeEvaluateManifestScripts(
                            InstallPass.Pass0, returnCode,
                            ref error) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    ///////////////////////////////////////////////////////////

                    if (PopulateSourceFiles(
                            ref error) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    ///////////////////////////////////////////////////////////

                    return returnCode;
                }
            }

            ///////////////////////////////////////////////////////////////////
            // Pass #1, VERIFY                                               //
            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// Performs the pass1.
            /// </summary>
            /// <param name="returnCode">
            /// The return code.
            /// </param>
            /// <param name="error">
            /// Upon failure, receives information about the error that was
            /// encountered.
            /// </param>
            /// <returns>
            /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
            /// <see cref="ReturnCode" /> value that indicates the type of
            /// failure.
            /// </returns>
            public ReturnCode PerformPass1( /* CORE */
                ReturnCode returnCode, /* in */
                ref Result error       /* in, out */
                )
            {
                CheckDisposed();

                lock (syncRoot) /* TRANSACTIONAL */
                {
                    if (VerifyState(
                            InstallPass.Pass1, returnCode,
                            ref error) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    ///////////////////////////////////////////////////////////

                    if (MaybeEvaluateManifestScripts(
                            InstallPass.Pass1, returnCode,
                            ref error) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    ///////////////////////////////////////////////////////////

                    //
                    // HACK: Always create new lists of file names, so full
                    //       state can be verified in pass 2.
                    //
                    relativeFileNames = new StringList();
                    existingFileNames = new StringList();

                    ///////////////////////////////////////////////////////////

                    foreach (string sourceFileName in sourceFileNames)
                    {
                        if (String.IsNullOrEmpty(sourceFileName))
                            continue;

                        ///////////////////////////////////////////////////////

                        string relativeFileName = null;

                        if (GetRelativeFileName(
                                sourceFileName, ref relativeFileName,
                                ref error) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }

                        ///////////////////////////////////////////////////////

                        if (CheckTargetFileName(
                                relativeFileName, ref error) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }

                        ///////////////////////////////////////////////////////

                        //
                        // HACK: Obviously (?), signature files themselves do
                        //       not have signatures.
                        //
                        string baseFileName = null;

                        if (SharedOps.IsSignatureFileName(
                                sourceFileName, ref baseFileName))
                        {
                            if (!File.Exists(baseFileName))
                            {
                                error = String.Format(
                                    "signature file {0} refers to " +
                                    "a file {1} that does not exist",
                                    Utility.FormatWrapOrNull(sourceFileName),
                                    Utility.FormatWrapOrNull(baseFileName));

                                return ReturnCode.Error;
                            }

                            relativeFileNames.Add(relativeFileName);
                            continue;
                        }

                        ///////////////////////////////////////////////////////

                        int signatureCount = 0;

                        ///////////////////////////////////////////////////////

                        if (MaybeCheckTrustedFiles(
                                sourceFileName, ref signatureCount,
                                ref error) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }

                        ///////////////////////////////////////////////////////

#if CERTIFICATE_PLUGIN && CERTIFICATE_POLICY
                        if (MaybeVerifySignature(sourceFileName,
                                timeout, ref signatureCount,
                                ref error) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }
#endif

                        ///////////////////////////////////////////////////////

                        if (MaybeVerifyBase64Signature(
                                sourceFileName, ref signatureCount,
                                ref error) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }

                        ///////////////////////////////////////////////////////

                        if (signatureCount == 0)
                        {
                            error = String.Format(
                                "cannot install file {0}, no signatures",
                                Utility.FormatWrapOrNull(sourceFileName));

                            return ReturnCode.Error;
                        }

                        ///////////////////////////////////////////////////////

                        relativeFileNames.Add(relativeFileName);
                    }

                    ///////////////////////////////////////////////////////////

                    return returnCode;
                }
            }

            ///////////////////////////////////////////////////////////////////
            // Pass #2, BACKUP                                               //
            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// Performs the pass2.
            /// </summary>
            /// <param name="returnCode">
            /// The return code.
            /// </param>
            /// <param name="error">
            /// Upon failure, receives information about the error that was
            /// encountered.
            /// </param>
            /// <returns>
            /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
            /// <see cref="ReturnCode" /> value that indicates the type of
            /// failure.
            /// </returns>
            public ReturnCode PerformPass2( /* CORE */
                ReturnCode returnCode, /* in */
                ref Result error       /* in, out */
                )
            {
                CheckDisposed();

                lock (syncRoot) /* TRANSACTIONAL */
                {
                    if (VerifyState(
                            InstallPass.Pass2, returnCode,
                            ref error) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    ///////////////////////////////////////////////////////////

                    if (MaybeEvaluateManifestScripts(
                            InstallPass.Pass2, returnCode,
                            ref error) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    ///////////////////////////////////////////////////////////

                    //
                    // HACK: Always create new lists of file names, so full
                    //       state can be verified in pass 3.
                    //
                    backupFileNames = new StringList();

                    ///////////////////////////////////////////////////////////

                    if (HasFlags(InstallFlags.SkipBackup))
                        return ReturnCode.Ok;

                    ///////////////////////////////////////////////////////////

                    Guid id = evaluateClientData.Id;

                    if (id.Equals(Guid.Empty))
                    {
                        error = String.Format(
                            "cannot backup files, context {0} missing " +
                            "unique identifier",
                            Utility.FormatWrapOrNull(evaluateClientData));

                        return ReturnCode.Error;
                    }

                    ///////////////////////////////////////////////////////////

                    foreach (string existingFileName in existingFileNames)
                    {
                        if (String.IsNullOrEmpty(existingFileName))
                            continue;

                        if (BackupFileForPass2(existingFileName, id,
                                ref error) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }
                    }

                    ///////////////////////////////////////////////////////////

                    return returnCode;
                }
            }

            ///////////////////////////////////////////////////////////////////
            // Pass #3, COMMIT                                               //
            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// Performs the pass3.
            /// </summary>
            /// <param name="returnCode">
            /// The return code.
            /// </param>
            /// <param name="error">
            /// Upon failure, receives information about the error that was
            /// encountered.
            /// </param>
            /// <returns>
            /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
            /// <see cref="ReturnCode" /> value that indicates the type of
            /// failure.
            /// </returns>
            public ReturnCode PerformPass3( /* CORE */
                ReturnCode returnCode, /* in */
                ref Result error       /* in, out */
                )
            {
                CheckDisposed();

                lock (syncRoot) /* TRANSACTIONAL */
                {
                    if (VerifyState(
                            InstallPass.Pass3, returnCode,
                            ref error) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    ///////////////////////////////////////////////////////////

                    if (MaybeEvaluateManifestScripts(
                            InstallPass.Pass3, returnCode,
                            ref error) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    ///////////////////////////////////////////////////////////

                    //
                    // HACK: Always create new lists of file names, so full
                    //       state can be verified in pass 4.
                    //
                    targetFileNames = new StringList();

                    ///////////////////////////////////////////////////////////

                    int count = 0;

                    foreach (string sourceFileName in sourceFileNames)
                    {
                        if (String.IsNullOrEmpty(sourceFileName))
                            continue;

                        string relativeFileName = null;

                        if (GetRelativeFileName(
                                sourceFileName, ref relativeFileName,
                                ref error) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }

                        if (CopyFileForPass3(
                                sourceFileName, relativeFileName,
                                ref error) != ReturnCode.Ok)
                        {
                            if (count > 0)
                                rollback = true;

                            return ReturnCode.Error;
                        }

                        count++;
                    }

                    ///////////////////////////////////////////////////////////

                    return returnCode;
                }
            }

            ///////////////////////////////////////////////////////////////////
            // Pass #4, ROLLBACK                                             //
            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// Performs the pass4.
            /// </summary>
            /// <param name="returnCode">
            /// The return code.
            /// </param>
            /// <param name="error">
            /// Upon failure, receives information about the error that was
            /// encountered.
            /// </param>
            /// <returns>
            /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
            /// <see cref="ReturnCode" /> value that indicates the type of
            /// failure.
            /// </returns>
            public ReturnCode PerformPass4( /* CORE */
                ReturnCode returnCode, /* in */
                ref Result error       /* in, out */
                )
            {
                CheckDisposed();

                lock (syncRoot) /* TRANSACTIONAL */
                {
                    if (VerifyState(
                            InstallPass.Pass4, returnCode,
                            ref error) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    ///////////////////////////////////////////////////////////

                    if (MaybeEvaluateManifestScripts(
                            InstallPass.Pass4, returnCode,
                            ref error) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    ///////////////////////////////////////////////////////////

                    //
                    // HACK: Always create new lists of file names, so full
                    //       state can be verified in pass 5.
                    //
                    rollbackFileNames = new StringList();

                    ///////////////////////////////////////////////////////////

                    if (!rollback)
                        return ReturnCode.Ok;

                    ///////////////////////////////////////////////////////////

                    Guid id = evaluateClientData.Id;

                    if (id.Equals(Guid.Empty))
                    {
                        error = String.Format(
                            "cannot rollback files, context {0} missing " +
                            "unique identifier",
                            Utility.FormatWrapOrNull(evaluateClientData));

                        return ReturnCode.Error;
                    }

                    ///////////////////////////////////////////////////////////

                    StringList targetDirectories = FileOps.GetDirectoryNames(
                        targetFileNames, ref error);

                    if (targetDirectories == null)
                        return ReturnCode.Error;

                    targetDirectories.Sort(); /* O(N log N) */
                    targetDirectories.Reverse(); /* O(N) */

                    ///////////////////////////////////////////////////////////

                    Result localError; /* REUSED */

                    ///////////////////////////////////////////////////////////

                    foreach (string targetFileName in targetFileNames)
                    {
                        if (String.IsNullOrEmpty(targetFileName))
                            continue;

                        localError = null;

                        if (DeleteFileForPass4(targetFileName,
                                ref localError) != ReturnCode.Ok)
                        {
                            if (HasFlags(InstallFlags.StopRollbackOnError))
                            {
                                error = localError;
                                return ReturnCode.Error;
                            }
                            else
                            {
                                Utility.Complain(interpreter,
                                    ReturnCode.Error, localError);
                            }
                        }
                    }

                    ///////////////////////////////////////////////////////////

                    //
                    // HACK: At this point, there are no longer any "target"
                    //       files because they have all been "rolled back"
                    //       (i.e. deleted); therefore, clear the list of
                    //       backup file names now.
                    //
                    targetFileNames.Clear();

                    ///////////////////////////////////////////////////////////

                    foreach (string targetDirectory in targetDirectories)
                    {
                        if (String.IsNullOrEmpty(targetDirectory))
                            continue;

                        localError = null;

                        if (DeleteDirectoryForPass4(targetDirectory, false,
                                ref localError) != ReturnCode.Ok)
                        {
                            if (HasFlags(InstallFlags.StopRollbackOnError))
                            {
                                error = localError;
                                return ReturnCode.Error;
                            }
                            else
                            {
                                Utility.Complain(interpreter,
                                    ReturnCode.Error, localError);
                            }
                        }
                    }

                    ///////////////////////////////////////////////////////////

                    foreach (string backupFileName in backupFileNames)
                    {
                        if (String.IsNullOrEmpty(backupFileName))
                            continue;

                        localError = null;

                        if (RollbackFileForPass4(backupFileName, id,
                                ref localError) != ReturnCode.Ok)
                        {
                            if (HasFlags(InstallFlags.StopRollbackOnError))
                            {
                                error = localError;
                                return ReturnCode.Error;
                            }
                            else
                            {
                                Utility.Complain(interpreter,
                                    ReturnCode.Error, localError);
                            }
                        }
                    }

                    ///////////////////////////////////////////////////////////

                    //
                    // HACK: At this point, there are no longer any "backup"
                    //       files because they have all been "rolled back"
                    //       to their original names; therefore, clear the
                    //       list of backup file names now.
                    //
                    backupFileNames.Clear();

                    ///////////////////////////////////////////////////////////

                    return returnCode;
                }
            }

            ///////////////////////////////////////////////////////////////////
            // Pass #5, CLEANUP                                              //
            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// Performs the pass5.
            /// </summary>
            /// <param name="returnCode">
            /// The return code.
            /// </param>
            /// <param name="error">
            /// Upon failure, receives information about the error that was
            /// encountered.
            /// </param>
            /// <returns>
            /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
            /// <see cref="ReturnCode" /> value that indicates the type of
            /// failure.
            /// </returns>
            public ReturnCode PerformPass5( /* CORE */
                ReturnCode returnCode, /* in */
                ref Result error       /* in, out */
                )
            {
                CheckDisposed();

                lock (syncRoot) /* TRANSACTIONAL */
                {
                    if (VerifyState(
                            InstallPass.Pass5, returnCode,
                            ref error) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    ///////////////////////////////////////////////////////////

                    if (MaybeEvaluateManifestScripts(
                            InstallPass.Pass5, returnCode,
                            ref error) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    ///////////////////////////////////////////////////////////

                    if (rollback)
                        return ReturnCode.Ok;

                    ///////////////////////////////////////////////////////////

                    if (HasFlags(InstallFlags.KeepBackupFiles))
                        return ReturnCode.Ok;

                    ///////////////////////////////////////////////////////////

                    Result localError; /* REUSED */

                    ///////////////////////////////////////////////////////////

                    foreach (string backupFileName in backupFileNames)
                    {
                        if (String.IsNullOrEmpty(backupFileName))
                            continue;

                        localError = null;

                        if (DeleteFileForPass5(backupFileName,
                                ref localError) != ReturnCode.Ok)
                        {
                            Utility.Complain(interpreter,
                                ReturnCode.Error, localError);
                        }
                    }

                    ///////////////////////////////////////////////////////////

                    //
                    // HACK: At this point, there are no longer any "backup"
                    //       files because they have all been deleted after
                    //       successful completion of the install; therefore,
                    //       clear the list of backup file names now.
                    //
                    backupFileNames.Clear();

                    ///////////////////////////////////////////////////////////

                    return returnCode;
                }
            }

            ///////////////////////////////////////////////////////////////////
            // Pass #6, POST-INSTALL                                         //
            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// Performs the pass6.
            /// </summary>
            /// <param name="returnCode">
            /// The return code.
            /// </param>
            /// <param name="error">
            /// Upon failure, receives information about the error that was
            /// encountered.
            /// </param>
            /// <returns>
            /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
            /// <see cref="ReturnCode" /> value that indicates the type of
            /// failure.
            /// </returns>
            public ReturnCode PerformPass6( /* CORE */
                ReturnCode returnCode, /* in */
                ref Result error       /* in, out */
                )
            {
                CheckDisposed();

                lock (syncRoot) /* TRANSACTIONAL */
                {
                    if (VerifyState(
                            InstallPass.Pass6, returnCode,
                            ref error) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    ///////////////////////////////////////////////////////////

                    if (MaybeEvaluateManifestScripts(
                            InstallPass.Pass6, returnCode,
                            ref error) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    ///////////////////////////////////////////////////////////

                    return returnCode;
                }
            }
            #endregion

            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// Builds the result.
            /// </summary>
            /// <param name="returnCode">
            /// The return code.
            /// </param>
            /// <param name="errors">
            /// The errors.
            /// </param>
            /// <returns>
            /// The result produced by the operation.
            /// </returns>
            public StringList BuildResult( /* CORE */
                ReturnCode returnCode, /* in */
                ResultList errors      /* in: OPTIONAL */
                )
            {
                CheckDisposed();

                lock (syncRoot) /* TRANSACTIONAL */
                {
                    StringList result = new StringList();

                    result.Add("returnCode");
                    result.Add(returnCode.ToString());

                    if (errors != null)
                    {
                        result.Add("errors");
                        result.Add(errors.ToString());
                    }

                    result.Add("elapsed");
                    result.Add(GetElapsed().ToString());

                    result.Add("rollback");
                    result.Add(rollback.ToString());

                    if (targetDirectory != null)
                    {
                        result.Add("targetDirectory");
                        result.Add(targetDirectory);
                    }

                    if (HasFlags(InstallFlags.VerboseResult))
                    {
                        if (manifestFileNames != null)
                        {
                            result.Add("manifestFileNames");
                            result.Add(manifestFileNames.ToString());
                        }

                        if (sourceFileNames != null)
                        {
                            result.Add("sourceFileNames");
                            result.Add(sourceFileNames.ToString());
                        }
                    }

                    if (relativeFileNames != null)
                    {
                        result.Add("relativeFileNames");
                        result.Add(relativeFileNames.ToString());
                    }

                    if (existingFileNames != null)
                    {
                        result.Add("existingFileNames");
                        result.Add(existingFileNames.ToString());
                    }

                    if (backupFileNames != null)
                    {
                        result.Add("backupFileNames");
                        result.Add(backupFileNames.ToString());
                    }

                    if (HasFlags(InstallFlags.VerboseResult))
                    {
                        if (targetFileNames != null)
                        {
                            result.Add("targetFileNames");
                            result.Add(targetFileNames.ToString());
                        }
                    }

                    if (rollbackFileNames != null)
                    {
                        result.Add("rollbackFileNames");
                        result.Add(rollbackFileNames.ToString());
                    }

                    return result;
                }
            }
            #endregion

            ///////////////////////////////////////////////////////////////////

            #region IDisposable Members
            /// <summary>
            /// Releases the resources used by this instance.
            /// </summary>
#if OBFUSCATION
            [Obfuscation(Feature = "renaming")]
#endif
            public void Dispose()
            {
                Dispose(true);
                GC.SuppressFinalize(this);
            }
            #endregion

            ///////////////////////////////////////////////////////////////////

            #region IDisposable "Pattern" Members
            /// <summary>
            /// Non-zero if this instance has been disposed.
            /// </summary>
            private bool disposed;
            /// <summary>
            /// Throws an exception if this instance has already been
            /// disposed.
            /// </summary>
            /// <exception cref="ObjectDisposedException">
            /// Thrown if this instance has already been disposed.
            /// </exception>
            private void CheckDisposed() /* throw */
            {
#if THROW_ON_DISPOSED
                if (disposed && Engine.IsThrowOnDisposed(interpreter, false))
                {
                    throw new ObjectDisposedException(
                        typeof(Installation).Name);
                }
#endif
            }

            ///////////////////////////////////////////////////////////////////

            /// <summary>
            /// Releases the resources used by this instance.
            /// </summary>
            /// <param name="disposing">
            /// The disposing.
            /// </param>
            private /* protected virtual */ void Dispose(
                bool disposing /* in */
                )
            {
                try
                {
                    if (!disposed)
                    {
                        if (disposing)
                        {
                            ////////////////////////////////////
                            // dispose managed resources here...
                            ////////////////////////////////////

                            lock (syncRoot) /* TRANSACTIONAL */
                            {
                                interpreter = null; /* NOT OWNED */
                                clientData = null; /* NOT OWNED */
                                sourceDirectory = null; /* NOT OWNED */
                                targetDirectory = null; /* NOT OWNED */
                                installFlags = InstallFlags.None;

                                ////////////////////////////////

                                evaluateClientData = null;

                                if (manifestFileNames != null)
                                {
                                    manifestFileNames.Clear();
                                    manifestFileNames = null;
                                }

                                if (sourceFileNames != null)
                                {
                                    sourceFileNames.Clear();
                                    sourceFileNames = null;
                                }

                                if (relativeFileNames != null)
                                {
                                    relativeFileNames.Clear();
                                    relativeFileNames = null;
                                }

                                if (existingFileNames != null)
                                {
                                    existingFileNames.Clear();
                                    existingFileNames = null;
                                }

                                if (backupFileNames != null)
                                {
                                    backupFileNames.Clear();
                                    backupFileNames = null;
                                }

                                if (targetFileNames != null)
                                {
                                    targetFileNames.Clear();
                                    targetFileNames = null;
                                }

                                rollback = false;

                                if (rollbackFileNames != null)
                                {
                                    rollbackFileNames.Clear();
                                    rollbackFileNames = null;
                                }
                            }
                        }

                        //////////////////////////////////////
                        // release unmanaged resources here...
                        //////////////////////////////////////
                    }
                }
                finally
                {
                    disposed = true;
                }
            }
            #endregion

            ///////////////////////////////////////////////////////////////////

            #region Destructor
            /// <summary>
            /// Finalizes an instance of the <see cref="Installation" />
            /// class.
            /// </summary>
            ~Installation()
            {
                Dispose(false);
            }
            #endregion
        }
#endif
        #endregion

        ///////////////////////////////////////////////////////////////////////

        #region TraceProxy Helper Class
        /// <summary>
        /// Wraps an underlying command or callback so that each execution can
        /// be traced.
        /// </summary>
        [ObjectId("26601ea9-103d-4b1b-91f3-2c2afa4edcc6")]
        private sealed class TraceProxy : IExecute
        {
            #region Private Data
            /// <summary>
            /// The execution callback wrapped by this proxy.
            /// </summary>
            private readonly ExecuteCallback callback;
            #endregion

            ///////////////////////////////////////////////////////////////////

            #region Public Constructors
            /// <summary>
            /// Constructs an instance of the <see cref="TraceProxy" /> class.
            /// </summary>
            /// <param name="callback">
            /// The execution callback to be invoked.
            /// </param>
            public TraceProxy(
                ExecuteCallback callback /* in */
                )
            {
                this.callback = callback;
            }
            #endregion

            ///////////////////////////////////////////////////////////////////

            #region IExecute Members
            /* Eagle._Components.Public.Delegates.ExecuteCallback */
            /// <summary>
            /// Executes the command and returns the result of the operation.
            /// </summary>
            /// <param name="interpreter">
            /// The interpreter in which the operation is being performed.
            /// </param>
            /// <param name="clientData">
            /// The extra data supplied by the caller, if any.
            /// </param>
            /// <param name="arguments">
            /// The list of arguments supplied to the command.
            /// </param>
            /// <param name="result">
            /// Upon return, receives the result of the operation, or an error
            /// message describing why it failed.
            /// </param>
            /// <returns>
            /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
            /// <see cref="ReturnCode" /> value that indicates the type of
            /// failure.
            /// </returns>
            public ReturnCode Execute( /* CORE */
                Interpreter interpreter, /* in */
                IClientData clientData,  /* in */
                ArgumentList arguments,  /* in */
                ref Result result        /* out */
                )
            {
                if (callback == null)
                {
                    result = "invalid underlying callback";
                    return ReturnCode.Error;
                }

                long entryId = 0;

                Helpers.Trace(
                    interpreter, clientData, arguments, ref entryId);

                ReturnCode code = callback(
                    interpreter, clientData, arguments, ref result);

                Helpers.Trace(
                    interpreter, clientData, arguments, code, result,
                    ref entryId);

                return code;
            }
            #endregion
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Traces the execution of a command.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        [MethodImpl(MethodImplOptions.NoInlining)]
        public static void Trace( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments   /* in */
            )
        {
            long entryId = 0;

            Trace(
                interpreter, clientData, arguments, null, null,
                ref entryId);
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Traces the execution of a command.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="entryId">
        /// On input, supplies the entry id; upon return, receives the updated
        /// value.
        /// </param>
        [MethodImpl(MethodImplOptions.NoInlining)]
        public static void Trace( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref long entryId         /* in, out */
            )
        {
            Trace(
                interpreter, clientData, arguments, null, null,
                ref entryId);
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Traces the execution of a command.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="returnCode">
        /// The return code.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <param name="entryId">
        /// On input, supplies the entry id; upon return, receives the updated
        /// value.
        /// </param>
        [MethodImpl(MethodImplOptions.NoInlining)]
        public static void Trace( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ReturnCode? returnCode,  /* in */
            Result result,           /* in */
            ref long entryId         /* in, out */
            )
        {
            IPluginData pluginData = null;

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData != null)
                pluginData = evaluateClientData.Plugin;

            IClientData rootClientData = SharedOps.GetRootClientData(
                clientData);

            bool allowNewLines = Configuration.DoesVariableExist(
                Constants.ConfigurationTraceNewLinesEnvVarName);

            string formatted = Utility.FormatCommandLogEntry(
                interpreter, pluginData, rootClientData, arguments,
                returnCode, result, 0, allowNewLines, ref entryId);

            CertificateTraceOps.DebugTrace(
                formatted, typeof(Helpers).Name,
                TracePriority.Highest); /* EXEMPT */

            if (evaluateClientData != null)
            {
                DateTime now = Utility.GetUtcNow();

                /* IGNORED */
                evaluateClientData.AppendToFile(
                    String.Format("Trace {0} {1}",
                    DataOps.FormatTimeStamp(now),
                    formatted));
            }
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Performs the expression to boolean operation.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="cultureInfo">
        /// The culture info.
        /// </param>
        /// <param name="text">
        /// The text.
        /// </param>
        /// <param name="errorInfo">
        /// The error info.
        /// </param>
        /// <param name="value">
        /// Upon return, receives the value.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode ExpressionToBoolean( /* CORE */
            Interpreter interpreter, /* in */
            CultureInfo cultureInfo, /* in */
            string text,             /* in */
            string errorInfo,        /* in */
            ref bool value,          /* out */
            ref Result error         /* out */
            )
        {
            ReturnCode code;
            Result localResult = null;

            code = interpreter.EvaluateExpressionWithErrorInfo(
                text, errorInfo, ref localResult);

            if (code != ReturnCode.Ok)
            {
                error = localResult;
                return code;
            }

            code = Value.GetBoolean6(
                localResult, ValueFlags.AnyNumberAnyRadixFast |
                ValueFlags.Fast, cultureInfo, ref value,
                ref localResult);

            if (code != ReturnCode.Ok)
            {
                error = localResult;
                return code;
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Conditionally sets the result to code.
        /// </summary>
        /// <param name="code">
        /// The code.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        public static void MaybeSetResultToCode( /* CORE */
            ReturnCode code,  /* in */
            ref Result result /* out */
            )
        {
            switch (code)
            {
                case ReturnCode.Ok:
                case ReturnCode.Return:
                case ReturnCode.Break:
                case ReturnCode.Continue:
                    {
                        result = code.ToString().ToLowerInvariant();
                        break;
                    }
            }
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Conditionally inserts the serious separators.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="list">
        /// On input, supplies the list; upon return, receives the updated
        /// value.
        /// </param>
        /// <param name="startIndex">
        /// The start index.
        /// </param>
        /// <param name="separator">
        /// The separator.
        /// </param>
        public static void MaybeInsertSeriousSeparators( /* CORE */
            Interpreter interpreter, /* in: OPTIONAL */
            IList<Argument> list,    /* in, out */
            int startIndex,          /* in */
            char separator           /* in */
            )
        {
            if (list == null)
                return;

            int width = Width.Default;
            int margin = Margin.Default;

            if (interpreter != null)
            {
                width = interpreter.OutputWidth;
                margin = interpreter.OutputMargin;

                if ((width > 0) &&
                    (margin > 0) && (margin < width))
                {
                    width -= margin;
                }
            }

            if (width <= 0)
                return;

            //
            // HACK: Use the format string "{1}" here to get
            //       the string for the argument value and,
            //       notably, not the name.
            //
            int length = Utility.GetTotalLength<Argument>(
                list, "{1}", startIndex, 2);

            if (width > length)
            {
                width = length;

                if (margin > 0)
                    width += margin;
            }

            StringBuilder builder = new StringBuilder();

            builder.AppendLine();
            builder.Append(separator, width);
            builder.AppendLine();

            int count = list.Count;

            for (int index = startIndex; index < count; index++)
            {
                string element = list[index]; /* CONVERSION */

                if (String.IsNullOrEmpty(element))
                    continue;

                if ((element.Length != 1) ||
                    (element[0] != Characters.FormFeed))
                {
                    continue;
                }

                list[index] = builder.ToString(); /* CONVERSION */
            }
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Builds the output.
        /// </summary>
        /// <param name="list">
        /// The list.
        /// </param>
        /// <param name="startIndex">
        /// The start index.
        /// </param>
        /// <param name="builder">
        /// On input, supplies the builder; upon return, receives the updated
        /// value.
        /// </param>
        public static void BuildOutput( /* CORE */
            IList<Argument> list,     /* in */
            int startIndex,           /* in */
            ref StringBuilder builder /* in, out */
            )
        {
            if (list == null)
                return;

            int count = list.Count;

            for (int index = startIndex; index < count; index++)
            {
                string element = list[index]; /* CONVERSION */

                if (String.IsNullOrEmpty(element))
                    continue;

                if (builder == null)
                    builder = new StringBuilder();

                builder.Append(element);
            }
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Writes the builder.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="builder">
        /// The builder.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode WriteBuilder( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            StringBuilder builder,   /* in */
            ref Result result        /* out */
            )
        {
            if (builder == null)
            {
                result = null;
                return ReturnCode.Ok;
            }

            if (!Configuration.DoesVariableExist(
                    Constants.WriteWithoutFailEnvVarName))
            {
                result = builder;
                return ReturnCode.Ok;
            }

            bool viaHost = true;

            if (Configuration.DoesVariableExist(
                    Constants.NoWriteWithoutFailViaHostEnvVarName))
            {
                viaHost = false;
            }

            IHost host = null;

            if (viaHost)
            {
                try
                {
                    //
                    // HACK: Attempt to grab the interpreter
                    //       host.  In theory, this can throw
                    //       an exception; however, it should
                    //       not.  If it does, something may
                    //       be seriously awry (e.g. disposed
                    //       interpreter, etc).  Just ignore
                    //       those types of problems and keep
                    //       going.
                    //
                    host = interpreter.Host; /* throw */
                }
#if DEBUG || FORCE_TRACE
                catch (Exception e)
#else
                catch (Exception)
#endif
                {
#if DEBUG || FORCE_TRACE
                    CertificateTraceOps.DebugTrace(
                        e, typeof(Helpers).Name,
                        TracePriority.Highest);
#endif
                }
            }

            result = builder;

#if TEST && WINFORMS
            SandboxOps.MaybeReportStatus(
                interpreter, clientData, result, true,
                false, true);
#endif

            /* NO RESULT */
            Utility.WriteWithoutFail(
                host as IDebugHost, result, viaHost);

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets the identifier name.
        /// </summary>
        /// <param name="value">
        /// The value.
        /// </param>
        /// <returns>
        /// The identifier name produced by the operation.
        /// </returns>
        private static string GetIdentifierName( /* CORE */
            object value /* in */
            )
        {
            IIdentifierName identifierName = value as IIdentifierName;

            if (identifierName == null)
                return null;

            return identifierName.Name;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets the public key token.
        /// </summary>
        /// <param name="fileName">
        /// The file name.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// The public key token produced by the operation.
        /// </returns>
        public static byte[] GetPublicKeyToken( /* CORE */
            string fileName, /* in */
            ref Result error /* out */
            )
        {
            try
            {
                AssemblyName assemblyName = AssemblyName.GetAssemblyName(
                    fileName); /* throw */

                byte[] publicKeyToken = assemblyName.GetPublicKeyToken();

                if (publicKeyToken == null)
                {
                    error = String.Format(
                        "file {0} is missing public key token",
                        Utility.FormatWrapOrNull(fileName));
                }

                return publicKeyToken;
            }
            catch (Exception e)
            {
                error = e;
                return null;
            }
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Looks up the identifier.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="kind">
        /// The kind.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="name">
        /// On input, supplies the name; upon return, receives the updated
        /// value.
        /// </param>
        /// <param name="errors">
        /// On input, supplies the errors; upon return, receives the updated
        /// value.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode LookupIdentifier( /* CORE */
            Interpreter interpreter, /* in */
            IdentifierKind kind,     /* in */
            ArgumentList arguments,  /* in */
            ref string name,         /* in, out */
            ref ResultList errors    /* in, out */
            )
        {
            if (interpreter == null)
            {
                if (errors == null)
                    errors = new ResultList();

                errors.Add("invalid interpreter");
                return ReturnCode.Error;
            }

            IIdentifier identifier = null;
            Result error = null;

            if (interpreter.GetIdentifier(
                    kind, name, arguments, LookupFlags.Default,
                    ref identifier, ref error) == ReturnCode.Ok)
            {
                name = GetIdentifierName(identifier);
                return ReturnCode.Ok;
            }
            else
            {
                if (error != null)
                {
                    if (errors == null)
                        errors = new ResultList();

                    errors.Add(error);
                }

                return ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets the snippet flags.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="cultureInfo">
        /// The culture info.
        /// </param>
        /// <param name="argumentOffset">
        /// The argument offset.
        /// </param>
        /// <param name="optional">
        /// The optional.
        /// </param>
        /// <param name="snippetFlags">
        /// On input, supplies the snippet flags; upon return, receives the
        /// updated value.
        /// </param>
        /// <param name="lookupFlags">
        /// On input, supplies the lookup flags; upon return, receives the
        /// updated value.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode GetSnippetFlags( /* CORE */
            Interpreter interpreter,       /* in: OPTIONAL */
            ArgumentList arguments,        /* in */
            CultureInfo cultureInfo,       /* in: OPTIONAL */
            int argumentOffset,            /* in */
            bool optional,                 /* in */
            ref SnippetFlags snippetFlags, /* in, out */
            ref LookupFlags lookupFlags,   /* in, out */
            ref Result error               /* out */
            )
        {
            if (arguments == null)
            {
                if (optional)
                {
                    return ReturnCode.Ok;
                }
                else
                {
                    error = "invalid argument list";
                    return ReturnCode.Error;
                }
            }

            int argumentCount = arguments.Count;

            if ((argumentOffset < 0) ||
                (argumentOffset >= argumentCount))
            {
                if (optional)
                {
                    return ReturnCode.Ok;
                }
                else
                {
                    if (argumentCount > 0)
                    {
                        error = String.Format(
                            "invalid argument offset: " +
                            "must be between zero and {0}",
                            argumentCount - 1);
                    }
                    else
                    {
                        error = "invalid argument offset";
                    }

                    return ReturnCode.Error;
                }
            }

            SnippetFlags localSnippetFlags = snippetFlags;
            string enumString; /* REUSED */
            object enumValue; /* REUSED */

            if (argumentCount > argumentOffset)
            {
                enumString = arguments[argumentOffset];

                if (String.IsNullOrEmpty(enumString))
                    enumString = null;

                if (enumString != null)
                {
                    enumValue = Utility.TryParseFlagsEnum(
                        interpreter, typeof(SnippetFlags),
                        localSnippetFlags.ToString(),
                        enumString, cultureInfo, true,
                        true, true, ref error);

                    if (!(enumValue is SnippetFlags))
                        return ReturnCode.Error;

                    localSnippetFlags = (SnippetFlags)enumValue;
                }
            }

            LookupFlags localLookupFlags = lookupFlags;

            argumentOffset++;

            if (argumentCount > argumentOffset)
            {
                enumString = arguments[argumentOffset];

                if (String.IsNullOrEmpty(enumString))
                    enumString = null;

                if (enumString != null)
                {
                    enumValue = Utility.TryParseFlagsEnum(
                        interpreter, typeof(LookupFlags),
                        localLookupFlags.ToString(),
                        enumString, cultureInfo, true,
                        true, true, ref error);

                    if (!(enumValue is LookupFlags))
                        return ReturnCode.Error;

                    localLookupFlags = (LookupFlags)enumValue;
                }
            }

            snippetFlags = localSnippetFlags;
            lookupFlags = localLookupFlags;

            return ReturnCode.Ok;
        }

