        #region Dead Code
#if DEAD_CODE
        /// <summary>
        /// Restores the swap command.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="commandName">
        /// The command name.
        /// </param>
        /// <param name="evaluateClientData">
        /// The evaluate client data.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="lookupFlags">
        /// The lookup flags.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        private static ReturnCode RestoreSwapCommand( /* CORE */
            Interpreter interpreter,               /* in */
            string commandName,                    /* in */
            EvaluateClientData evaluateClientData, /* in: OPTIONAL */
            IClientData clientData,                /* in: OPTIONAL */
            LookupFlags lookupFlags,               /* in */
            ref Result error                       /* out */
            )
        {
            if (interpreter == null)
            {
                error = "invalid interpreter";
                return ReturnCode.Error;
            }

            long token = 0; /* NOT USED */
            ICommand command = null;

            if (interpreter.GetCommand(
                    commandName, lookupFlags, ref token,
                    ref command, ref error) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            return RestoreSwapCommand(
                interpreter, command, evaluateClientData,
                clientData, ref error);
        }
#endif
        #endregion

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Restores the swap command.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="command">
        /// The underlying command to be wrapped.
        /// </param>
        /// <param name="evaluateClientData">
        /// The evaluate client data.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode RestoreSwapCommand( /* CORE */
            Interpreter interpreter,               /* in */
            ICommand command,                      /* in */
            EvaluateClientData evaluateClientData, /* in: OPTIONAL */
            IClientData clientData,                /* in: OPTIONAL */
            ref Result error                       /* out */
            )
        {
            if (interpreter == null)
            {
                error = "invalid interpreter";
                return ReturnCode.Error;
            }

            bool success = false;
            long token = 0;
            Result result; /* REUSED */

            try
            {
                result = null;

                if (interpreter.AddCommand(
                        command, clientData, ref token,
                        ref result) != ReturnCode.Ok)
                {
                    error = result;
                    return ReturnCode.Error;
                }

                //
                // NOTE: Realistically, this conditional should
                //       always be true.  Otherwise, the caller
                //       can never (easily) figure out which of
                //       the command tokens we added.
                //
                if (evaluateClientData != null)
                {
                    //
                    // NOTE: Attempt to save the added command
                    //       token atomically with the addition.
                    //       If that fails for any reason, the
                    //       command added above will be removed
                    //       below, within the "finally" block,
                    //       as needed.
                    //
                    result = null;

                    if (evaluateClientData.SaveSwapToken(
                            token, ref result) != ReturnCode.Ok)
                    {
                        error = result;
                        return ReturnCode.Error;
                    }
                }

                success = true;
                return ReturnCode.Ok;
            }
            finally
            {
                if (!success && (token != 0))
                {
                    result = null;

                    if (interpreter.RemoveCommand(
                            token, clientData,
                            ref result) != ReturnCode.Ok)
                    {
                        Utility.Complain(
                            interpreter, ReturnCode.Error,
                            result);
                    }
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Makes the script name.
        /// </summary>
        /// <param name="text">
        /// The text.
        /// </param>
        /// <param name="signature">
        /// The signature.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// The script name produced by the operation.
        /// </returns>
        public static string MakeScriptName( /* CORE */
            string text,      /* in */
            byte[] signature, /* in */
            ref Result error  /* out */
            )
        {
            byte[] bytes = Utility.HashStringAndOrBytes(
                text, signature, EncodingType.Script, ref error);

            if (bytes == null)
                return null;

            return DataOps.FormatHexadecimal(bytes);
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Evaluates the for each file.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="fileNames">
        /// The file names.
        /// </param>
        /// <param name="pattern">
        /// The pattern.
        /// </param>
        /// <param name="text">
        /// The text.
        /// </param>
        /// <param name="varName">
        /// The var name.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode EvaluateForEachFile( /* CORE */
            Interpreter interpreter,       /* in */
            IClientData clientData,        /* in */
            IEnumerable<string> fileNames, /* in */
            string pattern,                /* in */
            string text,                   /* in */
            string varName,                /* in */
            ref Result error               /* out */
            )
        {
            if (interpreter == null)
            {
                error = "invalid interpreter";
                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                error = "missing context clientData";
                return ReturnCode.Error;
            }

            if (fileNames == null)
            {
                error = "invalid file names";
                return ReturnCode.Error;
            }

            StringList localFileNames = new StringList(fileNames);

            if (localFileNames.Count == 0)
            {
                error = "no file names";
                return ReturnCode.Error;
            }

            localFileNames.Sort(); /* O(N log N) */

            using (EvaluateClientData newEvaluateClientData =
                    new EvaluateClientData(evaluateClientData))
            {
                /* IGNORED */
                newEvaluateClientData.AttachTo(evaluateClientData);

                /* NO RESULT */
                newEvaluateClientData.DoNotModifyInterpreter();

                ReturnCode code;
                ResultList errors = null;

                try
                {
                    int iterationLimit = interpreter.IterationLimit;
                    int iterationCount = 0;

                    foreach (string localFileName in localFileNames)
                    {
                        if (String.IsNullOrEmpty(localFileName))
                            continue;

                        string fileNameOnly = Path.GetFileName(
                            localFileName);

                        if (String.IsNullOrEmpty(fileNameOnly))
                            continue;

                        if ((pattern != null) && !Parser.StringMatch(
                                interpreter, fileNameOnly, 0, pattern,
                                0, false))
                        {
                            continue;
                        }

                        Result localResult; /* REUSED */

                        if (text != null)
                        {
                            if (varName != null)
                            {
                                localResult = null;

                                if (evaluateClientData.SetVariableValue(
                                        interpreter, varName, localFileName,
                                        ref localResult) != ReturnCode.Ok)
                                {
                                    if (errors == null)
                                        errors = new ResultList();

                                    if (localResult != null)
                                    {
                                        errors.Add(localResult);
                                    }
                                    else
                                    {
                                        errors.Add(String.Format(
                                            "could not set loop variable {0}",
                                            Utility.FormatWrapOrNull(
                                            varName)));
                                    }

                                    break;
                                }
                            }

                            localResult = null;

                            if (interpreter.EvaluateScript(
                                    text, ref localResult) != ReturnCode.Ok)
                            {
                                if (errors == null)
                                    errors = new ResultList();

                                if (localResult != null)
                                {
                                    errors.Add(String.Format(
                                        "error for script block {0}",
                                        Utility.FormatWrapOrNull(
                                        localFileName)));

                                    errors.Add(localResult);
                                }
                                else
                                {
                                    errors.Add(String.Format(
                                        "null error for script block {0}",
                                        Utility.FormatWrapOrNull(
                                        localFileName)));
                                }

                                break;
                            }
                        }
                        else
                        {
                            //
                            // NOTE: Skip over all non-script files as they
                            //       cannot be evaluated (obviously?).
                            //
                            if (!SharedOps.IsScriptFileName(localFileName))
                                continue;

                            //
                            // HACK: There is no point in attempting (and
                            //       failing) to evaluate a script file
                            //       without a signature file.  Skip it,
                            //       just in case directories exist that
                            //       contain signed and unsigned script
                            //       files.
                            //
                            string signatureFileName =
                                DataOps.FormatSignatureFileName(localFileName);

                            if (!File.Exists(signatureFileName))
                                continue;

                            using (EvaluateClientData evaluateClientData2 =
                                    EvaluateClientData.ForNewScript(
                                        newEvaluateClientData, interpreter,
                                        localFileName, ref errors))
                            {
                                //
                                // BUGFIX: The required version was ALWAYS
                                //         intended to be checked on a
                                //         per-file basis.
                                //
                                /* IGNORED */
                                EvaluateClientData.ResetRequiredVersion(
                                    evaluateClientData2, true);

                                localResult = null;

                                if (ScriptOps.EvaluateFile(
                                        evaluateClientData2,
                                        ref localResult) != ReturnCode.Ok)
                                {
                                    if (errors == null)
                                        errors = new ResultList();

                                    if (localResult != null)
                                    {
                                        errors.Add(String.Format(
                                            "error for script file {0}",
                                            Utility.FormatWrapOrNull(
                                            localFileName)));

                                        errors.Add(localResult);
                                    }
                                    else
                                    {
                                        errors.Add(String.Format(
                                            "null error for script file {0}",
                                            Utility.FormatWrapOrNull(
                                            localFileName)));
                                    }

                                    break;
                                }
                            }
                        }

                        if ((iterationLimit != Limits.Unlimited) &&
                            (++iterationCount > iterationLimit))
                        {
                            if (errors == null)
                                errors = new ResultList();

                            errors.Add(String.Format(
                                "iteration limit {0} exceeded",
                                iterationLimit));

                            break;
                        }
                    }
                }
                catch (Exception e)
                {
                    if (errors == null)
                        errors = new ResultList();

                    errors.Add(e);
                }
                finally
                {
                    if (errors != null)
                    {
                        error = errors;
                        code = ReturnCode.Error;
                    }
                    else
                    {
                        code = ReturnCode.Ok;
                    }
                }

                return code;
            }
        }

