        /// <summary>
        /// Gets the guid.
        /// </summary>
        /// <param name="cultureInfo">
        /// The culture info.
        /// </param>
        /// <param name="value">
        /// The value.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// The guid produced by the operation.
        /// </returns>
        public static Guid? GetGuid( /* CORE */
            CultureInfo cultureInfo, /* in */
            string value,            /* in */
            ref Result error         /* out */
            )
        {
            Guid id = Guid.Empty;

            if (Value.GetGuid(
                    value, cultureInfo, ref id,
                    ref error) != ReturnCode.Ok)
            {
                return null;
            }

            if (id.Equals(Guid.Empty))
            {
                error = "empty guid value not allowed";
                return null;
            }

            return id;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets the guid list.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="cultureInfo">
        /// The culture info.
        /// </param>
        /// <param name="value">
        /// The value.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// The guid list produced by the operation.
        /// </returns>
        public static GuidList GetGuidList( /* CORE */
            Interpreter interpreter, /* in */
            CultureInfo cultureInfo, /* in */
            string value,            /* in */
            ref Result error         /* out */
            )
        {
            StringList list = null;

            if (Parser.SplitList(
                    interpreter, value, 0, Length.Invalid,
                    true, ref list, ref error) != ReturnCode.Ok)
            {
                return null;
            }

            GuidList result = new GuidList();
            string anyValid = Characters.Asterisk.ToString();

            foreach (string element in list)
            {
                if (element == null)
                    continue;

                if (Utility.SystemStringEquals(
                        element, anyValid))
                {
                    result[Guid.Empty] = null;
                    continue;
                }

                Guid id = Guid.Empty;

                if (Value.GetGuid(
                        element, cultureInfo, ref id,
                        ref error) != ReturnCode.Ok)
                {
                    return null;
                }

                if (id.Equals(Guid.Empty))
                {
                    error = "empty guid value not allowed";
                    return null;
                }

                result[id] = null;
            }

            return result;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets the ticket scope id.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="scope">
        /// The scope.
        /// </param>
        /// <param name="id">
        /// Upon return, receives the id.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see langword="true" /> on success; otherwise,
        /// <see langword="false" />.
        /// </returns>
        private static bool GetTicketScopeId( /* CORE */
            Interpreter interpreter, /* in */
            TicketScope scope,       /* in */
            ref long id,             /* out */
            ref Result error         /* out */
            )
        {
            switch (scope)
            {
                case TicketScope.Process:
                    {
                        id = Utility.GetCurrentProcessId();
                        return true;
                    }
                case TicketScope.AppDomain:
                    {
                        id = Utility.GetCurrentAppDomainId();
                        return true;
                    }
                case TicketScope.Thread:
                    {
                        id = Utility.GetCurrentThreadId();
                        return true;
                    }
                case TicketScope.Interpreter:
                    {
                        if (interpreter == null)
                        {
                            error = "invalid interpreter";
                            return false;
                        }

                        id = interpreter.IdNoThrow;
                        return true;
                    }
                case TicketScope.Context:
                    {
                        if (interpreter == null)
                        {
                            error = "invalid interpreter";
                            return false;
                        }

                        Result result = null;

                        if (interpreter.GetContext(
                                ref result) != ReturnCode.Ok)
                        {
                            error = result;
                            return false;
                        }

                        id = (long)result.Value;
                        return true;
                    }
                default:
                    {
                        error = String.Format(
                            "unsupported ticket scope {0}", scope);

                        return false;
                    }
            }
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Formats the ticket.
        /// </summary>
        /// <param name="policyType">
        /// The policy type.
        /// </param>
        /// <param name="scope">
        /// The scope.
        /// </param>
        /// <param name="scopeId">
        /// The scope id.
        /// </param>
        /// <param name="ticketId">
        /// The ticket id.
        /// </param>
        /// <returns>
        /// The ticket produced by the operation.
        /// </returns>
        private static string FormatTicket( /* CORE */
            PolicyType policyType, /* in */
            TicketScope scope,     /* in */
            long scopeId,          /* in */
            Guid? ticketId         /* in */
            )
        {
            StringBuilder builder = new StringBuilder();

            builder.AppendFormat(
                Constants.TicketFormat, policyType, scope,
                scopeId);

            if (ticketId != null)
            {
                builder.Append(Characters.Space);
                builder.Append(ticketId);
            }

            return builder.ToString();
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Creates the ticket.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="encoding">
        /// The encoding.
        /// </param>
        /// <param name="policyType">
        /// The policy type.
        /// </param>
        /// <param name="scope">
        /// The scope.
        /// </param>
        /// <param name="key">
        /// The key.
        /// </param>
        /// <param name="ticketId">
        /// The ticket id.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode CreateTicket( /* CORE */
            Interpreter interpreter, /* in */
            Encoding encoding,       /* in */
            PolicyType policyType,   /* in */
            TicketScope scope,       /* in */
            byte[] key,              /* in */
            Guid? ticketId,          /* in */
            ref Result result        /* out */
            )
        {
            if (encoding == null)
            {
                result = "invalid encoding";
                return ReturnCode.Error;
            }

            long scopeId = 0;

            if (!GetTicketScopeId(
                    interpreter, scope, ref scopeId, ref result))
            {
                return ReturnCode.Error;
            }

            byte[] data = encoding.GetBytes(FormatTicket(
                policyType, scope, scopeId, ticketId));

#if NATIVE
            if (Utility.IsWindowsOperatingSystem())
            {
                if (ProtectOps.Rc4EncryptOrDecrypt(key,
                        true, ref data, ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }
            }
            else
#endif
            {
                if (KeyFile.RC4(
                        key, data, 0, ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }
            }

            result = DataOps.FormatHexadecimal(data, false);
            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Validates the ticket.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="cultureInfo">
        /// The culture info.
        /// </param>
        /// <param name="encoding">
        /// The encoding.
        /// </param>
        /// <param name="policyType">
        /// The policy type.
        /// </param>
        /// <param name="scope">
        /// The scope.
        /// </param>
        /// <param name="key">
        /// The key.
        /// </param>
        /// <param name="ticketId">
        /// The ticket id.
        /// </param>
        /// <param name="value">
        /// On input, supplies the value; upon return, receives the updated
        /// value.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode ValidateTicket( /* CORE */
            Interpreter interpreter, /* in */
            CultureInfo cultureInfo, /* in */
            Encoding encoding,       /* in */
            PolicyType policyType,   /* in */
            TicketScope scope,       /* in */
            byte[] key,              /* in */
            Guid? ticketId,          /* in */
            ref string value,        /* in, out */
            ref Result error         /* out */
            )
        {
            if (encoding == null)
            {
                error = "invalid encoding";
                return ReturnCode.Error;
            }

            byte[] data = null;

            if (Utility.GetBytesFromString(value,
                    cultureInfo, ref data, ref error) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

#if NATIVE
            if (Utility.IsWindowsOperatingSystem())
            {
                if (ProtectOps.Rc4EncryptOrDecrypt(key,
                        false, ref data, ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }
            }
            else
#endif
            {
                if (KeyFile.RC4(
                        key, data, 0, ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }
            }

            long scopeId = 0;

            if (!GetTicketScopeId(
                    interpreter, scope, ref scopeId, ref error))
            {
                return ReturnCode.Error;
            }

            value = encoding.GetString(data);

            if (!Utility.SystemStringEquals(
                    value, FormatTicket(policyType, scope, scopeId,
                    ticketId)))
            {
                error = "ticket could not be validated";
                return ReturnCode.Error;
            }

            return ReturnCode.Ok;
        }

