        /// <summary>
        /// Gets the license certificate.
        /// </summary>
        /// <param name="id">
        /// The id.
        /// </param>
        /// <param name="certificate">
        /// Upon return, receives the certificate.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see langword="true" /> on success; otherwise,
        /// <see langword="false" />.
        /// </returns>
        public static bool GetLicenseCertificate( /* CORE */
            Guid id,                      /* in */
            ref ICertificate certificate, /* out */
            ref Result error              /* out */
            )
        {
            if (!id.Equals(Guid.Empty))
            {
                certificate = LicenseState.GetCertificate(id, ref error);

                if (certificate == null)
                    return false;
            }
            else
            {
                certificate = LicenseState.GetCertificate();

                if (certificate == null)
                {
                    error = String.Format(
                        "invalid license certificate for {0}",
                        Utility.FormatWrapOrNull(
                            Constants.HarpyAssemblySimpleName));

                    return false;
                }
            }

            return true;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Determines whether the change license property is permitted.
        /// </summary>
        /// <param name="name">
        /// The name.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see langword="true" /> if the condition is satisfied; otherwise,
        /// <see langword="false" />.
        /// </returns>
#if CERTIFICATE_PLUGIN && PLUGIN_COMMANDS
        private static bool CanChangeLicenseProperty(
            string name,     /* in */
            ref Result error /* out */
            )
        {
            if (String.IsNullOrEmpty(name))
            {
                error = "invalid license property name";
                return false;
            }

            StringDictionary dictionary = Constants.ChangeLicensePropertyNames;

            if (dictionary == null)
                return true; /* NOTE: Everything allowed? */

            if (!dictionary.ContainsKey(name))
            {
                error = "unsupported license property";
                return false;
            }

            return true;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Conditionally mutates the flags key and value.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="cultureInfo">
        /// The culture info.
        /// </param>
        /// <param name="flagsKey">
        /// On input, supplies the flags key; upon return, receives the
        /// updated value.
        /// </param>
        /// <param name="value">
        /// On input, supplies the value; upon return, receives the updated
        /// value.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see langword="true" /> on success; otherwise,
        /// <see langword="false" />.
        /// </returns>
        private static bool MaybeMutateFlagsKeyAndValue(
            Interpreter interpreter, /* in */
            CultureInfo cultureInfo, /* in */
            ref long flagsKey,       /* in, out */
            ref object value,        /* in, out */
            ref Result error         /* out */
            )
        {
            if (!(value is string))
            {
                error = "flags value is not a string";
                return false;
            }

            StringList list = null;

            if (Parser.SplitList(
                    interpreter, (string)value, 0, Length.Invalid,
                    true, ref list, ref error) != ReturnCode.Ok)
            {
                return false;
            }

            if (list.Count == 0)
            {
                flagsKey = Utility.DefaultAttributeFlagsKey();
                value = String.Empty;

                return true;
            }

            if (list.Count == 1)
            {
                flagsKey = Utility.DefaultAttributeFlagsKey();
                value = list[0];

                return true;
            }

            if (list.Count == 2)
            {
                if (Value.GetWideInteger2(list[0],
                        ValueFlags.AnyWideInteger, cultureInfo,
                        ref flagsKey, ref error) != ReturnCode.Ok)
                {
                    return false;
                }

                value = list[1];
                return true;
            }

            error = "flags value must have zero, one, or two elements";
            return false;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets the license properties.
        /// </summary>
        /// <param name="id">
        /// The id.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see langword="true" /> on success; otherwise,
        /// <see langword="false" />.
        /// </returns>
        public static bool GetLicenseProperties(
            Guid id,          /* in: NOT USED */
            ref Result result /* out */
            )
        {
            StringDictionary dictionary = Constants.ChangeLicensePropertyNames;

            if (dictionary != null)
            {
                result = new StringList(dictionary.Keys);
                return true;
            }
            else
            {
                result = "license properties unavailable";
                return false;
            }
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets the license property value.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="pluginData">
        /// The plugin data.
        /// </param>
        /// <param name="id">
        /// The id.
        /// </param>
        /// <param name="name">
        /// The name.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see langword="true" /> on success; otherwise,
        /// <see langword="false" />.
        /// </returns>
        public static bool GetLicensePropertyValue(
            Interpreter interpreter, /* in */
            IPluginData pluginData,  /* in */
            Guid id,                 /* in */
            string name,             /* in */
            ref Result result        /* out */
            )
        {
            if (!CanChangeLicenseProperty(name, ref result))
                return false;

            ICertificate certificate = null;

            if (!GetLicenseCertificate(id, ref certificate, ref result))
                return false;

            Type metadataType = typeof(ICertificate);
            object value;

            try
            {
                value = CommandOps.GetMetadataPropertyValue(
                    metadataType, name, certificate); /* throw */
            }
            catch (Exception e)
            {
                result = e;
                return false;
            }

            Result localResult = null;

            if (CommandOps.GetMetadataResult(
                    value, ref localResult) != ReturnCode.Ok)
            {
                return false;
            }

            /* IGNORED */
            CertificateIsolatedOps.MaybeFixupResult(
                interpreter, pluginData, localResult);

            result = localResult;
            return true;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Changes the license property value.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="pluginData">
        /// The plugin data.
        /// </param>
        /// <param name="id">
        /// The id.
        /// </param>
        /// <param name="name">
        /// The name.
        /// </param>
        /// <param name="value">
        /// The value.
        /// </param>
        /// <param name="cultureInfo">
        /// The culture info.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see langword="true" /> on success; otherwise,
        /// <see langword="false" />.
        /// </returns>
        public static bool ChangeLicensePropertyValue(
            Interpreter interpreter, /* in */
            IPluginData pluginData,  /* in */
            Guid id,                 /* in */
            string name,             /* in */
            object value,            /* in */
            CultureInfo cultureInfo, /* in: OPTIONAL */
            ref Result result        /* out */
            )
        {
            if (!CanChangeLicenseProperty(name, ref result))
                return false;

            ICertificate certificate = null;

            if (!GetLicenseCertificate(id, ref certificate, ref result))
                return false;

            Type metadataType = typeof(ICertificate);
            object newValue = value;

            if (CommandOps.GetMetadataValue(interpreter,
                    metadataType, certificate, name, cultureInfo,
                    ref newValue, ref result) != ReturnCode.Ok)
            {
                return false;
            }

            if (newValue is StringBuilder)
                newValue = newValue.ToString();

            if (newValue is string)
            {
                if (Utility.SystemStringEquals(name, "Features") ||
                    Utility.SystemStringEquals(name, "Restrictions"))
                {
                    long flagsKey = Utility.DefaultAttributeFlagsKey();

                    if (!MaybeMutateFlagsKeyAndValue(
                            interpreter, cultureInfo, ref flagsKey,
                            ref newValue, ref result))
                    {
                        return false;
                    }

                    object oldValue;

                    try
                    {
                        oldValue = CommandOps.GetMetadataPropertyValue(
                            metadataType, name, certificate); /* throw */
                    }
                    catch (Exception e)
                    {
                        result = e;
                        return false;
                    }

                    if (!(oldValue is string))
                    {
                        result = "certificate property value type mismatch";
                        return false;
                    }

                    string flags = null;

                    if (flagsKey == Utility.DefaultAttributeFlagsKey())
                    {
                        if (CertificateFlagOps.SimpleChange(
                                (string)oldValue, (string)newValue, ref flags,
                                ref result) != ReturnCode.Ok)
                        {
                            return false;
                        }
                    }
                    else
                    {
                        if (CertificateFlagOps.Change(
                                (string)oldValue, (string)newValue, flagsKey,
                                true, true, false, false, false, ref flags,
                                ref result) != ReturnCode.Ok)
                        {
                            return false;
                        }
                    }

                    newValue = flags;
                }
                else if (Utility.SystemStringEquals(name, "Quantity"))
                {
                    long quantity = 0;

                    if (!DataOps.TryParseQuantity(
                            (string)newValue, ref quantity, ref result))
                    {
                        return false;
                    }

                    newValue = quantity;
                }
                else if (Utility.SystemStringEquals(name, "Duration"))
                {
                    TimeSpan duration = TimeSpan.Zero;

                    if (!DataOps.TryParseDuration(
                            (string)newValue, ref duration, ref result))
                    {
                        return false;
                    }

                    newValue = duration;
                }
                else if (Utility.SystemStringEquals(name, "TimeStamp"))
                {
                    DateTime timeStamp = DateTime.MinValue;

                    if (!DataOps.TryParseUniversalTimeStamp(
                            (string)newValue, ref timeStamp, ref result))
                    {
                        return false;
                    }

                    newValue = timeStamp;
                }
            }

            try
            {
                /* NO RESULT */
                CommandOps.SetMetadataPropertyValue(metadataType,
                    name, certificate, newValue); /* throw */

                return true;
            }
            catch (Exception e)
            {
                result = e;
                return false;
            }
        }
#endif

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Announces the interactive loop.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="contextName">
        /// The context name.
        /// </param>
        /// <param name="enter">
        /// The enter.
        /// </param>
        /// <param name="host">
        /// On input, supplies the host; upon return, receives the updated
        /// value.
        /// </param>
#if SHELL
        private static void AnnounceInteractiveLoop( /* CORE */
            Interpreter interpreter, /* in */
            string contextName,      /* in */
            bool enter,              /* in */
            ref IHost host           /* in, out */
            )
        {
            try
            {
                if (host == null)
                    host = interpreter.Host; /* throw */
            }
#if DEBUG || FORCE_TRACE
            catch (Exception e)
#else
            catch (Exception)
#endif
            {
#if DEBUG || FORCE_TRACE
                CertificateTraceOps.DebugTrace(
                    e, typeof(Helpers).Name,
                    TracePriority.Highest);
#endif
            }

            if (host != null)
            {
                if (contextName == null)
                    contextName = Constants.InteractiveLoopName;

                host.WriteAnnouncementInfo(interpreter, enter ?
                    BreakpointType.BeforeInteractiveLoop :
                    BreakpointType.AfterInteractiveLoop,
                    contextName, true);
            }
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Performs the interactive loop operation.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode InteractiveLoop( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ref Result result        /* in, out */
            )
        {
            string contextName = null;

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData != null)
                contextName = evaluateClientData.ContextName;

            bool announce = true;

            if (Configuration.DoesVariableExist(
                    Constants.NoAnnounceInteractiveLoopEnvVarName))
            {
                announce = false;
            }

            IHost host = null;

            if (announce)
            {
                AnnounceInteractiveLoop(
                    interpreter, contextName, true, ref host);
            }

            try
            {
                return Interpreter.InteractiveLoop(
                    interpreter, InteractiveLoopData.Create(),
                    ref result);
            }
            finally
            {
                if (announce)
                {
                    AnnounceInteractiveLoop(
                        interpreter, contextName, false, ref host);
                }
            }
        }
#endif

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Attempts to combine the uris.
        /// </summary>
        /// <param name="baseUri">
        /// The base uri.
        /// </param>
        /// <param name="relativeUri">
        /// The relative uri.
        /// </param>
        /// <param name="encoding">
        /// The encoding.
        /// </param>
        /// <param name="flags">
        /// The flags.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// The value produced by the operation.
        /// </returns>
#if WEB
        private static Uri TryCombineUris( /* CORE */
            Uri baseUri,        /* in */
            string relativeUri, /* in */
            Encoding encoding,  /* in */
            UriFlags flags,     /* in */
            ref Result error    /* out */
            )
        {
            return Utility.TryCombineUris(baseUri,
                relativeUri, encoding, Constants.RequestUriComponents,
                UriFormat.Unescaped, flags, ref error);
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Joins the uri parts.
        /// </summary>
        /// <param name="baseUri">
        /// The base uri.
        /// </param>
        /// <param name="relativeUri">
        /// The relative uri.
        /// </param>
        /// <param name="data">
        /// The data.
        /// </param>
        /// <param name="encoding">
        /// The encoding.
        /// </param>
        /// <param name="flags">
        /// The flags.
        /// </param>
        /// <param name="uri">
        /// Upon return, receives the uri.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode JoinUriParts( /* CORE */
            Uri baseUri,           /* in */
            string relativeUri,    /* in */
            StringDictionary data, /* in */
            Encoding encoding,     /* in */
            UriFlags flags,        /* in */
            ref Uri uri,           /* out */
            ref Result error       /* out */
            )
        {
            Uri localUri;

            if (relativeUri != null)
            {
                localUri = TryCombineUris(
                    baseUri, relativeUri, encoding, flags, ref error);

                if (localUri == null)
                    return ReturnCode.Error;
            }
            else
            {
                localUri = baseUri;
            }

            if (data == null)
                goto done;

            StringBuilder builder = null;

            Utility.QueryFromDictionary(data, encoding, ref builder);

            if (builder == null)
                goto done;

            //
            // HACK: The query string, if any, must begin with a "?"
            //       character for the TryCombineUris method to work
            //       properly.
            //
            builder.Insert(0, Characters.QuestionMark);

            localUri = TryCombineUris(
                localUri, builder.ToString(), encoding, flags, ref error);

            if (localUri == null)
                return ReturnCode.Error;

        done:

            uri = localUri;
            return ReturnCode.Ok;
        }
#endif

