        /// <summary>
        /// Gets the request assembly.
        /// </summary>
        /// <param name="assemblyName">
        /// The assembly name.
        /// </param>
        /// <param name="pluginData">
        /// The plugin data.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// The request assembly produced by the operation.
        /// </returns>
#if XML && NETWORK && WEB
        public static Assembly GetRequestAssembly( /* CORE */
            string assemblyName,    /* in */
            IPluginData pluginData, /* in */
            ref Result error        /* out */
            )
        {
            Assembly assembly = null;
            Result localResult = null;

            if (Helpers.FindAssembly(
                    assemblyName, ref assembly,
                    ref localResult) == ReturnCode.Ok)
            {
                return assembly;
            }

            if (Utility.IsCrossAppDomain(pluginData))
            {
                error = Result.Combine(
                    localResult, "WARNING: plugin is isolated");
            }
            else
            {
                error = localResult;
            }

            return null;
        }

