        /// Gets the request base uri.
        /// </summary>
        /// <param name="assembly">
        /// The assembly.
        /// </param>
        /// <param name="cultureInfo">
        /// The culture info.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// The request base uri produced by the operation.
        /// </returns>
        public static Uri GetRequestBaseUri( /* CORE */
            Assembly assembly,       /* in: OPTIONAL */
            CultureInfo cultureInfo, /* in: OPTIONAL */
            ref Result error         /* out */
            )
        {
            Uri baseUri; /* REUSED */

            string value = Configuration.GetVariable(
                Constants.RequestBaseUriEnvVarName);

            if (!String.IsNullOrEmpty(value))
            {
                baseUri = null;

                if (Value.GetUri(
                        value, UriKind.Absolute, cultureInfo,
                        ref baseUri, ref error) == ReturnCode.Ok)
                {
                    return baseUri;
                }
            }

            if (assembly != null)
            {
                baseUri = Utility.GetAssemblyUri(
                    assembly, Constants.RequestLicenseUriName);

                if (baseUri != null)
                {
                    return baseUri;
                }
                else
                {
                    error = String.Format(
                        "assembly {0} has no license uri",
                        Utility.FormatWrapOrNull(assembly));
                }
            }

            return null;
        }

