        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Determines whether like variable name.
        /// </summary>
        /// <param name="value">
        /// The value.
        /// </param>
        /// <returns>
        /// <see langword="true" /> if the condition is satisfied; otherwise,
        /// <see langword="false" />.
        /// </returns>
        private static bool LooksLikeVariableName( /* CORE */
            string value /* in */
            )
        {
            if (String.IsNullOrEmpty(value))
                return false;

            Regex regEx = Constants.VarNameRegEx;

            if (regEx == null)
                return false;

            Match match = regEx.Match(value);

            if ((match == null) || !match.Success)
                return false;

            return true;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets the request data.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="value">
        /// The value.
        /// </param>
        /// <param name="data">
        /// Upon return, receives the data.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode GetRequestData( /* CORE */
            Interpreter interpreter,   /* in */
            string value,              /* in */
            ref StringDictionary data, /* out */
            ref Result error           /* out */
            )
        {
            string localValue = null;

            if (LooksLikeVariableName(value))
            {
                Result varValue = null;

                if (interpreter.GetVariableValue(
                        Constants.GetVariableFlags,
                        value, ref varValue,
                        ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                localValue = varValue;
            }
            else
            {
                localValue = value;
            }

            StringDictionary localData = StringDictionary.FromString(
                localValue, true, ref error);

            if (localData == null)
                return ReturnCode.Error;

            data = localData;
            return ReturnCode.Ok;
        }

