        /// <summary>
        /// Gets the request data.
        /// </summary>
        /// <param name="dictionary">
        /// The dictionary.
        /// </param>
        /// <returns>
        /// The request data produced by the operation.
        /// </returns>
        private static NameValueCollection GetRequestData( /* CORE */
            StringDictionary dictionary /* in: OPTIONAL */
            )
        {
            if (dictionary == null)
                return new NameValueCollection();

            return dictionary.ToNameValueCollection();
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets the response string.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="bytes">
        /// The bytes.
        /// </param>
        /// <param name="encoding">
        /// The encoding.
        /// </param>
        /// <param name="fileName">
        /// The file name.
        /// </param>
        /// <param name="raw">
        /// The raw.
        /// </param>
        /// <param name="text">
        /// Upon return, receives the text.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        private static ReturnCode GetResponseString( /* CORE */
            Interpreter interpreter, /* in */
            byte[] bytes,            /* in */
            Encoding encoding,       /* in */
            string fileName,         /* in */
            bool raw,                /* in */
            ref string text,         /* out */
            ref Result error         /* out */
            )
        {
            string localText;

            if (bytes != null)
            {
                if (fileName != null)
                {
                    string directory = Utility.GetUniquePath(
                        interpreter, Utility.GetTempPath(
                        interpreter), null, null, ref error);

                    if (directory == null)
                        return ReturnCode.Error;

                    try
                    {
                        Directory.CreateDirectory(
                            directory); /* throw */

                        localText = Path.Combine(
                            directory, Path.GetFileName(
                            fileName)); /* throw */

                        File.WriteAllBytes(
                            localText, bytes); /* throw */
                    }
                    catch (Exception e)
                    {
                        error = e;
                        return ReturnCode.Error;
                    }
                }
                else if (raw)
                {
                    localText = Convert.ToBase64String(bytes,
                        Base64FormattingOptions.InsertLineBreaks);
                }
                else if (encoding != null)
                {
                    try
                    {
                        localText = encoding.GetString(
                            bytes); /* throw */
                    }
                    catch (Exception e)
                    {
                        error = e;
                        return ReturnCode.Error;
                    }
                }
                else
                {
                    error = "no encoding selected";
                    return ReturnCode.Error;
                }
            }
            else if (fileName != null)
            {
                error = "no bytes to save to file";
                return ReturnCode.Error;
            }
            else
            {
                localText = null;
            }

            text = localText;
            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets the respose file name.
        /// </summary>
        /// <param name="id">
        /// The id.
        /// </param>
        /// <param name="bytes">
        /// The bytes.
        /// </param>
        /// <returns>
        /// The respose file name produced by the operation.
        /// </returns>
        private static string GetResposeFileName( /* CORE */
            Guid id,     /* in */
            byte[] bytes /* in */
            )
        {
            string fileExtension = null;

#if CERTIFICATE_PLUGIN && PLUGIN_COMMANDS
            if (DataOps.HasEncryptedDataHeader(bytes))
            {
                fileExtension = FileExtension.EncryptedMarkup;
            }
            else
#endif
            {
                fileExtension = FileExtension.Markup;
            }

            return String.Format("{0}{1}", id, fileExtension);
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets the response bytes.
        /// </summary>
        /// <param name="text">
        /// The text.
        /// </param>
        /// <param name="encoding">
        /// The encoding.
        /// </param>
        /// <param name="raw">
        /// The raw.
        /// </param>
        /// <param name="bytes">
        /// Upon return, receives the bytes.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        private static ReturnCode GetResponseBytes( /* CORE */
            string text,       /* in */
            Encoding encoding, /* in */
            bool raw,          /* in */
            ref byte[] bytes,  /* out */
            ref Result error   /* out */
            )
        {
            if (text != null)
            {
                if (raw)
                {
                    bytes = Convert.FromBase64String(text);
                }
                else if (encoding != null)
                {
                    try
                    {
                        bytes = encoding.GetBytes(
                            text); /* throw */
                    }
                    catch (Exception e)
                    {
                        error = e;
                        return ReturnCode.Error;
                    }
                }
                else
                {
                    error = "no encoding selected";
                    return ReturnCode.Error;
                }
            }
            else
            {
                bytes = null;
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Performs the install.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="sourceDirectory">
        /// The source directory.
        /// </param>
        /// <param name="targetDirectory">
        /// The target directory.
        /// </param>
        /// <param name="timeout">
        /// The timeout.
        /// </param>
        /// <param name="installFlags">
        /// The install flags.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode PerformInstall( /* CORE */
            Interpreter interpreter,   /* in */
            IClientData clientData,    /* in */
            string sourceDirectory,    /* in */
            string targetDirectory,    /* in */
            int? timeout,              /* in: OPTIONAL */
            InstallFlags installFlags, /* in */
            ref Result result          /* out */
            )
        {
            string envVarName1 = null;
            string envVarName2 = null;

            try
            {
                long threadId = Utility.GetCurrentThreadId();

                envVarName1 = String.Format(
                    "{0}_{1}", EnvVars.PopulateResultStack, threadId);

                if (!Utility.SetEnvironmentVariable(
                        envVarName1, 1.ToString()))
                {
                    envVarName1 = null;
                }

                envVarName2 = String.Format(
                    "{0}_{1}", EnvVars.IncludeResultStack, threadId);

                if (!Utility.SetEnvironmentVariable(
                        envVarName2, 1.ToString()))
                {
                    envVarName2 = null;
                }

                using (Installation installation = new Installation(
                        interpreter, clientData, sourceDirectory,
                        targetDirectory, timeout, installFlags))
                {
                    ReturnCode code = ReturnCode.Ok; /* REUSED */
                    ResultList errors = null;

                    foreach (InstallPass pass in new InstallPass[] {
                        InstallPass.Pass0, InstallPass.Pass1,
                        InstallPass.Pass2, InstallPass.Pass3,
                        InstallPass.Pass4, InstallPass.Pass5,
                        InstallPass.Pass6
                    })
                    {
                        Result error = null;

                        switch (pass)
                        {
                            case InstallPass.Pass0: /* Pre-Install */
                                {
                                    code = installation.PerformPass0(
                                        code, ref error);

                                    break;
                                }
                            case InstallPass.Pass1: /* Verify */
                                {
                                    code = installation.PerformPass1(
                                        code, ref error);

                                    break;
                                }
                            case InstallPass.Pass2: /* Backup (?) */
                                {
                                    code = installation.PerformPass2(
                                        code, ref error);

                                    break;
                                }
                            case InstallPass.Pass3: /* Commit */
                                {
                                    code = installation.PerformPass3(
                                        code, ref error);

                                    break;
                                }
                            case InstallPass.Pass4: /* Rollback (?) */
                                {
                                    code = installation.PerformPass4(
                                        code, ref error);

                                    break;
                                }
                            case InstallPass.Pass5: /* Cleanup (?) */
                                {
                                    code = installation.PerformPass5(
                                        code, ref error);

                                    break;
                                }
                            case InstallPass.Pass6: /* Post-Install (?) */
                                {
                                    code = installation.PerformPass6(
                                        code, ref error);

                                    break;
                                }
                            default:
                                {
                                    error = String.Format(
                                        "unsupported install pass: {0}",
                                        Utility.FormatWrapOrNull(pass));

                                    code = ReturnCode.Error;
                                    break;
                                }
                        }

                        if ((code != ReturnCode.Ok) && (error != null))
                        {
                            if (errors == null)
                                errors = new ResultList();

                            errors.Add(error);
                        }
                    }

                    result = installation.BuildResult(code, errors);
                    return code;
                }
            }
            finally
            {
                if ((envVarName2 != null) &&
                    Utility.UnsetEnvironmentVariable(envVarName2))
                {
                    envVarName2 = null;
                }

                if ((envVarName1 != null) &&
                    Utility.UnsetEnvironmentVariable(envVarName1))
                {
                    envVarName1 = null;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Makes the uri request.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="baseUri">
        /// The base uri.
        /// </param>
        /// <param name="relativeUri">
        /// The relative uri.
        /// </param>
        /// <param name="method">
        /// The method.
        /// </param>
        /// <param name="data">
        /// The data.
        /// </param>
        /// <param name="encoding">
        /// The encoding.
        /// </param>
        /// <param name="fileName">
        /// The file name.
        /// </param>
        /// <param name="timeout">
        /// The timeout.
        /// </param>
        /// <param name="allowInsecure">
        /// The allow insecure.
        /// </param>
        /// <param name="raw">
        /// The raw.
        /// </param>
        /// <param name="text">
        /// Upon return, receives the text.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode MakeUriRequest( /* CORE */
            Interpreter interpreter, /* in: OPTIONAL */
            Uri baseUri,             /* in */
            string relativeUri,      /* in: OPTIONAL */
            string method,           /* in: OPTIONAL */
            StringDictionary data,   /* in: OPTIONAL */
            Encoding encoding,       /* in: OPTIONAL */
            string fileName,         /* in */
            int? timeout,            /* in: OPTIONAL */
            bool allowInsecure,      /* in */
            bool raw,                /* in */
            ref string text,         /* out */
            ref Result error         /* out */
            )
        {
            if (Utility.InOfflineMode())
            {
                error = "cannot make uri request in offline mode";
                return ReturnCode.Error;
            }

            bool upload;

            if (method == null) /* a.k.a. "GET" */
            {
                upload = false;
            }
            else if (DataOps.StringEqualsNoCase(
                    method, Constants.GetMethod))
            {
                upload = false;
            }
            else if (DataOps.StringEqualsNoCase(
                    method, Constants.PostMethod))
            {
                upload = true;
            }
            else
            {
                //
                // TODO: Perhaps other request methods
                //       can be supported easily?
                //
                error = String.Format(
                    "unsupported request method {0}",
                    Utility.FormatWrapOrNull(method));

                return ReturnCode.Error;
            }

            if (encoding == null)
                encoding = DataOps.GetDefaultEncoding();

            UriFlags uriFlags = Constants.RequestUriFlags;

            if (allowInsecure)
                uriFlags |= UriFlags.InsecureOnlyMask;

            Uri uri = null;
            byte[] bytes = null;

            if (upload)
            {
                if (JoinUriParts(
                        baseUri, relativeUri, null,
                        encoding, uriFlags, ref uri,
                        ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                if (!Utility.IsWebUri(
                        uri, ref uriFlags, ref error))
                {
                    return ReturnCode.Error;
                }

#if TEST
                if (Utility.SetWebSecurityProtocol(
                        false, ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }
#endif

                if (Utility.UploadValues(
                        interpreter, null, uri,
                        method, GetRequestData(data),
                        NetworkState.GetMaximumRetries(),
                        timeout, null, ref bytes,
                        ref error) != ReturnCode.Ok)
                {
#if DEBUG || FORCE_TRACE
                    CertificateNetworkOps.DebugTraceUriError(
                        null, uri, timeout, error, TracePriority.High);
#endif

                    return ReturnCode.Error;
                }
            }
            else
            {
                if (JoinUriParts(
                        baseUri, relativeUri, data,
                        encoding, uriFlags, ref uri,
                        ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

#if TEST
                if (Utility.SetWebSecurityProtocol(
                        false, ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }
#endif

                if (Utility.DownloadData(
                        interpreter, null, uri,
                        NetworkState.GetMaximumRetries(), timeout,
                        null, ref bytes, ref error) != ReturnCode.Ok)
                {
#if DEBUG || FORCE_TRACE
                    CertificateNetworkOps.DebugTraceUriError(
                        null, uri, timeout, error, TracePriority.High);
#endif

                    return ReturnCode.Error;
                }
            }

            return GetResponseString(
                interpreter, bytes, encoding, fileName, raw,
                ref text, ref error);
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Requests the license.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="baseUri">
        /// The base uri.
        /// </param>
        /// <param name="encoding">
        /// The encoding.
        /// </param>
        /// <param name="id">
        /// The id.
        /// </param>
        /// <param name="timeout">
        /// The timeout.
        /// </param>
        /// <param name="fileName">
        /// Upon return, receives the file name.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode RequestLicense( /* CORE */
            Interpreter interpreter, /* in: OPTIONAL */
            Uri baseUri,             /* in */
            Encoding encoding,       /* in: OPTIONAL */
            Guid id,                 /* in */
            int? timeout,            /* in: OPTIONAL */
            ref string fileName,     /* out */
            ref Result error         /* out */
            )
        {
            if (encoding == null)
                encoding = DataOps.GetDefaultEncoding();

            if (encoding == null)
            {
                error = "invalid encoding";
                return ReturnCode.Error;
            }

            StringDictionary data = new StringDictionary();

            data.Add("id", id.ToString());

            bool encrypted = Constants.RequestLicenseEncrypted;

            data.Add("encrypted", encrypted.ToString());

            string text = null;

            if (MakeUriRequest(
                    interpreter, baseUri, GetRequestRelativeUri(),
                    null, data, encoding, null, timeout, Build.Debug,
                    true, ref text, ref error) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            byte[] bytes = null;

            if (GetResponseBytes(text, encoding,
                    true, ref bytes, ref error) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

#if SERIALIZATION
            if (!CertificateXmlOps.LooksLikeDocument(
                    bytes, encoding, encrypted, true, ref error))
            {
                return ReturnCode.Error;
            }
#endif

            string localFileName = GetResposeFileName(id, bytes);

            if (localFileName == null)
                return ReturnCode.Error;

            string xml = encoding.GetString(bytes); /* throw */

            if (!LicenseState.MergeCachedTextFile(
                    localFileName, xml))
            {
                error = "unable to cache certificate text file";
                return ReturnCode.Error;
            }

            if (!LicenseState.MergeCachedBinaryFile(
                    localFileName, bytes))
            {
                error = "unable to cache certificate binary file";
                return ReturnCode.Error;
            }

            fileName = localFileName;
            return ReturnCode.Ok;
        }

