        /// <summary>
        /// Provisions the license.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="baseUri">
        /// The base uri.
        /// </param>
        /// <param name="encoding">
        /// The encoding.
        /// </param>
        /// <param name="apiKey">
        /// The api key.
        /// </param>
        /// <param name="id">
        /// The id.
        /// </param>
        /// <param name="duration">
        /// The duration.
        /// </param>
        /// <param name="timeout">
        /// The timeout.
        /// </param>
        /// <param name="xml">
        /// Upon return, receives the xml.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode ProvisionLicense( /* CORE */
            Interpreter interpreter, /* in: OPTIONAL */
            Uri baseUri,             /* in */
            Encoding encoding,       /* in: OPTIONAL */
            Guid apiKey,             /* in */
            Guid id,                 /* in */
            TimeSpan duration,       /* in */
            int? timeout,            /* in: OPTIONAL */
            ref string xml,          /* out */
            ref Result error         /* out */
            )
        {
            if (encoding == null)
                encoding = DataOps.GetDefaultEncoding();

            if (encoding == null)
            {
                error = "invalid encoding";
                return ReturnCode.Error;
            }

            StringDictionary data = new StringDictionary();

            data.Add("apiKey", apiKey.ToString());
            data.Add("provisionType", "License");
            data.Add("entityName", id.ToString());
            data.Add("duration", duration.ToString());

            bool encrypted = Constants.ProvisionLicenseEncrypted;

            data.Add("encrypted", encrypted.ToString());

            string text = null;

            if (MakeUriRequest(
                    interpreter, baseUri, GetProvisionRelativeUri(),
                    null, data, encoding, null, timeout, Build.Debug,
                    true, ref text, ref error) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            byte[] bytes = null;

            if (GetResponseBytes(text, encoding,
                    true, ref bytes, ref error) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

#if SERIALIZATION
            if (!CertificateXmlOps.LooksLikeDocument(
                    bytes, encoding, encrypted, true, ref error))
            {
                return ReturnCode.Error;
            }
#endif

            xml = encoding.GetString(bytes); /* throw */
            return ReturnCode.Ok;
        }
#endif

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Finds the key pair.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="keyPairs">
        /// The key pairs.
        /// </param>
        /// <param name="keyRingName">
        /// The key ring name.
        /// </param>
        /// <param name="policyType">
        /// The policy type.
        /// </param>
        /// <param name="publicKeyToken">
        /// The public key token.
        /// </param>
        /// <param name="keyPair">
        /// Upon return, receives the key pair.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        private static ReturnCode FindKeyPair( /* CORE */
            Interpreter interpreter,        /* in: OPTIONAL */
            IEnumerable<IKeyPair> keyPairs, /* in: OPTIONAL */
            string keyRingName,             /* in: OPTIONAL */
            PolicyType? policyType,         /* in: OPTIONAL */
            byte[] publicKeyToken,          /* in: OPTIONAL */
            ref IKeyPair keyPair,           /* out */
            ref Result error                /* out */
            )
        {
            Result localError; /* REUSED */
            ResultList errors = null;

            //
            // NOTE: First, check for the (specific?) key pair within the
            //       specified list of key pairs (i.e. most likely from a
            //       script context).  If a non-null public key token was
            //       specified by the caller, their public key tokens must
            //       match; otherwise, the first non-null key pair will be
            //       returned, if any.
            //
            localError = null;

            if (CertificateKeyPairOps.GetOne(
                    keyPairs, publicKeyToken, false, " in context",
                    ref keyPair, ref localError) == ReturnCode.Ok)
            {
                return ReturnCode.Ok;
            }
            else
            {
                if (localError != null)
                {
                    if (errors == null) /* REDUNDANT */
                        errors = new ResultList();

                    errors.Add(localError);
                }
            }

            ///////////////////////////////////////////////////////////////////

#if CERTIFICATE_PLUGIN && CERTIFICATE_POLICY
            //
            // NOTE: If a non-null policy type was specified, then check
            //       that trusted key ring for the specified public key
            //       token and/or the first available key pair.
            //
            if (policyType != null)
            {
                localError = null;

                if (CertificateKeyPairOps.GetRing(interpreter,
                        keyRingName, (PolicyType)policyType,
                        publicKeyToken, ref keyPair,
                        ref localError) == ReturnCode.Ok)
                {
                    return ReturnCode.Ok;
                }
                else
                {
                    if (localError != null)
                    {
                        if (errors == null)
                            errors = new ResultList();

                        errors.Add(localError);
                    }
                }
            }
#endif

            error = errors;
            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Finds the assembly.
        /// </summary>
        /// <param name="assemblyName">
        /// The assembly name.
        /// </param>
        /// <param name="assembly">
        /// Upon return, receives the assembly.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode FindAssembly( /* CORE */
            string assemblyName,   /* in */
            ref Assembly assembly, /* out */
            ref Result error       /* out */
            )
        {
            AssemblyName localAssemblyName = Utility.GetAssemblyName(
                assemblyName, ref error);

            if (localAssemblyName == null)
                return ReturnCode.Error;

            assembly = Utility.FindAssemblyInAppDomain(
                null, localAssemblyName.Name, localAssemblyName.Version,
                localAssemblyName.GetPublicKeyToken(), ref error);

            return (assembly != null) ? ReturnCode.Ok : ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Conditionally performs the dump cached file operation.
        /// </summary>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="fileName">
        /// The file name.
        /// </param>
        /// <param name="priority">
        /// The priority.
        /// </param>
        /// <returns>
        /// <see langword="true" /> on success; otherwise,
        /// <see langword="false" />.
        /// </returns>
        private static bool MaybeDumpCachedFile( /* CORE */
            IClientData clientData, /* in */
            string fileName,        /* in */
            TracePriority priority  /* in */
            )
        {
            if (clientData == null)
                return false;

            if (String.IsNullOrEmpty(fileName))
                return false;

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
                return false;

            string directory;
            string fileNameOnly;

            try
            {
                directory = Path.GetDirectoryName(
                    evaluateClientData.FileName);

                fileNameOnly = Path.GetFileName(
                    fileName);
            }
#if DEBUG || FORCE_TRACE
            catch (Exception e)
#else
            catch
#endif
            {
#if DEBUG || FORCE_TRACE
                CertificateTraceOps.DebugTrace(
                    e, typeof(Helpers).Name, priority);
#endif

                return false;
            }

            if (String.IsNullOrEmpty(directory))
                return false;

            if (!Directory.Exists(directory))
                return false;

            if (String.IsNullOrEmpty(fileNameOnly))
                return false;

            object data;

            if (!LicenseState.TryGetCachedFile(fileName, out data))
                return false;

            if (data is byte[])
            {
                try
                {
                    File.WriteAllBytes(Path.Combine(
                        directory, fileNameOnly), (byte[])data);

                    return true;
                }
#if DEBUG || FORCE_TRACE
                catch (Exception e)
#else
                catch
#endif
                {
#if DEBUG || FORCE_TRACE
                    CertificateTraceOps.DebugTrace(
                        e, typeof(Helpers).Name, priority);
#endif
                }
            }

            if (data is string)
            {
                try
                {
                    File.WriteAllText(Path.Combine(
                        directory, fileNameOnly), (string)data);

                    return true;
                }
#if DEBUG || FORCE_TRACE
                catch (Exception e)
#else
                catch
#endif
                {
#if DEBUG || FORCE_TRACE
                    CertificateTraceOps.DebugTrace(
                        e, typeof(Helpers).Name, priority);
#endif
                }
            }

            return false;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Requires the license.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="plugin">
        /// The plugin.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="fileName">
        /// The file name.
        /// </param>
        /// <param name="publicKeyToken">
        /// The public key token.
        /// </param>
        /// <param name="features">
        /// The features.
        /// </param>
        /// <param name="restrictions">
        /// The restrictions.
        /// </param>
        /// <param name="addObject">
        /// The add object.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode RequireLicense( /* CORE */
            Interpreter interpreter, /* in: OPTIONAL */
            IPlugin plugin,          /* in: OPTIONAL */
            IClientData clientData,  /* in */
            string fileName,         /* in: OPTIONAL */
            byte[] publicKeyToken,   /* in: OPTIONAL */
            string features,         /* in: OPTIONAL */
            string restrictions,     /* in: OPTIONAL */
            bool addObject,          /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (LicenseState.IsPending())
            {
                result = "license already pending";
                return ReturnCode.Error;
            }

            IEnumerable<IKeyPair> keyPairs; /* REUSED */
            Assembly assembly = AssemblyOps.GetObject();
            AssemblyName assemblyName = AssemblyOps.GetName();

            if (publicKeyToken != null)
            {
                keyPairs = evaluateClientData.KeyPairs;

#if CERTIFICATE_PLUGIN && (CERTIFICATE_POLICY || PLUGIN_COMMANDS)
                ResultList errors = null;

                if (CertificateKeyPairOps.GetBuiltIn( /* OK */
                        interpreter, assembly, assemblyName,
                        ref keyPairs, ref errors) != ReturnCode.Ok)
                {
                    result = errors;
                    return ReturnCode.Error;
                }
#endif

                IKeyPair keyPair = null;

                if (FindKeyPair(interpreter, keyPairs,
                        null, PolicyType.License, publicKeyToken,
                        ref keyPair, ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                keyPairs = (keyPair != null) ?
                    new IKeyPair[] { keyPair } : null;
            }
            else
            {
                keyPairs = null;
            }

            //
            // HACK: The "force" flag is used here to indicate a
            //       manual license verification operation, which
            //       should make sure that no superfluous access
            //       to internal licensing state is performed by
            //       the called method.
            //
            Result localResult; /* REUSED */
            ICertificate certificate = null;

            localResult = null;

            if (VerifyOps.LoadAndProcess(
                    interpreter, assembly,
                    assemblyName, plugin,
                    evaluateClientData.HashAlgorithmName,
                    evaluateClientData.HashKey,
                    evaluateClientData.Encoding,
                    keyPairs, features, restrictions,
                    evaluateClientData.ExecutionPolicy,
                    evaluateClientData.KeyName,
                    evaluateClientData.KeyRingName,
                    evaluateClientData.Timeout,
                    true, Constants.CertificateEmbedded,
                    Constants.CertificateValidate, null,
                    null, evaluateClientData,
                    ref fileName, ref certificate,
                    ref localResult) != ReturnCode.Ok)
            {
                /* IGNORED */
                MaybeDumpCachedFile(clientData,
                    fileName, TracePriority.Highest);

                result = localResult;
                return ReturnCode.Error;
            }

            if (certificate == null)
            {
                result = "license certificate missing";
                return ReturnCode.Error;
            }

            string networkInfo = null;

#if NETWORK
            Uri authority = null;
            UriComponents components = (UriComponents)0;

            if (CertificateNetworkOps.GetAuthorityAndComponents(
                    interpreter, assembly, plugin, certificate,
                    evaluateClientData.CultureInfo, ref authority,
                    ref components, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            networkInfo = StringList.MakeList(authority, components);
#endif

            if (addObject)
            {
#if TEST
                object objectValue = null;

#if ISOLATED_PLUGINS && CERTIFICATE_PLUGIN
                if (SharedOps.IsCrossAppDomain(interpreter, plugin))
                {
                    objectValue = Certificate.ToDictionary(
                        certificate);
                }
                else
#endif
                {
                    objectValue = certificate;
                }

                localResult = null;

                if (evaluateClientData.AddObject(
                        interpreter, null, objectValue,
                        Constants.ContextObjectFlags,
                        ref localResult) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                if (networkInfo != null)
                {
                    result = StringList.MakeList(
                        "Object", localResult,
                        "NetworkInfo", networkInfo);
                }
                else
                {
                    result = StringList.MakeList(
                        "Object", localResult);
                }
#else
                result = "not implemented";
                return ReturnCode.Error;
#endif
            }
            else
            {
                if (networkInfo != null)
                {
                    result = StringList.MakeList(
                        "Id", certificate.Id,
                        "NetworkInfo", networkInfo);
                }
                else
                {
                    result = StringList.MakeList(
                        "Id", certificate.Id);
                }
            }

            return ReturnCode.Ok;
        }

