        /// <summary>
        /// Performs the security should be enabled operation.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="pluginData">
        /// The plugin data.
        /// </param>
        /// <param name="flags">
        /// The flags.
        /// </param>
        /// <returns>
        /// <see langword="true" /> or <see langword="false" /> to indicate
        /// the result, or <see langword="null" /> if it cannot be determined.
        /// </returns>
#if CERTIFICATE_PLUGIN && CERTIFICATE_POLICY
        public static bool? SecurityShouldBeEnabled( /* CORE? */
            Interpreter interpreter,  /* in */
            IPluginData pluginData,   /* in */
            EnableSecurityFlags flags /* in */
            )
        {
            if (SharedOps.HasFlags(
                    flags, EnableSecurityFlags.Disable, true))
            {
                return false;
            }
            else if (SharedOps.HasFlags(
                    flags, EnableSecurityFlags.Enable, true))
            {
                return true;
            }
            else
            {
                bool isEnabled;

                if (KeyRingOps.IsBaseScriptPolicyAllowSignedOnly(
                        interpreter, pluginData))
                {
                    isEnabled = true;
                }
                else
                {
                    isEnabled = false;
                }

                if (SharedOps.HasFlags(
                        flags, EnableSecurityFlags.Toggle, true))
                {
                    return !isEnabled;
                }
                else if (SharedOps.HasFlags(
                        flags, EnableSecurityFlags.MaybeDisable, true))
                {
                    if (isEnabled)
                        return false;
                }
                else if (SharedOps.HasFlags(
                        flags, EnableSecurityFlags.MaybeEnable, true))
                {
                    if (!isEnabled)
                        return true;
                }
            }

            return null;
        }

