        /// <summary>
        /// Performs the security should be local only operation.
        /// </summary>
        /// <param name="flags">
        /// The flags.
        /// </param>
        /// <param name="default">
        /// The default.
        /// </param>
        /// <returns>
        /// <see langword="true" /> on success; otherwise,
        /// <see langword="false" />.
        /// </returns>
        private static bool SecurityShouldBeLocalOnly( /* CORE? */
            EnableSecurityFlags flags, /* in */
            bool @default              /* in */
            )
        {
            if (SharedOps.HasFlags(
                    flags, EnableSecurityFlags.GlobalOnly, true))
            {
                return false;
            }
            else if (SharedOps.HasFlags(
                    flags, EnableSecurityFlags.LocalOnly, true))
            {
                return true;
            }
            else
            {
                return @default;
            }
        }

