        public static bool SecurityShouldBeIgnoreErrors( /* CORE? */
            IPluginData pluginData,   /* in */
            EnableSecurityFlags flags /* in */
            )
        {
            return SecurityShouldBeIgnoreErrors(flags, pluginData != null);
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Determines whether bootstrap key pairs.
        /// </summary>
        /// <param name="flags">
        /// The flags.
        /// </param>
        /// <param name="wasEnabled">
        /// The was enabled.
        /// </param>
        /// <param name="enable">
        /// The enable.
        /// </param>
        /// <param name="shouldBootstrap">
        /// Upon return, receives the should bootstrap.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode ShouldBootstrapKeyPairs(
            EnableSecurityFlags flags, /* in */
            bool wasEnabled,           /* in */
            bool? enable,              /* in: OPTIONAL */
            ref bool shouldBootstrap,  /* out */
            ref Result error           /* out */
            )
        {
            if ((!wasEnabled && (enable != null) && (bool)enable) ||
                (wasEnabled && ((enable == null) || (bool)enable)))
            {
                bool isPending = CertificateKeyRingState.IsAnyPending();

                if (SharedOps.HasFlags(
                        flags, EnableSecurityFlags.AlwaysKeyRings, true))
                {
                    if (isPending)
                    {
                        error = "key ring(s) already pending load";
                        return ReturnCode.Error;
                    }

                    shouldBootstrap = true;
                }

                if (!isPending && SharedOps.HasFlags(
                        flags, EnableSecurityFlags.MaybeKeyRings, true))
                {
                    shouldBootstrap = true;
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Bootstraps the key pairs.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="pluginData">
        /// The plugin data.
        /// </param>
        /// <param name="cultureInfo">
        /// The culture info.
        /// </param>
        /// <param name="loaded">
        /// Upon return, receives the loaded.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode BootstrapKeyPairs( /* CORE? */
            Interpreter interpreter, /* in */
            IPluginData pluginData,  /* in */
            CultureInfo cultureInfo, /* in */
            ref int? loaded,         /* out */
            ref Result error         /* out */
            )
        {
            if (CertificateKeyRingState.IsAnyPending())
            {
                error = "key ring(s) already pending load";
                return ReturnCode.Error;
            }

            int localLoaded = 0;

            if (KeyRingOps.BootstrapKeyPairsPublicOnly(interpreter,
                    pluginData, cultureInfo, PolicyType.Script,
                    ref localLoaded, ref error) == ReturnCode.Ok)
            {
                loaded = localLoaded;
                return ReturnCode.Ok;
            }
            else
            {
                return ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Determines whether the badge plugin loaded condition is satisfied.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <returns>
        /// <see langword="true" /> if the condition is satisfied; otherwise,
        /// <see langword="false" />.
        /// </returns>
        public static bool IsBadgePluginLoaded( /* CORE? */
            Interpreter interpreter /* in */
            )
        {
            if (interpreter != null)
            {
                Result error = null;

                if (interpreter.FindPlugin(null,
                        MatchMode.Glob, Constants.BadgePluginPattern,
                        null, Constants.EnterprisePublicKeyTokenBytes,
                        false, ref error) != null)
                {
                    return true;
                }
            }

            return false;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Performs the result for enable security operation.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="wasEnabled">
        /// The was enabled.
        /// </param>
        /// <param name="skipEnable">
        /// The skip enable.
        /// </param>
        /// <param name="enable">
        /// The enable.
        /// </param>
        /// <param name="isEnabled">
        /// The is enabled.
        /// </param>
        /// <param name="loaded">
        /// The loaded.
        /// </param>
        /// <returns>
        /// The value produced by the operation.
        /// </returns>
        public static StringList ResultForEnableSecurity( /* CORE? */
            Interpreter interpreter, /* in */
            bool wasEnabled,         /* in */
            bool skipEnable,         /* in */
            bool? enable,            /* in: OPTIONAL */
            bool isEnabled,          /* in */
            int? loaded              /* in: OPTIONAL */
            )
        {
            StringList list = new StringList();

            list.Add("security");
            list.Add("was");

            if (wasEnabled)
                list.Add("enabled");
            else
                list.Add("disabled");

            if (!skipEnable && (enable != null))
            {
                list.Add("set");

                if ((bool)enable)
                    list.Add("enabled");
                else
                    list.Add("disabled");
            }

            list.Add("is");

            if (isEnabled)
                list.Add("enabled");
            else
                list.Add("disabled");

            if (interpreter != null)
            {
                list.Add("interpreter");

                if (interpreter.SetSecurityWasEnabled(null) == isEnabled)
                    list.Add("synchronized");
                else
                    list.Add("desynchronized");
            }

            if (loaded != null)
            {
                list.Add("loaded");
                list.Add(((int)loaded).ToString());
            }

            list.Add("certificates");

            if (IsBadgePluginLoaded(interpreter))
                list.Add("available");
            else
                list.Add("unavailable");

            return list;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets the public key name.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="varName">
        /// The var name.
        /// </param>
        /// <param name="unsetVarName">
        /// The unset var name.
        /// </param>
        /// <param name="keyName">
        /// Upon return, receives the key name.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode GetPublicKeyName( /* CORE? */
            Interpreter interpreter, /* in */
            string varName,          /* in */
            bool unsetVarName,       /* in */
            ref string keyName,      /* out */
            ref Result error         /* out */
            )
        {
            if (interpreter == null)
            {
                error = "invalid interpreter";
                return ReturnCode.Error;
            }

            Result value = null;

            if (interpreter.GetVariableValue(
                    Constants.GetVariableFlags, varName,
                    ref value, ref error) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            StringList list = null;

            if (Parser.SplitList(
                    interpreter, value, 0, Length.Invalid, true,
                    ref list, ref error) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            int count = list.Count;

            if (count < 2)
            {
                error = String.Format(
                    "bad public key list length {0}", count);

                return ReturnCode.Error;
            }

            if (unsetVarName && interpreter.UnsetVariable(
                    Constants.UnsetVariableFlags, varName,
                    ref error) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            keyName = list[1];
            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Adds the public key.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="keyMetadata">
        /// The key metadata.
        /// </param>
        /// <param name="keyData">
        /// The key data.
        /// </param>
        /// <param name="keyRingName">
        /// The key ring name.
        /// </param>
        /// <param name="policyType">
        /// The policy type.
        /// </param>
        /// <param name="keyName">
        /// On input, supplies the key name; upon return, receives the updated
        /// value.
        /// </param>
        /// <param name="keyPair">
        /// Upon return, receives the key pair.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode AddPublicKey( /* CORE? */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            string keyMetadata,      /* in */
            string keyData,          /* in */
            string keyRingName,      /* in */
            PolicyType? policyType,  /* in */
            ref string keyName,      /* in, out */
            ref IKeyPair keyPair,    /* out */
            ref Result error         /* out */
            )
        {
            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                error = "missing context clientData";
                return ReturnCode.Error;
            }

            IKeyPair localKeyPair = DataOps.ParseKeyPairData(
                evaluateClientData.FileName, keyData, false,
                null, true, false, ref error);

            if (localKeyPair == null)
                return ReturnCode.Error;

            IIdentifier identifier = null;
            IKeyPairMetadataBase keyPairMetadataBase = null;

            if (CertificateKeyPairOps.GetIdentifierAndMetadata(
                    keyMetadata, ref identifier,
                    ref keyPairMetadataBase,
                    ref error) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            /* IGNORED */
            DataOps.CopyIdentifier(
                identifier, localKeyPair as IIdentifier);

            string localKeyName;

            if (keyName != null) /* RARE */
                localKeyName = keyName;
            else if (identifier != null)
                localKeyName = identifier.Name;
            else
                localKeyName = null;

            if (localKeyName == null)
            {
                string fileName = evaluateClientData.FileName;

                if (!String.IsNullOrEmpty(fileName))
                    localKeyName = fileName;
            }

            if (localKeyName == null)
            {
                localKeyName = String.Format("{0}: 0x{1:X}",
                    Constants.TraceFileNamePrefix,
                    Utility.GetHashCode(evaluateClientData));
            }

            /* IGNORED */
            DataOps.MaybeSetAsKeyPair(
                localKeyPair as IIdentifierBase, localKeyName);

            /* IGNORED */
            DataOps.CopyKeyPairMetadataBase(
                keyPairMetadataBase, localKeyPair);

            //
            // NOTE: If a particular key pair is revoked, it cannot be
            //       used to verify anything, no matter what.
            //
            NetworkFlags networkFlags = GetNetworkFlags(policyType);

            if (CertificateKeyPairState.GetForceNetwork())
                networkFlags |= NetworkFlags.ForceMask;

            Result localResult = null;

            if (CertificateRevocationOps.IsRevoked( /* OK */
                    interpreter, AssemblyOps.GetObject(),
                    evaluateClientData.Plugin,
                    evaluateClientData.HashAlgorithmName,
                    evaluateClientData.HashKey,
                    evaluateClientData.Encoding, null,
                    localKeyPair, evaluateClientData.CultureInfo,
                    Utility.GetUtcNow(), evaluateClientData.Timeout,
                    networkFlags, ref localResult) != ReturnCode.Ok)
            {
                error = localResult;
                return ReturnCode.Error;
            }

            //
            // HACK: If a particular key pair is expired, it cannot be
            //       used to verify anything.  This does not apply if
            //       a key pair has the "ExpireSignature" usage flag.
            //
            if (SharedOps.CheckKeyExpiration(
                    localKeyPair, null, ref error) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            //
            // HACK: If the specified policy type is not null, that means
            //       the caller wishes to persist the loaded key pair into
            //       the associated trusted key ring for the interpreter;
            //       otherwise, the key pair is usable within the current
            //       script context only.
            //
            if (policyType != null)
            {
                IKeyRing keyRing = null;

                if (KeyRingOps.GetKeyRing(interpreter,
                        keyRingName, (PolicyType)policyType,
                        ref keyRing, ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                int added = 0;

                if ((keyRing != null) && keyRing.Add(
                        localKeyName, localKeyPair, false, false,
                        ref added, ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                if (added != 1)
                {
                    error = String.Format(
                        "could not add key pair {0} as {1} to " +
                        "trusted {2} key ring {3}",
                        Utility.FormatWrapOrNull(
                            DataOps.FormatPublicKeyToken(
                                localKeyPair.PublicKeyToken,
                                true, true)),
                        Utility.FormatWrapOrNull(localKeyName),
                        Utility.FormatWrapOrNull(policyType),
                        Utility.FormatWrapOrNull(keyRingName));

                    return ReturnCode.Error;
                }

                /* IGNORED */
                CertificateGlobalState.IncrementChangeCount();
            }
            else
            {
                IList<IKeyPair> keyPairs =
                    evaluateClientData.KeyPairs as IList<IKeyPair>;

                if (keyPairs == null)
                {
                    error = "missing context key pairs";
                    return ReturnCode.Error;
                }

                keyPairs.Add(localKeyPair);
            }

            keyPair = localKeyPair;
            keyName = localKeyName;

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Removes the public key.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="keyRingName">
        /// The key ring name.
        /// </param>
        /// <param name="policyType">
        /// The policy type.
        /// </param>
        /// <param name="keyName">
        /// The key name.
        /// </param>
        /// <param name="keyPair">
        /// Upon return, receives the key pair.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode RemovePublicKey( /* CORE? */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            string keyRingName,      /* in */
            PolicyType? policyType,  /* in */
            string keyName,          /* in */
            ref IKeyPair keyPair,    /* out */
            ref Result error         /* out */
            )
        {
            //
            // HACK: If the specified policy type is not null, that means
            //       the caller wishes to persist the loaded key pair into
            //       the associated trusted key ring for the interpreter;
            //       otherwise, the key pair is usable within the current
            //       script context only.
            //
            if (policyType != null)
            {
                IKeyRing keyRing = null;

                if (KeyRingOps.GetKeyRing(interpreter,
                        keyRingName, (PolicyType)policyType,
                        ref keyRing, ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                IKeyPair localKeyPair = null;
                int removed = 0;

                if ((keyRing != null) && keyRing.Remove(
                        keyName, true, ref localKeyPair, ref removed,
                        ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                if (removed != 1)
                {
                    error = String.Format(
                        "could not remove key pair {0} as {1} from " +
                        "trusted {2} key ring {3}",
                        Utility.FormatWrapOrNull((localKeyPair != null) ?
                            DataOps.FormatPublicKeyToken(
                                localKeyPair.PublicKeyToken,
                                true, true) : null),
                        Utility.FormatWrapOrNull(keyName),
                        Utility.FormatWrapOrNull(policyType),
                        Utility.FormatWrapOrNull(keyRingName));

                    return ReturnCode.Error;
                }

                /* IGNORED */
                CertificateGlobalState.IncrementChangeCount();

                keyPair = localKeyPair;
                return ReturnCode.Ok;
            }
            else
            {
                EvaluateClientData evaluateClientData =
                    clientData as EvaluateClientData;

                if (evaluateClientData == null)
                {
                    error = "missing context clientData";
                    return ReturnCode.Error;
                }

                return CertificateKeyPairOps.RemoveByName(
                    evaluateClientData.KeyPairs, keyName,
                    " from context", ref keyPair, ref error);
            }
        }
#endif

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Determines whether the command is available.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="name">
        /// The name.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="found">
        /// The found.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode HaveCommand( /* CORE */
            Interpreter interpreter, /* in */
            string name,             /* in */
            IClientData clientData,  /* in */
            ref bool found,          /* in */
            ref Result error         /* out */
            )
        {
            if (interpreter == null)
            {
                error = "invalid interpreter";
                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                error = "missing context clientData";
                return ReturnCode.Error;
            }

            LongList tokens = evaluateClientData.CommandTokens;

            if (tokens == null)
            {
                error = "missing context command tokens";
                return ReturnCode.Error;
            }

            bool localFound = false;

            foreach (long token in tokens)
            {
                string localName = null;
                Result localError = null; /* NOT USED */

                if ((interpreter.GetCommandName(token,
                        LookupFlags.NoVerbose, ref localName,
                        ref localError) == ReturnCode.Ok) &&
                    (localName != null) &&
                    DataOps.StringEquals(localName, name))
                {
                    localFound = true;
                    break;
                }
            }

            found = localFound;
            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Lists the commands.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="list">
        /// On input, supplies the list; upon return, receives the updated
        /// value.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode ListCommands( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ref StringList list,     /* in, out */
            ref Result error         /* out */
            )
        {
            if (interpreter == null)
            {
                error = "invalid interpreter";
                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                error = "missing context clientData";
                return ReturnCode.Error;
            }

            LongList tokens = evaluateClientData.CommandTokens;

            if (tokens == null)
            {
                error = "missing context command tokens";
                return ReturnCode.Error;
            }

            StringList localList = null;

            foreach (long token in tokens)
            {
                string localName = null;
                Result localError = null; /* NOT USED */

                if ((interpreter.GetCommandName(token,
                        LookupFlags.NoVerbose, ref localName,
                        ref localError) == ReturnCode.Ok))
                {
                    if (localName != null)
                    {
                        if (localList == null)
                            localList = new StringList();

                        localList.Add(localName);
                    }
                }
            }

            if (localList != null)
            {
                localList.Sort(); /* O(N log N) */

                if (list == null)
                    list = new StringList();

                list.AddRange(localList);
            }

            return ReturnCode.Ok;
        }

