        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Removes the all commands.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error that was
        /// encountered.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode RemoveAllCommands( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ref Result error         /* out */
            )
        {
            if (interpreter == null)
            {
                error = "invalid interpreter";
                return ReturnCode.Error;
            }

            LongList tokens = null;
            ResultList errors = null;

            /* IGNORED */
            interpreter.RemoveCommands(
                GetAllCommandNames(), clientData, false, false,
                ref tokens, ref errors);

#if DEBUG || FORCE_TRACE
            CertificateTraceOps.DebugTrace(String.Format(
                "RemoveAllCommands: interpreter = {0}, " +
                "tokens = {1}, errors = {2}",
                DataOps.FormatInterpreter(
                    interpreter, true, false),
                Utility.FormatWrapOrNull(tokens),
                Utility.FormatWrapOrNull(true, true, errors)),
                typeof(Helpers).Name, TracePriority.Low);
#endif

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Adds the all commands via reflection.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="plugin">
        /// The plugin.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="tokens">
        /// Upon return, receives the tokens.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
#if TEST
        public static ReturnCode AddAllCommandsViaReflection( /* CORE */
            Interpreter interpreter, /* in */
            IPlugin plugin,          /* in */
            IClientData clientData,  /* in */
            ref long[] tokens,       /* out */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            LongList localTokens = null;

            try
            {
                Assembly assembly = AssemblyOps.GetObject();
                ResultList errors = null;

                if (SharedOps.IsCrossAppDomain(interpreter, plugin))
                {
#if ISOLATED_INTERPRETERS || ISOLATED_PLUGINS
                    if (_Test.TestAddCommands(interpreter,
                            assembly, plugin, clientData, CommandFlags.None,
                            Constants.TransientCommandNamePattern, null, true,
                            ref localTokens, ref errors) != ReturnCode.Ok)
                    {
                        result = errors;
                        return ReturnCode.Error;
                    }
#else
                    result = "cannot use delegates with plugin isolated";
                    return ReturnCode.Error;
#endif
                }
                else
                {
                    if (_Test.TestAddExecuteCallbacks(interpreter,
                            assembly, plugin, clientData, CommandFlags.None,
                            Constants.TransientCallbacksTypeName, null, true,
                            ref localTokens, ref errors) != ReturnCode.Ok)
                    {
                        result = errors;
                        return ReturnCode.Error;
                    }
                }

                return ReturnCode.Ok;
            }
            finally
            {
                tokens = (localTokens != null) ?
                    localTokens.ToArray() : null;
            }
        }
#endif

        ///////////////////////////////////////////////////////////////////////

#if ISOLATED_INTERPRETERS || ISOLATED_PLUGINS
        /// <summary>
        /// Adds the command.
        /// </summary>
        /// <param name="trace">
        /// The trace.
        /// </param>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="command">
        /// The underlying command to be wrapped.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="token">
        /// Upon return, receives the token.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        private static ReturnCode AddCommand( /* CORE */
            bool trace,              /* in */
            Interpreter interpreter, /* in */
            ICommand command,        /* in */
            IClientData clientData,  /* in */
            ref long token,          /* out */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            ICommand localCommand;

            if (trace)
            {
                localCommand = new _TraceProxy(
                    new CommandData(command), command);
            }
            else
            {
                localCommand = command;
            }

            return interpreter.AddCommand(
                localCommand, clientData, ref token, ref result);
        }
#endif

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Adds the execute callback.
        /// </summary>
        /// <param name="trace">
        /// The trace.
        /// </param>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="name">
        /// The name.
        /// </param>
        /// <param name="callback">
        /// The execution callback to be invoked.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="plugin">
        /// The plugin.
        /// </param>
        /// <param name="token">
        /// Upon return, receives the token.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        private static ReturnCode AddExecuteCallback( /* CORE */
            bool trace,               /* in */
            Interpreter interpreter,  /* in */
            string name,              /* in */
            ExecuteCallback callback, /* in */
            IClientData clientData,   /* in */
            IPlugin plugin,           /* in */
            ref long token,           /* out */
            ref Result result         /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            ExecuteCallback localCallback;

            if (trace)
                localCallback = new TraceProxy(callback).Execute;
            else
                localCallback = callback;

            return interpreter.AddExecuteCallback(
                name, localCallback, clientData, plugin, ref token,
                ref result);
        }

