        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Removes the tokens.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="plugin">
        /// The plugin.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="tokens">
        /// On input, supplies the tokens; upon return, receives the updated
        /// value.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode RemoveTokens( /* CORE */
            Interpreter interpreter, /* in */
            IPlugin plugin,          /* in */
            IClientData clientData,  /* in */
            ref long[] tokens,       /* in, out */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (tokens == null)
            {
                result = "invalid command tokens";
                return ReturnCode.Error;
            }

            int length = tokens.Length;

            for (int index = length - 1; index >= 0; index--)
            {
                long token = tokens[index];

                if (token == 0)
                    continue;

                ReturnCode removeCode;
                Result removeResult = null;

                removeCode = interpreter.RemoveCommand(
                    token, clientData, ref removeResult);

                if (removeCode != ReturnCode.Ok)
                {
                    Utility.Complain(
                        interpreter, removeCode, removeResult);
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets the base path.
        /// </summary>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <returns>
        /// The base path produced by the operation.
        /// </returns>
        public static string GetBasePath( /* CORE */
            IClientData clientData /* in */
            )
        {
            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
                return null;

            string fileName = evaluateClientData.FileName;

            if (String.IsNullOrEmpty(fileName))
                return null;

            string directory = Path.GetDirectoryName(fileName);

            if (String.IsNullOrEmpty(directory))
                return null;

            if (directory[0] == Characters.Period)
                return null;

            return directory;
        }
    }
    #endregion

