    #region Command Callbacks Class (Configuration)
    /// <summary>
    /// Provides the callback methods that implement the behavior of the
    /// licensing commands.
    /// </summary>
#if OBFUSCATION
    [Obfuscation(Feature = "renaming")]
#endif
    [ObjectId("263539a1-992b-4cfc-97bc-f05538d10d69")]
    internal static class Callbacks
    {
#if NETWORK
        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>offlineMode</c> configuration command, which
        /// gets or sets the plugin offline-mode flag (a nullable boolean)
        /// stored in the evaluation context.  With no argument the current
        /// value is returned; supplying an argument parses a new boolean
        /// value, stores it, and signals the context change so dependent
        /// state is refreshed.  When enabled, offline mode suppresses
        /// outbound network activity such as remote time verification and
        /// license retrieval.  Available only when compiled with
        /// <c>NETWORK</c> support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode OfflineMode( /* CORE */ /* WR-CTX */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 1) || (argumentCount > 2))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} ?enable?\"",
                    Constants.OfflineModeCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            Result value; /* REUSED */
            bool? oldEnable;

            value = null; /* bool */

            if (interpreter.GetVariableValue(
                    Constants.ContextGetVariableFlags,
                    Constants.PluginOfflineModeVariableName,
                    ref value, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;

            if (String.IsNullOrEmpty(value))
            {
                oldEnable = null;
            }
            else
            {
                oldEnable = null;

                if (Value.GetNullableBoolean2(
                        value, ValueFlags.AnyBoolean, cultureInfo,
                        ref oldEnable, ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }
            }

            if (argumentCount == 2)
            {
                bool? newEnable = null;

                if (Value.GetNullableBoolean2(
                        arguments[1], ValueFlags.AnyBoolean, cultureInfo,
                        ref newEnable, ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                value = newEnable;

                if (interpreter.SetVariableValue(
                        Constants.ContextSetVariableFlags,
                        Constants.PluginOfflineModeVariableName,
                        value, null, ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                /* IGNORED */
                ScriptContext.SignalChanged(clientData,
                    Constants.PluginOfflineModeVariableName);

                result = newEnable;
            }
            else
            {
                result = oldEnable;
            }

            return ReturnCode.Ok;
        }
#endif

        ///////////////////////////////////////////////////////////////////////

#if SHELL
        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>interactiveLoop</c> configuration command, which
        /// enters a nested interactive shell read-eval-print loop in the
        /// context of the current configuration evaluation.  This is
        /// primarily a debugging and diagnostic aid for inspecting and
        /// adjusting configuration state interactively.  Available only when
        /// compiled with <c>SHELL</c> support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode InteractiveLoop( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if (argumentCount != 1)
            {
                result = String.Format(
                    "wrong # args: should be \"{0}\"",
                    Constants.InteractiveLoopCommandName);

                return ReturnCode.Error;
            }

            return Helpers.InteractiveLoop(
                interpreter, clientData, ref result);
        }

        ///////////////////////////////////////////////////////////////////////

#if CERTIFICATE_PLUGIN && CERTIFICATE_POLICY && PLUGIN_COMMANDS
        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>requireShell</c> configuration command, which
        /// gets or sets the shell configuration flags for the current
        /// context.  Supplying an empty flags value unsets the shell
        /// configuration entirely; supplying a non-empty value parses and
        /// stores it.  Available only when compiled with shell, certificate
        /// plugin, certificate policy, and plugin command support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode RequireShell( /* CORE */ /* WR-CTX */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 1) || (argumentCount > 2))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} ?flags?\"",
                    Constants.RequireNetworkCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            Result value; /* REUSED */
            object enumValue; /* REUSED */
            ShellFlags? shellFlags;

            value = null; /* bool */

            if (interpreter.GetVariableValue(
                    Constants.ContextGetVariableFlags,
                    Constants.PluginShellFlagsVariableName,
                    ref value, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;

            if (String.IsNullOrEmpty(value))
            {
                shellFlags = null;
            }
            else
            {
                enumValue = Utility.TryParseFlagsEnum(
                    interpreter, typeof(ShellFlags),
                    null, value, cultureInfo, true, true,
                    true, ref result);

                if (!(enumValue is ShellFlags))
                    return ReturnCode.Error;

                shellFlags = (ShellFlags)enumValue;
                value = shellFlags.ToString();
            }

            if (argumentCount == 2)
            {
                string enumString = arguments[1];

                //
                // HACK: If an empty string is specified,
                //       just convert it to a null value.
                //       This will cause the code below
                //       to unset the property instead of
                //       setting it.
                //
                if (String.IsNullOrEmpty(enumString))
                    enumString = null;

                if (enumString != null)
                {
                    enumValue = Utility.TryParseFlagsEnum(
                        interpreter, typeof(ShellFlags), value,
                        enumString, cultureInfo, true, true,
                        true, ref result);

                    if (!(enumValue is ShellFlags))
                        return ReturnCode.Error;

                    shellFlags = (ShellFlags)enumValue;
                    value = shellFlags.ToString();

                    if (interpreter.SetVariableValue(
                            Constants.ContextSetVariableFlags,
                            Constants.PluginShellFlagsVariableName,
                            value, null, ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
                }
                else
                {
                    //
                    // HACK: Unsetting context script variable is
                    //       needed here to permit the associated
                    //       internal state to be completely reset,
                    //       due to the value conversion algorithm
                    //       used by ApplyVariables.
                    //
                    if (interpreter.UnsetVariable(
                            Constants.ContextUnsetVariableFlags,
                            Constants.PluginShellFlagsVariableName,
                            ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    value = enumString; /* null */
                }

                /* IGNORED */
                ScriptContext.SignalChanged(clientData,
                    Constants.PluginShellFlagsVariableName);
            }

            result = value;
            return ReturnCode.Ok;
        }
#endif
#endif

