#if CERTIFICATE_PLUGIN && CERTIFICATE_POLICY
        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>forEachPolicyType</c> configuration command,
        /// which iterates over every defined policy type, assigning each in
        /// turn to the named iteration variable and evaluating the supplied
        /// body script.  Errors from individual iterations are accumulated.
        /// Available only when compiled with certificate plugin and
        /// certificate policy support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode ForEachPolicyType( /* CORE? */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if (argumentCount != 3)
            {
                result = String.Format(
                    "wrong # args: should be \"{0} varName script\"",
                    Constants.ForEachPolicyTypeCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            //
            // TODO: Maybe this should not be required?  This command
            //       does not actually modify any important state by
            //       itself.
            //
            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            IEnumerable<PolicyType> policyTypes =
                PolicyOps.GetPolicyTypes();

            if (policyTypes == null)
            {
                result = "policy types not available";
                return ReturnCode.Error;
            }

            string varName = arguments[1];

            if (String.IsNullOrEmpty(varName))
                varName = null;

            string text = arguments[2];

            if (String.IsNullOrEmpty(text))
                text = null;

            ReturnCode code;
            ResultList errors = null;
            bool setVariable = false;

            try
            {
                int iterationLimit = interpreter.IterationLimit;
                int iterationCount = 0;

                foreach (PolicyType policyType in policyTypes)
                {
                    if (text == null)
                        continue;

                    Result localResult; /* REUSED */

                    if (varName != null)
                    {
                        localResult = null;

                        if (interpreter.SetVariableValue(
                                varName, policyType.ToString(),
                                ref localResult) == ReturnCode.Ok)
                        {
                            setVariable = true;
                        }
                        else
                        {
                            if (errors == null)
                                errors = new ResultList();

                            if (localResult != null)
                            {
                                errors.Add(localResult);
                            }
                            else
                            {
                                errors.Add(String.Format(
                                    "could not set loop variable {0}",
                                    Utility.FormatWrapOrNull(varName)));
                            }

                            break;
                        }
                    }

                    localResult = null;

                    if (interpreter.EvaluateScript(
                            text, ref localResult) != ReturnCode.Ok)
                    {
                        if (errors == null)
                            errors = new ResultList();

                        if (localResult != null)
                        {
                            errors.Add(String.Format(
                                "error for script block {0}",
                                Utility.FormatWrapOrNull(policyType)));

                            errors.Add(localResult);
                        }
                        else
                        {
                            errors.Add(String.Format(
                                "null error for script block {0}",
                                Utility.FormatWrapOrNull(policyType)));
                        }

                        break;
                    }

                    if ((iterationLimit != Limits.Unlimited) &&
                        (++iterationCount > iterationLimit))
                    {
                        if (errors == null)
                            errors = new ResultList();

                        errors.Add(String.Format(
                            "iteration limit {0} exceeded",
                            iterationLimit));

                        break;
                    }
                }
            }
            finally
            {
                if (setVariable)
                {
                    Result unsetError = null;

                    if (interpreter.UnsetVariable(
                            varName, ref unsetError) != ReturnCode.Ok)
                    {
                        if (errors == null)
                            errors = new ResultList();

                        if (unsetError != null)
                        {
                            errors.Add(unsetError);
                        }
                        else
                        {
                            errors.Add(String.Format(
                                "could not unset loop variable {0}",
                                Utility.FormatWrapOrNull(varName)));
                        }
                    }
                }

                ///////////////////////////////////////////////////////////////

                if (errors != null)
                {
                    result = errors;
                    code = ReturnCode.Error;
                }
                else
                {
                    code = ReturnCode.Ok;
                }
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>addCertificates</c> configuration command, which
        /// registers certificate-based snippets for the current context.
        /// When a non-empty path is supplied, certificate snippets are loaded
        /// from that path subject to the given snippet and lookup flags; when
        /// the path is empty, the names of the existing snippets are listed
        /// instead.  Available only when compiled with certificate plugin and
        /// certificate policy support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode AddCertificates( /* CORE? */ /* STATE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 2) || (argumentCount > 4))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} path " +
                    "?snippetFlags? ?lookupFlags?\"",
                    Constants.AddCertificatesCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            SnippetFlags snippetFlags = SnippetFlags.Default;
            LookupFlags lookupFlags = LookupFlags.Default;

            if (Helpers.GetSnippetFlags(
                    interpreter, arguments, cultureInfo, 2,
                    true, ref snippetFlags, ref lookupFlags,
                    ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            string path = arguments[1];
            IEnumerable<string> names = null;

            if (!String.IsNullOrEmpty(path))
            {
                ResultList errors = null;

                if (interpreter.AddSnippetsForCertificates(
                        path, snippetFlags, lookupFlags,
                        ref names, ref errors) != ReturnCode.Ok)
                {
                    result = errors;
                    return ReturnCode.Error;
                }
            }
            else
            {
                if (interpreter.ListSnippets(
                        null, false, snippetFlags |
                            SnippetFlags.MaybeUseXmlOnlyMask,
                        lookupFlags, ref names,
                        ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }
            }

            result = (names != null) ?
                new StringList(names) : null;

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>addPublicKey</c> configuration command, which
        /// adds a public key (described by its metadata and key data) to the
        /// context key pair collection, optionally recording the resulting
        /// descriptor in the named variable.  Returns a list of policy-type /
        /// key-name / public-key-token descriptors for the keys added.
        /// Available only when compiled with certificate plugin and
        /// certificate policy support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode AddPublicKey( /* CORE? */ /* STATE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 3) || (argumentCount > 4))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} " +
                    "metadata data ?varName?\"",
                    Constants.AddPublicKeyCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            string keyName = null;
            IKeyPair keyPair = null;

            if (Helpers.AddPublicKey(
                    interpreter, evaluateClientData, arguments[1],
                    arguments[2], null, null, ref keyName, ref keyPair,
                    ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

#if DEBUG || FORCE_TRACE
            CertificateTraceOps.DebugTrace(String.Format(
                "AddPublicKey: interpreter = {0}, " +
                "keyName = {1}, keyPair = {2}",
                DataOps.FormatInterpreter(
                    interpreter, true, false),
                Utility.FormatWrapOrNull(keyName),
                Utility.FormatWrapOrNull(keyPair)),
                typeof(Callbacks).Name, TracePriority.MediumLow);

            DebugOnlyOps.DumpKeyPairs(
                interpreter, "AddPublicKey", null,
                evaluateClientData.KeyPairs, typeof(Callbacks).Name,
                PolicyType.Script, TracePriority.Highest);
#endif

            string value = null;

            if (keyPair != null)
            {
                value = StringList.MakeList(
                    PolicyType.None, keyName,
                    DataOps.FormatPublicKeyToken(
                        keyPair.PublicKeyToken, false, false));
            }
            else
            {
                value = keyName;
            }

            if (argumentCount == 4)
            {
                string varName = arguments[3];

                if (String.IsNullOrEmpty(varName))
                    varName = null;

                if (varName != null)
                {
                    if (interpreter.SetVariableValue(
                            Constants.SetVariableFlags,
                            varName, value, null,
                            ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
                }
            }

            result = value;
            return ReturnCode.Ok;
        }

