        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>addRingPublicKey</c> configuration command,
        /// which adds a public key to the key ring associated with a specific
        /// policy type (defaulting to the license policy type when omitted),
        /// optionally recording the result in the named variable.  Available
        /// only when compiled with certificate plugin and certificate policy
        /// support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode AddRingPublicKey( /* CORE? */ /* STATE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 3) || (argumentCount > 5))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} " +
                    "metadata data ?varName? ?policyType?\"",
                    Constants.AddRingPublicKeyCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            PolicyType policyType = PolicyType.License;
            string enumString;
            object enumValue;

            if (argumentCount == 5)
            {
                enumString = arguments[4];

                if (String.IsNullOrEmpty(enumString))
                    enumString = null;

                if (enumString != null)
                {
                    enumValue = Utility.TryParseFlagsEnum(
                        interpreter, typeof(PolicyType),
                        policyType.ToString(), enumString,
                        cultureInfo, true, true, true,
                        ref result);

                    if (!(enumValue is PolicyType))
                        return ReturnCode.Error;

                    policyType = (PolicyType)enumValue;
                }
            }

            string keyName = null;
            IKeyPair keyPair = null;

            if (Helpers.AddPublicKey(
                    interpreter, evaluateClientData, arguments[1],
                    arguments[2], null, policyType, ref keyName,
                    ref keyPair, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

#if DEBUG || FORCE_TRACE
            CertificateTraceOps.DebugTrace(String.Format(
                "AddRingPublicKey: interpreter = {0}, " +
                "policyType = {1}, keyName = {2}, keyPair = {3}",
                DataOps.FormatInterpreter(
                    interpreter, true, false),
                Utility.FormatWrapOrNull(policyType),
                Utility.FormatWrapOrNull(keyName),
                Utility.FormatWrapOrNull(keyPair)),
                typeof(Callbacks).Name, TracePriority.MediumLow);
#endif

            string value = null;

            if (keyPair != null)
            {
                value = StringList.MakeList(
                    policyType, keyName,
                    DataOps.FormatPublicKeyToken(
                        keyPair.PublicKeyToken, false, false));
            }
            else
            {
                value = keyName;
            }

            if (argumentCount >= 4)
            {
                string varName = arguments[3];

                if (String.IsNullOrEmpty(varName))
                    varName = null;

                if (varName != null)
                {
                    if (interpreter.SetVariableValue(
                            Constants.SetVariableFlags,
                            varName, value, null,
                            ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
                }
            }

            result = value;
            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>havePublicKey</c> configuration command, which
        /// tests whether a given public key is present in the context key
        /// pair collection, returning a boolean.  Available only when
        /// compiled with certificate plugin and certificate policy support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode HavePublicKey( /* CORE? */ /* STATE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if (argumentCount != 2)
            {
                result = String.Format(
                    "wrong # args: should be \"{0} keyPair\"",
                    Constants.HavePublicKeyCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            IList<IKeyPair> keyPairs =
                evaluateClientData.KeyPairs as IList<IKeyPair>;

            if (keyPairs == null)
            {
                result = "missing context key pairs";
                return ReturnCode.Error;
            }

            string keyName = arguments[1];
            byte[] publicKeyToken = null;

            /* IGNORED */
            DataOps.ParsePublicKeyToken(keyName, ref publicKeyToken);

            bool found = false;

            foreach (IKeyPair keyPair in keyPairs)
            {
                if (keyPair == null)
                    continue;

                if (!keyPair.HavePublicKey)
                    continue;

                if ((publicKeyToken != null) &&
                    DataOps.MatchPublicKeyToken(
                        keyPair.PublicKeyToken, publicKeyToken))
                {
                    found = true;
                    break;
                }

                if (keyName == null)
                {
                    found = true;
                    break;
                }

                IIdentifier identifier = keyPair as IIdentifier;

                if (identifier == null)
                    continue;

                if (DataOps.StringEquals(identifier.Name, keyName))
                {
                    found = true;
                    break;
                }
            }

            result = found;
            return ReturnCode.Ok;
        }

