        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>requireMachine</c> configuration command, which
        /// requires that the current machine's identifying GUID appears in
        /// the supplied list of allowed machine GUIDs; an empty GUID in the
        /// list acts as a wildcard that matches any machine.  Returns the
        /// GUID that matched.  Available only when compiled with certificate
        /// plugin and certificate policy support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode RequireMachine( /* CORE? */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 2) || (argumentCount > 3))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} list ?flags?\"",
                    Constants.RequireMachineCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            PathFlags pathFlags = LicenseState.GetPathFlagsOrDefault();

            object enumValue;

            if (argumentCount == 3)
            {
                enumValue = Utility.TryParseFlagsEnum(
                    interpreter, typeof(PathFlags),
                    pathFlags.ToString(), arguments[2],
                    cultureInfo, true, true, true, ref result);

                if (!(enumValue is PathFlags))
                    return ReturnCode.Error;

                pathFlags = (PathFlags)enumValue;
            }

            GuidList ids = Helpers.GetGuidList(
                interpreter, cultureInfo, arguments[1], ref result);

            if (ids == null)
                return ReturnCode.Error;

            Guid? id = PolicyOps.GetMachineId(
                interpreter, null, cultureInfo, pathFlags, ref result);

            if (id == null)
                return ReturnCode.Error;

            if (ids.ContainsKey(Guid.Empty)) /* ANY VALID */
            {
                result = Guid.Empty;
                return ReturnCode.Ok;
            }

            if (ids.ContainsKey((Guid)id))
            {
                result = (Guid)id;
                return ReturnCode.Ok;
            }

            result = String.Format(
                "wrong machine identifier {0}",
                Utility.FormatWrapOrNull(id));

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>requirePublicKey</c> configuration command,
        /// which requires that a specific public key token is available for
        /// the given policy type (defaulting to the script policy type),
        /// failing the configuration when it is not.  Available only when
        /// compiled with certificate plugin and certificate policy support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode RequirePublicKey( /* CORE? */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 2) || (argumentCount > 3))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} " +
                    "publicKeyToken ?policyType?\"",
                    Constants.RequirePublicKeyCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            PolicyType policyType = PolicyType.Script;
            string enumString;
            object enumValue;

            if (argumentCount == 3)
            {
                enumString = arguments[2];

                if (String.IsNullOrEmpty(enumString))
                    enumString = null;

                if (enumString != null)
                {
                    enumValue = Utility.TryParseFlagsEnum(
                        interpreter, typeof(PolicyType),
                        policyType.ToString(), enumString,
                        cultureInfo, true, true, true,
                        ref result);

                    if (!(enumValue is PolicyType))
                        return ReturnCode.Error;

                    policyType = (PolicyType)enumValue;
                }
            }

            byte[] publicKeyToken = null;

            if (DataOps.ParsePublicKeyToken(
                    arguments[1], ref publicKeyToken,
                    ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            EntityType? entityType =
                SharedOps.PolicyTypeToEntityType(
                    policyType, ref result);

            if (entityType == null)
                return ReturnCode.Error;

            IEnumerable<IKeyPair> keyPairs = null;

            if (CertificateKeyPairOps.GetPublicOnly(
                    null, policyType, false,
                    AssemblyOps.GetObject(),
                    AssemblyOps.GetName(),
                    null, null, false, interpreter,
                    (EntityType)entityType, true, true,
                    true, false, true, ref keyPairs,
                    ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            keyPairs = CertificateKeyPairOps.FilterByToken(
                keyPairs, publicKeyToken, false, ref result);

            if (keyPairs != null)
            {
                return ReturnCode.Ok;
            }
            else
            {
                result = String.Format(
                    "required {0} public key {1} not found", policyType,
                    DataOps.FormatPublicKeyToken(publicKeyToken, true,
                    true));

                return ReturnCode.Error;
            }
        }

