        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>changePolicyProperty</c> configuration command,
        /// a generic getter/setter for the configurable properties of a
        /// policy type.  The supported property names are the key name, key
        /// ring name, current execution policy, script flags, path flags, and
        /// network flags; with no value the property is read, otherwise it is
        /// parsed and stored.  Available only when compiled with certificate
        /// plugin and certificate policy support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode ChangePolicyProperty( /* CORE? */ /* WR-CTX */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 3) || (argumentCount > 4))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} policyType " +
                    "propertyName ?propertyValue?\"",
                    Constants.ChangePolicyPropertyCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            object enumValue; /* REUSED */
            CultureInfo cultureInfo = evaluateClientData.CultureInfo;

            enumValue = Utility.TryParseFlagsEnum(
                interpreter, typeof(PolicyType), null,
                arguments[1], cultureInfo, true, true,
                true, ref result);

            if (!(enumValue is PolicyType))
                return ReturnCode.Error;

            PolicyType policyType = (PolicyType)enumValue;
            string propertyName = arguments[2];
            string propertyValue = null;

            if (arguments.Count == 4)
            {
                propertyValue = arguments[3];

                //
                // HACK: If an empty string is specified,
                //       just convert it to a null value.
                //       This will cause the code below
                //       to unset the property instead of
                //       setting it.
                //
                if (String.IsNullOrEmpty(propertyValue))
                    propertyValue = null;
            }

            Result value; /* REUSED */

            switch (propertyName)
            {
                case Constants.KeyNamePropertyName: /* type: String */
                case Constants.KeyRingNamePropertyName: /* type: String */
                    {
                        value = null;

                        if (PolicyConfiguration.GetPropertyValue(
                                interpreter, policyType,
                                propertyName, ref value,
                                ref result) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }

                        if (arguments.Count == 4)
                        {
                            if (propertyValue != null)
                            {
                                if (PolicyConfiguration.SetPropertyValue(
                                        interpreter, policyType,
                                        propertyName, propertyValue,
                                        ref result) != ReturnCode.Ok)
                                {
                                    return ReturnCode.Error;
                                }
                            }
                            else
                            {
                                if (PolicyConfiguration.UnsetPropertyValue(
                                        interpreter, policyType,
                                        propertyName,
                                        ref result) != ReturnCode.Ok)
                                {
                                    return ReturnCode.Error;
                                }
                            }

                            /* IGNORED */
                            PolicyConfiguration.SignalPropertyChanged(
                                clientData, policyType, propertyName);

                            result = propertyValue;
                        }
                        else
                        {
                            result = value;
                        }

                        return ReturnCode.Ok;
                    }
                case Constants.CurrentPolicyPropertyName: /* type: ExecutionPolicy */
                    {
                        value = null;

                        if (PolicyConfiguration.GetPropertyValue(
                                interpreter, policyType,
                                propertyName, ref value,
                                ref result) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }

                        if (value != null)
                            value = value.ToString();

                        if (arguments.Count == 4)
                        {
                            if (propertyValue != null)
                            {
                                enumValue = Utility.TryParseFlagsEnum(
                                    interpreter, typeof(ExecutionPolicy),
                                    value, propertyValue, cultureInfo,
                                    true, true, true, ref result);

                                if (!(enumValue is ExecutionPolicy))
                                    return ReturnCode.Error;

                                if (PolicyConfiguration.SetPropertyValue(
                                        interpreter, policyType,
                                        propertyName, enumValue,
                                        ref result) != ReturnCode.Ok)
                                {
                                    return ReturnCode.Error;
                                }

                                /* IGNORED */
                                PolicyConfiguration.SignalPropertyChanged(
                                    clientData, policyType, propertyName);

                                result = enumValue.ToString();
                            }
                            else
                            {
                                if (PolicyConfiguration.UnsetPropertyValue(
                                        interpreter, policyType,
                                        propertyName,
                                        ref result) != ReturnCode.Ok)
                                {
                                    return ReturnCode.Error;
                                }

                                /* IGNORED */
                                PolicyConfiguration.SignalPropertyChanged(
                                    clientData, policyType, propertyName);

                                result = propertyValue;
                            }
                        }
                        else
                        {
                            result = value;
                        }

                        return ReturnCode.Ok;
                    }
                case Constants.ScriptFlagsPropertyName: /* type: ScriptFlags */
                    {
                        value = null;

                        if (PolicyConfiguration.GetPropertyValue(
                                interpreter, policyType,
                                propertyName, ref value,
                                ref result) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }

                        if (value != null)
                            value = value.ToString();

                        if (arguments.Count == 4)
                        {
                            if (propertyValue != null)
                            {
                                enumValue = Utility.TryParseFlagsEnum(
                                    interpreter, typeof(ScriptFlags),
                                    value, propertyValue, cultureInfo,
                                    true, true, true, ref result);

                                if (!(enumValue is ScriptFlags))
                                    return ReturnCode.Error;

                                if (PolicyConfiguration.SetPropertyValue(
                                        interpreter, policyType,
                                        propertyName, enumValue,
                                        ref result) != ReturnCode.Ok)
                                {
                                    return ReturnCode.Error;
                                }

                                /* IGNORED */
                                PolicyConfiguration.SignalPropertyChanged(
                                    clientData, policyType, propertyName);

                                result = enumValue.ToString();
                            }
                            else
                            {
                                if (PolicyConfiguration.UnsetPropertyValue(
                                        interpreter, policyType,
                                        propertyName,
                                        ref result) != ReturnCode.Ok)
                                {
                                    return ReturnCode.Error;
                                }

                                /* IGNORED */
                                PolicyConfiguration.SignalPropertyChanged(
                                    clientData, policyType, propertyName);

                                result = propertyValue;
                            }
                        }
                        else
                        {
                            result = value;
                        }

                        return ReturnCode.Ok;
                    }
                case Constants.PathFlagsPropertyName: /* type: PathFlags */
                    {
                        value = null;

                        if (PolicyConfiguration.GetPropertyValue(
                                interpreter, policyType,
                                propertyName, ref value,
                                ref result) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }

                        if (value != null)
                            value = value.ToString();

                        if (arguments.Count == 4)
                        {
                            if (propertyValue != null)
                            {
                                enumValue = Utility.TryParseFlagsEnum(
                                    interpreter, typeof(PathFlags),
                                    value, propertyValue, cultureInfo,
                                    true, true, true, ref result);

                                if (!(enumValue is PathFlags))
                                    return ReturnCode.Error;

                                if (PolicyConfiguration.SetPropertyValue(
                                        interpreter, policyType,
                                        propertyName, enumValue,
                                        ref result) != ReturnCode.Ok)
                                {
                                    return ReturnCode.Error;
                                }

                                /* IGNORED */
                                PolicyConfiguration.SignalPropertyChanged(
                                    clientData, policyType, propertyName);

                                result = enumValue.ToString();
                            }
                            else
                            {
                                if (PolicyConfiguration.UnsetPropertyValue(
                                        interpreter, policyType,
                                        propertyName,
                                        ref result) != ReturnCode.Ok)
                                {
                                    return ReturnCode.Error;
                                }

                                /* IGNORED */
                                PolicyConfiguration.SignalPropertyChanged(
                                    clientData, policyType, propertyName);

                                result = propertyValue;
                            }
                        }
                        else
                        {
                            result = value;
                        }

                        return ReturnCode.Ok;
                    }
                case Constants.NetworkFlagsPropertyName: /* type: NetworkFlags */
                    {
                        value = null;

                        if (PolicyConfiguration.GetPropertyValue(
                                interpreter, policyType,
                                propertyName, ref value,
                                ref result) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }

                        if (value != null)
                            value = value.ToString();

                        if (arguments.Count == 4)
                        {
                            if (propertyValue != null)
                            {
                                enumValue = Utility.TryParseFlagsEnum(
                                    interpreter, typeof(NetworkFlags),
                                    value, propertyValue, cultureInfo,
                                    true, true, true, ref result);

                                if (!(enumValue is NetworkFlags))
                                    return ReturnCode.Error;

                                if (PolicyConfiguration.SetPropertyValue(
                                        interpreter, policyType,
                                        propertyName, enumValue,
                                        ref result) != ReturnCode.Ok)
                                {
                                    return ReturnCode.Error;
                                }

                                /* IGNORED */
                                PolicyConfiguration.SignalPropertyChanged(
                                    clientData, policyType, propertyName);

                                result = enumValue.ToString();
                            }
                            else
                            {
                                if (PolicyConfiguration.UnsetPropertyValue(
                                        interpreter, policyType,
                                        propertyName,
                                        ref result) != ReturnCode.Ok)
                                {
                                    return ReturnCode.Error;
                                }

                                /* IGNORED */
                                PolicyConfiguration.SignalPropertyChanged(
                                    clientData, policyType, propertyName);

                                result = propertyValue;
                            }
                        }
                        else
                        {
                            result = value;
                        }

                        return ReturnCode.Ok;
                    }
                default:
                    {
                        result = "unrecognized policy property name";
                        return ReturnCode.Error;
                    }
            }
        }

