        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>configurePackages</c> configuration command,
        /// which configures the package-if-needed mappings used by the
        /// plugin.  When the use-built-in-mappings flag is set the built-in
        /// assembly-to-plugin mappings are installed (requiring a test
        /// build); otherwise the mappings are copied from the certificate
        /// plugin state.  Available only when compiled with certificate
        /// plugin and certificate policy support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode ConfigurePackages( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 1) || (argumentCount > 2))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} ?flags?\"",
                    Constants.ConfigurePackagesCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            PackageIfNeededFlags flags = PackageIfNeededFlags.Default;
            string enumString;
            object enumValue;

            if (argumentCount == 2)
            {
                enumString = arguments[1];

                if (String.IsNullOrEmpty(enumString))
                    enumString = null;

                if (enumString != null)
                {
                    enumValue = Utility.TryParseFlagsEnum(
                        interpreter, typeof(PackageIfNeededFlags),
                        flags.ToString(), enumString,
                        cultureInfo, true, true, true,
                        ref result);

                    if (!(enumValue is PackageIfNeededFlags))
                        return ReturnCode.Error;

                    flags = (PackageIfNeededFlags)enumValue;
                }
            }

            AssemblyFilePluginNames mappings;

            if (Utility.HasFlags(
                    flags, PackageIfNeededFlags.UseBuiltInMappings, true))
            {
#if TEST
                mappings = _Test.TestGetAssemblyFilePluginNames(
                    interpreter, null, flags, ref result);
#else
                result = "not implemented";
                return ReturnCode.Error;
#endif
            }
            else
            {
                mappings = CertificatePluginState.CopyMappings();
            }

            return Utility.CreateAndEvaluatePackageIfNeededScripts(
                interpreter, mappings, AssemblyOps.GetDirectory(),
                null, Constants.EnterprisePublicKeyTokenBytes,
                cultureInfo, flags, ref result);
        }

