        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>enableSecurity</c> configuration command, which
        /// turns on the security policies for the context and, depending on
        /// the supplied enable-security flags, optionally bootstraps the key
        /// rings.  Returns a formatted summary describing what was enabled.
        /// Available only when compiled with certificate plugin and
        /// certificate policy support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode EnableSecurity( /* CORE? */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            //
            // WARNING: *SECURITY* Even after this configuration command
            //          has successfully enabled security policies and/or
            //          loaded the necessary (bootstrap) key rings, core
            //          library script certificates, et al, will probably
            //          NOT be available, i.e. unless one of the "Badge"
            //          plugins has been loaded beforehand.  During the
            //          initial "Harpy" plugin loading process, this is
            //          actually impossible because the "Badge" plugins
            //          rely upon the "Harpy" plugins for their license
            //          enforcement.  Thus, any attempts to load "Badge"
            //          plugins from here would cause infinite (mutual)
            //          recursion problems.
            //
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 1) || (argumentCount > 2))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} ?flags?\"",
                    Constants.EnableSecurityCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            EnableSecurityFlags flags = EnableSecurityFlags.Default;
            string enumString;
            object enumValue; /* REUSED */

            if (argumentCount == 2)
            {
                enumString = arguments[1];

                if (String.IsNullOrEmpty(enumString))
                    enumString = null;

                if (enumString != null)
                {
                    enumValue = Utility.TryParseFlagsEnum(
                        interpreter, typeof(EnableSecurityFlags),
                        flags.ToString(), enumString,
                        cultureInfo, true, true, true,
                        ref result);

                    if (!(enumValue is EnableSecurityFlags))
                        return ReturnCode.Error;

                    flags = (EnableSecurityFlags)enumValue;
                }
            }

            if (SharedOps.HasFlags(flags,
                    EnableSecurityFlags.SkipIfInitialize, true) &&
                SharedOps.HasFlags(
                    evaluateClientData.ConfigurationPhase,
                    ConfigurationPhase.InitializeMask, false))
            {
                result = "skipped, initialize pending";
                return ReturnCode.Ok;
            }

            IPluginData pluginData = evaluateClientData.Plugin;
            bool wasEnabled;

            if (KeyRingOps.IsBaseScriptPolicyAllowSignedOnly(
                    interpreter, pluginData))
            {
                wasEnabled = true;
            }
            else
            {
                wasEnabled = false;
            }

            if (wasEnabled && SharedOps.HasFlags(flags,
                    EnableSecurityFlags.SkipIfEnabled, true))
            {
                result = "skipped, already enabled";
                return ReturnCode.Ok;
            }

            bool? enable = Helpers.SecurityShouldBeEnabled(
                interpreter, pluginData, flags);

            bool shouldBootstrap = false;

            if (Helpers.ShouldBootstrapKeyPairs(flags,
                    wasEnabled, enable, ref shouldBootstrap,
                    ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            bool skipEnable = false;

            if (!shouldBootstrap && SharedOps.HasFlags(flags,
                    EnableSecurityFlags.WithKeyRingsOnly, true))
            {
                skipEnable = true;
            }

            bool allowAnyPlugin = SharedOps.HasFlags(
                flags, EnableSecurityFlags.AllowAnyPlugin, true);

            bool localOnly = Helpers.SecurityShouldBeLocalOnly(
                pluginData, flags);

            bool ignoreErrors = Helpers.SecurityShouldBeIgnoreErrors(
                pluginData, flags);

            if (!skipEnable &&
                PolicyOps.MaybeEnableOrDisable(interpreter,
                    pluginData, enable, allowAnyPlugin, localOnly,
                    ignoreErrors, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            bool isEnabled;
            int? loaded = null;

            if (KeyRingOps.IsBaseScriptPolicyAllowSignedOnly(
                    interpreter, pluginData))
            {
                isEnabled = true;

                if (shouldBootstrap)
                {
                    if (Helpers.BootstrapKeyPairs(
                            interpreter, pluginData,
                            cultureInfo, ref loaded,
                            ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
                }
            }
            else
            {
                isEnabled = false;
            }

            result = Helpers.ResultForEnableSecurity(
                interpreter, wasEnabled, skipEnable, enable,
                isEnabled, loaded);

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>evaluateFile</c> configuration command, which
        /// evaluates a script file subject to optional evaluate-command flags
        /// and an optional base64-encoded password.  The flags select the
        /// evaluation mode: as a bundle file, by way of the shell, with
        /// signature verification, as a trusted file, or plain evaluation;
        /// when the no-complain flag is set the outcome is wrapped as a
        /// {returnCode result} list rather than propagating an error.
        /// Available only when compiled with certificate plugin and
        /// certificate policy support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode EvaluateFile( /* CORE? */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 2) || (argumentCount > 4))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} fileName ?flags? ?password?\"",
                    Constants.EvaluateFileCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            EvaluateCommandFlags flags = EvaluateCommandFlags.Default;
            string enumString;
            object enumValue; /* REUSED */

            if (argumentCount >= 3)
            {
                enumString = arguments[2];

                if (String.IsNullOrEmpty(enumString))
                    enumString = null;

                if (enumString != null)
                {
                    enumValue = Utility.TryParseFlagsEnum(
                        interpreter, typeof(EvaluateCommandFlags),
                        flags.ToString(), enumString,
                        cultureInfo, true, true, true,
                        ref result);

                    if (!(enumValue is EvaluateCommandFlags))
                        return ReturnCode.Error;

                    flags = (EvaluateCommandFlags)enumValue;
                }
            }

            byte[] password = null;

            if (argumentCount == 4)
            {
                try
                {
                    password = Convert.FromBase64String(
                        arguments[3]); /* throw */
                }
                catch (Exception e)
                {
                    result = e;
                    return ReturnCode.Error;
                }
            }

            string fileName = arguments[1];
            IPluginData pluginData = evaluateClientData.Plugin;
            Result localResult; /* REUSED */

            if (!KeyRingOps.IsBaseScriptPolicyAllowSignedOnly(
                    interpreter, pluginData))
            {
                localResult = String.Format(
                    "base script policy is not {0}",
                    ExecutionPolicy.AllowSignedOnly);

                if (SharedOps.HasFlags(flags,
                        EvaluateCommandFlags.SkipSignedOnly, true))
                {
#if DEBUG || FORCE_TRACE
                    CertificateTraceOps.MaybeLogAndDebugTrace(
                        String.Format(
                            "EvaluateFile: ALLOWING SCRIPT FILE " +
                            "{0} WITH FLAGS {1} IN INTERPRETER {2} " +
                            "VIA PLUGIN {3} DESPITE ERROR: {4}",
                            Utility.FormatWrapOrNull(fileName),
                            Utility.FormatWrapOrNull(flags),
                            DataOps.FormatInterpreter(
                                interpreter, true, false),
                            Utility.FormatWrapOrNull(pluginData),
                            Utility.FormatWrapOrNull(localResult)),
                        typeof(Callbacks).Name,
                        TracePriority.MediumHigh, 0);
#endif
                }
                else
                {
                    result = localResult;
                    return ReturnCode.Error;
                }
            }

            int? timeout = evaluateClientData.Timeout;

            if (timeout == null)
                timeout = SharedOps.GetTimeout(interpreter, null);

            TrustFlags trustFlags = Constants.FileTrustFlags;
            ReturnCode localCode;

            if (SharedOps.HasFlags(
                    flags, EvaluateCommandFlags.ViaBundle, true))
            {
#if DATA
                //
                // TODO: Are these the best bundle flags to use
                //       here?
                //
                BundleFlags bundleFlags =
                    BundleFlags.Default |
                    BundleFlags.RequireKeyRing;

                if (SharedOps.HasFlags(flags,
                        EvaluateCommandFlags.ErrorOnEmpty, true))
                {
                    bundleFlags |= BundleFlags.ErrorOnEmpty;
                }

                if (SharedOps.HasFlags(flags,
                        EvaluateCommandFlags.StopOnError, true))
                {
                    bundleFlags |= BundleFlags.StopOnError;
                }

                localResult = null;

                localCode = interpreter.EvaluateBundleFile(
                    fileName, password, bundleFlags,
                    ref clientData, ref localResult);
#else
                result = "not implemented";
                return ReturnCode.Error;
#endif
            }
            else if (SharedOps.HasFlags(
                    flags, EvaluateCommandFlags.ViaShell, true))
            {
#if SHELL && CERTIFICATE_PLUGIN && CERTIFICATE_POLICY && PLUGIN_COMMANDS
                ShellFlags shellFlags;

                if (SharedOps.HasFlags(
                        flags, EvaluateCommandFlags.StrictShell, true))
                {
                    shellFlags = ShellFlags.None;
                }
                else
                {
                    shellFlags = ShellFlags.Legacy;
                }

                localResult = null;

                localCode = ShellOps.EvaluateFile(
                    interpreter, fileName, timeout,
                    shellFlags, ref localResult);
#else
                result = "not implemented";
                return ReturnCode.Error;
#endif
            }
            else if (SharedOps.HasFlags(
                    flags, EvaluateCommandFlags.WithVerify, true))
            {
                byte[] signature = null;

                if (!DataOps.TryReadSignatureFile(
                        interpreter, evaluateClientData.Encoding,
                        DataOps.FormatSignatureFileName(fileName),
                        timeout, evaluateClientData.AllowRemoteUri,
                        ref signature, ref result))
                {
                    return ReturnCode.Error;
                }

                string text = null;
                byte[] hashValue = null; /* NOT USED */
                IKeyPair keyPair = null;

                if (ScriptOps.VerifyFile(
                        interpreter, evaluateClientData, fileName,
                        signature, evaluateClientData.Timeout,
                        evaluateClientData.AllowRemoteUri,
                        true /* NO-XML */, ref text, ref hashValue,
                        ref keyPair, ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                string keyUsage = __KeyUsage.Source;

                if ((keyUsage != null) &&
                    (ScriptOps.CheckKeyUsage(
                        keyPair, keyUsage, EntityType.File,
                        ref result) != ReturnCode.Ok))
                {
                    return ReturnCode.Error;
                }

                if (SharedOps.HasFlags(
                        flags, EvaluateCommandFlags.WithTrust, true))
                {
                    localResult = null;

                    localCode = interpreter.EvaluateTrustedScript(
                        fileName, text, trustFlags, ref localResult);
                }
                else
                {
                    localResult = null;

                    localCode = interpreter.EvaluateScript(
                        fileName, text, ref localResult);
                }
            }
            else if (SharedOps.HasFlags(
                    flags, EvaluateCommandFlags.WithTrust, true))
            {
                localResult = null;

                localCode = interpreter.EvaluateTrustedFile(
                    evaluateClientData.Encoding, fileName,
                    trustFlags, ref localResult);
            }
            else
            {
                localResult = null;

                localCode = interpreter.EvaluateFile(fileName,
                    ref localResult);
            }

            if (SharedOps.HasFlags(
                    flags, EvaluateCommandFlags.NoComplain, true))
            {
                result = StringList.MakeList(
                    localCode, localResult);

                return ReturnCode.Ok;
            }
            else
            {
                result = localResult;
                return localCode;
            }
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>evaluateStream</c> configuration command, which
        /// evaluates a script read from an embedded resource stream in the
        /// named assembly (defaulting to the current assembly).  The flags
        /// select among verify, trust, and plain evaluation modes.  Available
        /// only when compiled with certificate plugin and certificate policy
        /// support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode EvaluateStream( /* CORE? */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 2) || (argumentCount > 4))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} fileName ?assembly? " +
                    "?flags?\"", Constants.EvaluateStreamCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            Stream stream = null;
            Assembly assembly = AssemblyOps.GetObject();

            if (argumentCount >= 3)
            {
                string assemblyString = arguments[2];

                if (String.IsNullOrEmpty(assemblyString))
                    assemblyString = null;

                if (assemblyString != null)
                {
                    assembly = Utility.FindAssemblyInAppDomain(
                        interpreter, null, MatchMode.Glob,
                        assemblyString, false, null, ref result);

                    if (assembly == null)
                        return ReturnCode.Error;
                }
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            EvaluateCommandFlags flags = EvaluateCommandFlags.Default;
            string enumString;
            object enumValue; /* REUSED */

            if (argumentCount == 4)
            {
                enumString = arguments[3];

                if (String.IsNullOrEmpty(enumString))
                    enumString = null;

                if (enumString != null)
                {
                    enumValue = Utility.TryParseFlagsEnum(
                        interpreter, typeof(EvaluateCommandFlags),
                        flags.ToString(), enumString,
                        cultureInfo, true, true, true,
                        ref result);

                    if (!(enumValue is EvaluateCommandFlags))
                        return ReturnCode.Error;

                    flags = (EvaluateCommandFlags)enumValue;
                }
            }

            string fileName = arguments[1];

            stream = SharedOps.GetStream(
                assembly, fileName, ref result);

            if (stream == null)
                return ReturnCode.Error;

            IPluginData pluginData = evaluateClientData.Plugin;
            Result localResult; /* REUSED */

            if (!KeyRingOps.IsBaseScriptPolicyAllowSignedOnly(
                    interpreter, pluginData))
            {
                localResult = String.Format(
                    "base script policy is not {0}",
                    ExecutionPolicy.AllowSignedOnly);

                if (SharedOps.HasFlags(flags,
                        EvaluateCommandFlags.SkipSignedOnly, true))
                {
#if DEBUG || FORCE_TRACE
                    CertificateTraceOps.MaybeLogAndDebugTrace(
                        String.Format(
                            "EvaluateStream: ALLOWING SCRIPT STREAM " +
                            "{0} WITH FLAGS {1} IN INTERPRETER {2} " +
                            "VIA PLUGIN {3} DESPITE ERROR: {4}",
                            Utility.FormatWrapOrNull(fileName),
                            Utility.FormatWrapOrNull(flags),
                            DataOps.FormatInterpreter(
                                interpreter, true, false),
                            Utility.FormatWrapOrNull(pluginData),
                            Utility.FormatWrapOrNull(localResult)),
                        typeof(Callbacks).Name,
                        TracePriority.MediumHigh, 0);
#endif
                }
                else
                {
                    result = localResult;
                    return ReturnCode.Error;
                }
            }

            TrustFlags trustFlags = Constants.FileTrustFlags;
            ReturnCode localCode;

            if (SharedOps.HasFlags(
                    flags, EvaluateCommandFlags.ViaBundle, true))
            {
                result = "not implemented";
                return ReturnCode.Error;
            }
            else if (SharedOps.HasFlags(
                    flags, EvaluateCommandFlags.ViaShell, true))
            {
                result = "not implemented";
                return ReturnCode.Error;
            }
            else if (SharedOps.HasFlags(
                    flags, EvaluateCommandFlags.WithVerify, true))
            {
                byte[] signature = null;

                if (!DataOps.TryReadSignatureStream(
                        assembly, evaluateClientData.Encoding,
                        DataOps.FormatSignatureFileName(fileName),
                        ref signature, ref result))
                {
                    return ReturnCode.Error;
                }

                string text = null;
                byte[] hashValue = null; /* NOT USED */
                IKeyPair keyPair = null;

                if (ScriptOps.VerifyStream(
                        interpreter, evaluateClientData,
                        fileName, stream, signature,
                        evaluateClientData.Timeout,
                        evaluateClientData.AllowRemoteUri,
                        ref text, ref hashValue, ref keyPair,
                        ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                string keyUsage = __KeyUsage.Source;

                if ((keyUsage != null) &&
                    (ScriptOps.CheckKeyUsage(
                        keyPair, keyUsage, EntityType.File,
                        ref result) != ReturnCode.Ok))
                {
                    return ReturnCode.Error;
                }

                if (SharedOps.HasFlags(
                        flags, EvaluateCommandFlags.WithTrust, true))
                {
                    localResult = null;

                    localCode = interpreter.EvaluateTrustedScript(
                        fileName, text, trustFlags, ref localResult);
                }
                else
                {
                    localResult = null;

                    localCode = interpreter.EvaluateScript(
                        fileName, text, ref localResult);
                }
            }
            else if (SharedOps.HasFlags(
                    flags, EvaluateCommandFlags.WithTrust, true))
            {
                using (StreamReader streamReader = new StreamReader(
                        stream))
                {
                    localResult = null;

                    localCode = interpreter.EvaluateTrustedStream(
                        fileName, streamReader, trustFlags,
                        ref localResult);
                }
            }
            else
            {
                using (StreamReader streamReader = new StreamReader(
                        stream))
                {
                    localResult = null;

                    localCode = interpreter.EvaluateStream(
                        fileName, streamReader, ref localResult);
                }
            }

            if (SharedOps.HasFlags(
                    flags, EvaluateCommandFlags.NoComplain, true))
            {
                result = StringList.MakeList(
                    localCode, localResult);

                return ReturnCode.Ok;
            }
            else
            {
                result = localResult;
                return localCode;
            }
        }
#endif

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>applyContextVariables</c> configuration command,
        /// which applies context variables to the interpreter.  When a
        /// context name is given only the variables for that named context
        /// are applied; otherwise all context variables are extracted and
        /// applied.  Returns the count of variables applied.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode ApplyContextVariables( /* CORE */ /* RD-CTX */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 1) || (argumentCount > 2))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} ?contextName?\"",
                    Constants.ApplyContextVariablesCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            int count = 0;

            if (argumentCount == 2)
            {
                string contextName = arguments[1];

                if (String.IsNullOrEmpty(contextName))
                    contextName = null;

                if (contextName != null)
                {
                    if (ScriptContext.ApplyVariables(
                            interpreter, evaluateClientData.Plugin,
                            evaluateClientData, contextName,
                            evaluateClientData.NoGlobalOnly,
                            evaluateClientData.AllowLocalPolicy,
                            false, false, ref count,
                            ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
                }
            }
            else
            {
                if (ScriptContext.ExtractAndApplyVariables(
                        interpreter, evaluateClientData.Plugin,
                        evaluateClientData,
                        evaluateClientData.CultureInfo,
                        evaluateClientData.NoGlobalOnly,
                        evaluateClientData.AllowLocalPolicy,
                        false, false, ref count,
                        ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }
            }

            result = count;
            return ReturnCode.Ok;
        }

