            object enumValue; /* REUSED */
            CultureInfo cultureInfo = evaluateClientData.CultureInfo;

            enumValue = Utility.TryParseFlagsEnum(
                interpreter, typeof(PolicyType), null,
                arguments[1], cultureInfo, true, true,
                true, ref result);

            if (!(enumValue is PolicyType))
                return ReturnCode.Error;

            PolicyType policyType = (PolicyType)enumValue;
            Result value; /* REUSED */
            VersionRange oldVersionRange;

            value = null; /* VersionRange */

            if (interpreter.GetVariableValue(
                    Constants.ContextGetVariableFlags,
                    String.Format(
                        Constants.PluginVersionRangeVariableFormat,
                        Constants.PluginVersionRangeVariableName,
                        policyType),
                    ref value, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            if (String.IsNullOrEmpty(value))
            {
                oldVersionRange = null;
            }
            else
            {
                oldVersionRange = null;

                if (DataOps.GetVersionRange(
                        value, cultureInfo, ref oldVersionRange,
                        ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }
            }

            if (argumentCount == 3)
            {
                //
                // HACK: If an empty string is specified,
                //       just convert it to a null value.
                //       This will cause the code below
                //       to unset the property instead of
                //       setting it.
                //
                VersionRange newVersionRange = null;

                if (DataOps.GetVersionRange(arguments[2],
                        cultureInfo, ref newVersionRange,
                        ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                if (newVersionRange != null)
                {
                    value = DataOps.FormatVersionRange(
                        newVersionRange);

                    if (interpreter.SetVariableValue(
                            Constants.ContextSetVariableFlags,
                            String.Format(
                                Constants.PluginVersionRangeVariableFormat,
                                Constants.PluginVersionRangeVariableName,
                                policyType),
                            value, null, ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
                }
                else
                {
                    //
                    // HACK: Unsetting context script variable is
                    //       needed here to permit the associated
                    //       internal state to be completely reset,
                    //       due to the value conversion algorithm
                    //       used by ApplyVariables.
                    //
                    if (interpreter.UnsetVariable(
                            Constants.ContextUnsetVariableFlags,
                            String.Format(
                                Constants.PluginVersionRangeVariableFormat,
                                Constants.PluginVersionRangeVariableName,
                                policyType),
                            ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    value = DataOps.FormatVersionRange(
                        newVersionRange); /* null */
                }

                /* IGNORED */
                ScriptContext.SignalChanged(clientData,
                    String.Format(
                        Constants.PluginVersionRangeVariableFormat,
                        Constants.PluginVersionRangeVariableName,
                        policyType));
            }
            else
            {
                value = DataOps.FormatVersionRange(
                    oldVersionRange);
            }

            result = value;
            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>configureRuleSet</c> configuration command,
        /// which builds an effective policy rule set.  The supplied rule-set
        /// type and rule-set dictionary are parsed, filtered by public key
        /// token, and the matching rule sets are merged into a single rule
        /// set whose string representation is returned.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode ConfigureRuleSet( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if (argumentCount != 3)
            {
                result = String.Format(
                    "wrong # args: should be \"{0} type ruleSets\"",
                    Constants.ConfigureRuleSetCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            RuleSetType ruleSetType = RuleSetType.Default;
            string enumString; /* REUSED */
            object enumValue; /* REUSED */

            enumString = arguments[1];

            if (String.IsNullOrEmpty(enumString))
                enumString = null;

            if (enumString != null)
            {
                enumValue = Utility.TryParseFlagsEnum(
                    interpreter, typeof(RuleSetType),
                    null, enumString, cultureInfo,
                    true, true, true, ref result);

                if (!(enumValue is RuleSetType))
                    return ReturnCode.Error;

                ruleSetType = (RuleSetType)enumValue;
            }

            RuleSetDictionary ruleSets;

            ruleSets = RuleSetDictionary.FromString(
                arguments[2], cultureInfo, ruleSetType, false,
                false, ref result);

            if (ruleSets == null)
                return ReturnCode.Error;

            StringList patterns = new StringList();
            IKeyPair keyPair = evaluateClientData.KeyPair;

            if ((keyPair != null) && !Utility.HasFlags(
                    ruleSetType, RuleSetType.SharedOnly, true))
            {
                patterns.Add(String.Format(
                    "^{0}$", DataOps.FormatPublicKeyToken(
                    keyPair.PublicKeyToken, false, false)));
            }

            if (Utility.HasFlags(
                    ruleSetType, RuleSetType.AllowShared, true))
            {
                //
                // HACK: This will end up including all rulesets
                //       that are not tied to a specific public
                //       key token (i.e. those are "shared" ).
                //
                patterns.Add(String.Format(
                    "^{0}#\\d+$", typeof(RuleSet).Name));
            }

            IRuleSet ruleSet = null;
            int count = 0; /* NOT USED */

            ruleSet = ruleSets.FlattenAll(
                interpreter, ruleSet, MatchMode.RegExp, patterns,
                false, false, true, ref count, ref result);

            if (ruleSet == null)
                return ReturnCode.Error;

            ruleSet = evaluateClientData.ChangeRuleSet(ruleSet);
            result = (ruleSet != null) ? ruleSet.ToString() : null;

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>continueWithNow</c> flow-control command, which
        /// causes the enclosing configuration loop to skip the remainder of
        /// the current iteration and continue with the next by returning <see
        /// cref="ReturnCode.Continue" />.  The optional argument becomes the
        /// command result.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode ContinueWithNow( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 1) || (argumentCount > 2))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} ?result?\"",
                    Constants.ContinueWithNowCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            if (argumentCount == 2)
                result = arguments[1];
            else
                result = null;

            return ReturnCode.Continue;
        }

