        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>enableExtractAndApply</c> configuration command,
        /// which enables or disables the extract-and-apply behavior by
        /// setting the corresponding flag on the evaluation context.  Returns
        /// the current value of the flag.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode EnableExtractAndApply( /* CORE */ /* STATE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if (argumentCount != 2)
            {
                result = String.Format(
                    "wrong # args: should be \"{0} enable\"",
                    Constants.EnableExtractAndApplyCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            bool? enable = null;

            if (Value.GetNullableBoolean2(
                    arguments[1], ValueFlags.AnyBoolean, cultureInfo,
                    ref enable, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            if (enable != null)
                evaluateClientData.ExtractAndApply = (bool)enable;

            result = evaluateClientData.ExtractAndApply;
            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>evaluateWithCleanup</c> flow-control command,
        /// which provides try/finally semantics for configuration scripts:
        /// the first body is evaluated and the second body is always
        /// evaluated afterward as a cleanup block.  The middle argument must
        /// be the literal string "finally".  The try body's result is
        /// returned when the finally body succeeds; otherwise the finally
        /// body's result is returned.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode EvaluateWithCleanup( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if (argumentCount != 4)
            {
                result = String.Format(
                    "wrong # args: should be " +
                    "\"{0} body1 finally body2\"",
                    Constants.EvaluateWithCleanupCommandName);

                return ReturnCode.Error;
            }

            if (!DataOps.StringEquals(
                    arguments[argumentCount - 2], "finally"))
            {
                result = "expected \"finally\" before \"body2\"";
                return ReturnCode.Error;
            }

            string tryText = arguments[1];
            string finallyText = arguments[3];

            ReturnCode tryCode;
            Result tryResult = null;

            ReturnCode finallyCode;
            Result finallyResult = null;

            try
            {
                tryCode = interpreter.EvaluateScript(
                    tryText, ref tryResult);
            }
            finally
            {
                finallyCode = interpreter.EvaluateScript(
                    finallyText, ref finallyResult);
            }

            if (finallyCode == ReturnCode.Ok)
            {
                result = tryResult;
                return tryCode;
            }
            else
            {
                result = finallyResult;
                return finallyCode;
            }
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>evaluateWithoutError</c> flow-control command,
        /// which evaluates the first body while suppressing any error it
        /// raises; if it fails and an else clause is supplied, the else body
        /// is evaluated.  This command always succeeds, returning a list
        /// describing the try (and optionally else) return codes and results.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode EvaluateWithoutError( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 2) || (argumentCount > 4))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} " +
                    "body1 ?else? ?body2?\"",
                    Constants.EvaluateWithoutErrorCommandName);

                return ReturnCode.Error;
            }

            if ((argumentCount == 4) &&
                !DataOps.StringEquals(
                    arguments[argumentCount - 2], "else"))
            {
                result = "expected \"else\" before \"body2\"";
                return ReturnCode.Error;
            }

            ReturnCode tryCode;
            Result tryResult = null;

            tryCode = interpreter.EvaluateScript(
                arguments[1], ref tryResult);

            if ((argumentCount >= 3) &&
                (tryCode != ReturnCode.Ok))
            {
                ReturnCode elseCode;
                Result elseResult = null;

                elseCode = interpreter.EvaluateScript(
                    arguments[argumentCount - 1],
                    ref elseResult);

                result = StringList.MakeList(
                    tryCode, tryResult, elseCode,
                    elseResult);
            }
            else
            {
                result = StringList.MakeList(
                    tryCode, tryResult);
            }

            return ReturnCode.Ok;
        }

