        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>failOnError</c> configuration command, which
        /// enables or disables fail-on-error behavior by parsing the argument
        /// as a nullable boolean and storing it on the evaluation context.
        /// Returns the previous value of the flag, before the modification.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode FailOnError( /* CORE */ /* STATE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if (argumentCount != 2)
            {
                result = String.Format(
                    "wrong # args: should be \"{0} enable\"",
                    Constants.FailOnErrorCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            bool? enable = null;

            if (Value.GetNullableBoolean2(
                    arguments[1], ValueFlags.AnyBoolean, cultureInfo,
                    ref enable, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            bool wasFailOnError = evaluateClientData.FailOnError;

            if (enable != null)
                evaluateClientData.FailOnError = (bool)enable;

            result = wasFailOnError;
            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>fatalError</c> flow-control command, which
        /// triggers or queries the fatal-error state.  With no arguments it
        /// reports whether the context was not already in the fatal-error
        /// state; supplying a message triggers a fatal error (optionally
        /// recording the given error line) and returns an error.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode FatalError( /* CORE */ /* STATE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 1) || (argumentCount > 3))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} " +
                    "?message? ?errorLine?\"",
                    Constants.FatalErrorCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            bool wasFatalError = evaluateClientData.FatalError;
            evaluateClientData.FatalError = true; /* FAIL-SAFE */

            int errorLine = 0;

            if (argumentCount == 3)
            {
                string valueString = arguments[2];

                if (String.IsNullOrEmpty(valueString))
                    valueString = null;

                if (valueString != null)
                {
                    if (Value.GetInteger2(
                            valueString, ValueFlags.AnyInteger,
                            evaluateClientData.CultureInfo,
                            ref errorLine,
                            ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
                }
            }

            string message = null;

            if (argumentCount >= 2)
            {
                message = arguments[1];

                if (String.IsNullOrEmpty(message))
                    message = null;
            }

            if (message != null)
            {
                Result localResult = message;

                localResult.ReturnCode = ReturnCode.Error;

                if (errorLine != 0)
                    localResult.ErrorLine = errorLine;

                result = localResult;
                return ReturnCode.Error;
            }
            else
            {
                result = !wasFatalError;
                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>forEachFile</c> iteration command, which
        /// enumerates the files matching the given pattern in the specified
        /// directory (defaulting to the configuration file directory),
        /// assigning each file path to the named iteration variable and
        /// evaluating the supplied body script.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode ForEachFile( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 2) || (argumentCount > 5))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} " +
                    "pattern ?directory? ?script? ?varName?\"",
                    Constants.ForEachFileCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            string pattern = arguments[1];

            if (String.IsNullOrEmpty(pattern))
                pattern = null;

            string directory = null;

            if (argumentCount >= 3)
            {
                directory = arguments[2];

                if (String.IsNullOrEmpty(directory))
                    directory = null;
            }

            string text = null;

            if (argumentCount >= 4)
            {
                text = arguments[3];

                if (String.IsNullOrEmpty(text))
                    text = null;
            }

            string varName = null;

            if (argumentCount == 5)
            {
                varName = arguments[4];

                if (String.IsNullOrEmpty(varName))
                    varName = null;
            }

            if (directory == null)
            {
                directory = Path.GetDirectoryName(
                    evaluateClientData.FileName);
            }

            if (!Directory.Exists(directory))
            {
                result = String.Format(
                    "directory {0} does not exist",
                    Utility.FormatWrapOrNull(directory));

                return ReturnCode.Error;
            }

            string[] fileNames;

            try
            {
                fileNames = Directory.GetFiles(
                    directory, Characters.Asterisk.ToString(),
                    SearchOption.TopDirectoryOnly); /* throw */
            }
            catch (Exception e)
            {
                result = e;
                return ReturnCode.Error;
            }

            if ((fileNames == null) || (fileNames.Length == 0))
            {
                result = String.Format(
                    "directory {0} appears to be empty",
                    Utility.FormatWrapOrNull(directory));

                return ReturnCode.Error;
            }

            Array.Sort(fileNames); /* O(N) */

            return Helpers.EvaluateForEachFile(
                interpreter, evaluateClientData, fileNames,
                pattern, text, varName, ref result);
        }

