        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>haveIdentifier</c> introspection command, which
        /// tests whether a named identifier exists.  The optional kind
        /// argument narrows the search to a specific identifier kind
        /// (defaulting to any executable entity).  Returns a boolean.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode HaveIdentifier( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 2) || (argumentCount > 3))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} name ?kind?\"",
                    Constants.HaveIdentifierCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            string identifierName = arguments[1];

            if (String.IsNullOrEmpty(identifierName))
                identifierName = null;

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            IdentifierKind kind = IdentifierKind.AnyIExecute;
            string enumString;
            object enumValue;

            if (argumentCount == 3)
            {
                enumString = arguments[2];

                if (String.IsNullOrEmpty(enumString))
                    enumString = null;

                if (enumString != null)
                {
                    enumValue = Utility.TryParseFlagsEnum(
                        interpreter, typeof(IdentifierKind),
                        kind.ToString(), enumString,
                        cultureInfo, true, true, true,
                        ref result);

                    if (!(enumValue is IdentifierKind))
                        return ReturnCode.Error;

                    kind = (IdentifierKind)enumValue;
                }
            }

            if (identifierName != null)
            {
                ResultList errors = null; /* NOT USED */

                if (Helpers.LookupIdentifier(interpreter,
                        kind, arguments, ref identifierName,
                        ref errors) == ReturnCode.Ok)
                {
                    result = true;
                }
                else
                {
                    result = false;
                }

                return ReturnCode.Ok;
            }
            else
            {
                result = "invalid identifier name";
                return ReturnCode.Error;
            }
        }

