        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>isRestrictedInterpreter</c> introspection
        /// command, which tests selected restriction aspects of the current
        /// interpreter as chosen by the restriction flags (any restriction,
        /// safe, hide-unsafe, SDK, or security).  Returns the boolean OR of
        /// the aspects that were checked.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode IsRestrictedInterpreter( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount != 1) && (argumentCount != 2))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} ?flags?\"",
                    Constants.IsRestrictedInterpreterCommandName);

                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = interpreter.CultureInfo;
            RestrictionFlags restrictionFlags = RestrictionFlags.Default;
            string enumString;
            object enumValue;

            if (argumentCount == 2)
            {
                enumString = arguments[1];

                if (String.IsNullOrEmpty(enumString))
                    enumString = null;

                if (enumString != null)
                {
                    enumValue = Utility.TryParseFlagsEnum(
                        interpreter, typeof(RestrictionFlags),
                        restrictionFlags.ToString(), enumString,
                        cultureInfo, true, true, true, ref result);

                    if (!(enumValue is RestrictionFlags))
                        return ReturnCode.Error;

                    restrictionFlags = (RestrictionFlags)enumValue;
                }
            }

            bool[] parts = { false, false, false, false, false };

            if (SharedOps.HasFlags(
                    restrictionFlags, RestrictionFlags.Any, true))
            {
                parts[0] = interpreter.IsRestricted();
            }

            if (SharedOps.HasFlags(
                    restrictionFlags, RestrictionFlags.Safe, true))
            {
                parts[1] = interpreter.IsSafe();
            }

            if (SharedOps.HasFlags(
                    restrictionFlags, RestrictionFlags.HideUnsafe, true))
            {
                parts[2] = interpreter.IsHideUnsafe();
            }

            if (SharedOps.HasFlags(
                    restrictionFlags, RestrictionFlags.Sdk, true))
            {
                parts[3] = interpreter.IsAnySdk();
            }

            if (SharedOps.HasFlags(
                    restrictionFlags, RestrictionFlags.Security, true))
            {
                parts[4] = interpreter.SetSecurityWasEnabled(null);
            }

            result = parts[0] || parts[1] || parts[2] || parts[3] || parts[4];
            return ReturnCode.Ok;
        }

