        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode KeyUsage( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if (argumentCount < 2)
            {
                result = String.Format(
                    Constants.KeyUsageWrongNumArgsFormat,
                    Constants.KeyUsageCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            EnsembleDictionary subCommands = new EnsembleDictionary();

            subCommands.Add("change", null);
            subCommands.Add("clear", null);
            subCommands.Add("default", null);
            subCommands.Add("forbid", null);
            subCommands.Add("get", null);
            subCommands.Add("list", null);
            subCommands.Add("modify", null);
            subCommands.Add("resolve", null);

            string subCommand = arguments[1];

            if (Utility.SubCommandFromEnsemble(
                    interpreter, subCommands, null, true, null,
                    ref subCommand, ref result) == ReturnCode.Ok)
            {
                //
                // HACK: Only the "clear" and "list" sub-commands
                //       do not require the entity type argument.
                //
                bool isClear = DataOps.StringEquals(
                    subCommand, "clear");

                bool isList = DataOps.StringEquals(
                    subCommand, "list");

                if ((argumentCount < 3) && !isClear && !isList)
                {
                    result = String.Format(
                        Constants.KeyUsageWrongNumArgsFormat,
                        Constants.KeyUsageCommandName);

                    return ReturnCode.Error;
                }

                //
                // HACK: Only the "list" sub-command cannot have
                //       an entity type argument.
                //
                CultureInfo cultureInfo = evaluateClientData.CultureInfo;
                EntityType? entityType = null;
                string enumString;
                object enumValue;

                if (!isList && (argumentCount >= 3))
                {
                    enumString = arguments[2];

                    if (String.IsNullOrEmpty(enumString))
                        enumString = null;

                    if (enumString != null)
                    {
                        enumValue = Utility.TryParseFlagsEnum(
                            interpreter, typeof(EntityType),
                            null, enumString, cultureInfo,
                            true, true, true, ref result);

                        if (!(enumValue is EntityType))
                            return ReturnCode.Error;

                        entityType = (EntityType)enumValue;
                    }
                }

                switch (subCommand)
                {
                    case "change":
                        {
                            if (argumentCount > 6)
                            {
                                result = String.Format(
                                    Constants.KeyUsageWrongNumArgsFormat,
                                    Constants.KeyUsageCommandName);

                                return ReturnCode.Error;
                            }

                            KeyUsageTriplet anyTriplet =
                                CertificateGlobalState.ResolveKeyUsage(
                                    (EntityType)entityType, ref result);

                            if (anyTriplet == null)
                                return ReturnCode.Error;

                            string flags = null;

                            if (argumentCount >= 4)
                            {
                                flags = arguments[3];

                                if (String.IsNullOrEmpty(flags))
                                    flags = null;

                                if ((flags != null) &&
                                    (CertificateFlagOps.SimpleChange(
                                        anyTriplet.X, flags, ref flags,
                                        ref result) != ReturnCode.Ok))
                                {
                                    return ReturnCode.Error;
                                }
                            }

                            string valueString; /* REUSED */
                            bool all = false;

                            if (argumentCount >= 5)
                            {
                                valueString = arguments[4];

                                if (String.IsNullOrEmpty(valueString))
                                    valueString = null;

                                if (valueString != null)
                                {
                                    if (Value.GetBoolean2(valueString,
                                            ValueFlags.AnyBoolean, cultureInfo,
                                            ref all, ref result) != ReturnCode.Ok)
                                    {
                                        return ReturnCode.Error;
                                    }
                                }
                            }

                            bool root = false;

                            if (argumentCount == 6)
                            {
                                valueString = arguments[5];

                                if (String.IsNullOrEmpty(valueString))
                                    valueString = null;

                                if (valueString != null)
                                {
                                    if (Value.GetBoolean2(valueString,
                                            ValueFlags.AnyBoolean, cultureInfo,
                                            ref root, ref result) != ReturnCode.Ok)
                                    {
                                        return ReturnCode.Error;
                                    }
                                }
                            }

                            result = CertificateGlobalState.MergeKeyUsage(
                                (EntityType)entityType, flags, all, root);

                            return ReturnCode.Ok;
                        }
                    case "clear":
                        {
                            if (argumentCount > 3)
                            {
                                result = String.Format(
                                    Constants.KeyUsageWrongNumArgsFormat,
                                    Constants.KeyUsageCommandName);

                                return ReturnCode.Error;
                            }

                            if (entityType != null)
                            {
                                result = CertificateGlobalState.RemoveKeyUsage(
                                    (EntityType)entityType);
                            }
                            else
                            {
                                result = CertificateGlobalState.ClearKeyUsages();
                            }

                            return ReturnCode.Ok;
                        }
                    case "default":
                        {
                            if (argumentCount != 3)
                            {
                                result = String.Format(
                                    Constants.KeyUsageWrongNumArgsFormat,
                                    Constants.KeyUsageCommandName);

                                return ReturnCode.Error;
                            }

                            KeyUsageTriplet anyTriplet =
                                CertificateGlobalState.DefaultKeyUsage(
                                    (EntityType)entityType, ref result);

                            if (anyTriplet == null)
                                return ReturnCode.Error;

                            result = anyTriplet.ToString();
                            return ReturnCode.Ok;
                        }
                    case "forbid":
                        {
                            if (argumentCount != 3)
                            {
                                result = String.Format(
                                    Constants.KeyUsageWrongNumArgsFormat,
                                    Constants.KeyUsageCommandName);

                                return ReturnCode.Error;
                            }

                            result = CertificateGlobalState.ForbidKeyUsage(
                                (EntityType)entityType);

                            return ReturnCode.Ok;
                        }
                    case "get":
                        {
                            if (argumentCount != 3)
                            {
                                result = String.Format(
                                    Constants.KeyUsageWrongNumArgsFormat,
                                    Constants.KeyUsageCommandName);

                                return ReturnCode.Error;
                            }

                            KeyUsageTriplet anyTriplet;

                            if (CertificateGlobalState.TryGetKeyUsage(
                                    (EntityType)entityType, out anyTriplet))
                            {
                                if (anyTriplet == null)
                                {
                                    result = String.Format(
                                        "invalid key usage for entity type {0}",
                                        Utility.FormatWrapOrNull(entityType));

                                    return ReturnCode.Error;
                                }

                                result = anyTriplet.ToString();
                            }
                            else
                            {
                                result = String.Format(
                                    "missing entity type {0} for key usage",
                                    Utility.FormatWrapOrNull(entityType));

                                return ReturnCode.Error;
                            }

                            return ReturnCode.Ok;
                        }
                    case "list":
                        {
                            if (argumentCount != 2)
                            {
                                result = String.Format(
                                    Constants.KeyUsageWrongNumArgsFormat,
                                    Constants.KeyUsageCommandName);

                                return ReturnCode.Error;
                            }

                            StringList list =
                                CertificateGlobalState.ListKeyUsages();

                            if (list == null)
                            {
                                result = "key usages unavailable";
                                return ReturnCode.Error;
                            }

                            result = list;
                            return ReturnCode.Ok;
                        }
                    case "modify":
                        {
                            if (argumentCount > 6)
                            {
                                result = String.Format(
                                    Constants.KeyUsageWrongNumArgsFormat,
                                    Constants.KeyUsageCommandName);

                                return ReturnCode.Error;
                            }

                            string flags = null;

                            if (argumentCount >= 4)
                            {
                                flags = arguments[3];

                                if (String.IsNullOrEmpty(flags))
                                    flags = null;

                                if (flags != null)
                                {
                                    if (!Utility.VerifyAttributeFlags(
                                            flags, true, true,
                                            ref result))
                                    {
                                        return ReturnCode.Error;
                                    }
                                }
                            }

                            string valueString; /* REUSED */
                            bool all = false;

                            if (argumentCount >= 5)
                            {
                                valueString = arguments[4];

                                if (String.IsNullOrEmpty(valueString))
                                    valueString = null;

                                if (valueString != null)
                                {
                                    if (Value.GetBoolean2(valueString,
                                            ValueFlags.AnyBoolean, cultureInfo,
                                            ref all, ref result) != ReturnCode.Ok)
                                    {
                                        return ReturnCode.Error;
                                    }
                                }
                            }

                            bool root = false;

                            if (argumentCount == 6)
                            {
                                valueString = arguments[5];

                                if (String.IsNullOrEmpty(valueString))
                                    valueString = null;

                                if (valueString != null)
                                {
                                    if (Value.GetBoolean2(valueString,
                                            ValueFlags.AnyBoolean, cultureInfo,
                                            ref root, ref result) != ReturnCode.Ok)
                                    {
                                        return ReturnCode.Error;
                                    }
                                }
                            }

                            result = CertificateGlobalState.MergeKeyUsage(
                                (EntityType)entityType, flags, all, root);

                            return ReturnCode.Ok;
                        }
                    case "resolve":
                        {
                            if (argumentCount != 3)
                            {
                                result = String.Format(
                                    Constants.KeyUsageWrongNumArgsFormat,
                                    Constants.KeyUsageCommandName);

                                return ReturnCode.Error;
                            }

                            KeyUsageTriplet anyTriplet =
                                CertificateGlobalState.ResolveKeyUsage(
                                    (EntityType)entityType, ref result);

                            if (anyTriplet == null)
                                return ReturnCode.Error;

                            result = anyTriplet.ToString();
                            return ReturnCode.Ok;
                        }
                    default:
                        {
                            result = String.Format(
                                Constants.KeyUsageWrongNumArgsFormat,
                                Constants.KeyUsageCommandName);

                            return ReturnCode.Error;
                        }
                }
            }
            else
            {
                return ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>listComponents</c> introspection command, which
        /// lists the names of all available transient configuration commands
        /// together with the active define constants.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode ListComponents( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if (argumentCount != 1)
            {
                result = String.Format(
                    "wrong # args: should be \"{0}\"",
                    Constants.ListComponentsCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            StringList list = null;

            if (Helpers.ListCommands(
                    interpreter, clientData, ref list,
                    ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

#if CERTIFICATE_PLUGIN
            CertificatePluginOps.AddDefineConstants(ref list);
#endif

            result = list;
            return ReturnCode.Ok;
        }

