            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            result = ScriptContext.GetVariableNames(
                evaluateClientData.NoGlobalOnly);

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>matchPlatform</c> introspection command, which
        /// matches the current platform against a list of {matchMode pattern}
        /// pairs, supporting exact, glob, and regular-expression match modes.
        /// Returns a boolean indicating whether any pattern matched.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode MatchPlatform( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if (argumentCount != 2)
            {
                result = String.Format(
                    "wrong # args: should be \"{0} patterns\"",
                    Constants.MatchPlatformCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            StringList list = null;

            if (Parser.SplitList(
                    interpreter, arguments[1], 0, Length.Invalid,
                    true, ref list, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            MatchMode mode = MatchMode.None;
            string enumString;
            object enumValue;

            if (list.Count > 0)
            {
                enumString = list[0];

                if (String.IsNullOrEmpty(enumString))
                    enumString = null;

                if (enumString != null)
                {
                    enumValue = Utility.TryParseFlagsEnum(
                        interpreter, typeof(MatchMode),
                        mode.ToString(), enumString,
                        cultureInfo, true, true, true,
                        ref result);

                    if (!(enumValue is MatchMode))
                        return ReturnCode.Error;

                    mode = (MatchMode)enumValue;
                }
            }

            if (list.Count > 1)
            {
                switch (mode)
                {
                    case MatchMode.Exact:
                        {
                            if (DataOps.StringEquals(
                                    Utility.GetFullPlatformName(),
                                    list[1]))
                            {
                                result = true;
                            }
                            else
                            {
                                result = false;
                            }

                            return ReturnCode.Ok;
                        }
                    case MatchMode.Glob:
                        {
                            if (Parser.StringMatch(interpreter,
                                    Utility.GetFullPlatformName(),
                                    0, list[1], 0, false))
                            {
                                result = true;
                            }
                            else
                            {
                                result = false;
                            }

                            return ReturnCode.Ok;
                        }
                    case MatchMode.RegExp:
                        {
                            try
                            {
                                Match match = Regex.Match(
                                    Utility.GetFullPlatformName(),
                                    list[1]); /* throw */

                                if ((match != null) && match.Success)
                                    result = true;
                                else
                                    result = false;

                                return ReturnCode.Ok;
                            }
                            catch (Exception e)
                            {
                                result = e;
                                return ReturnCode.Error;
                            }
                        }
                    default:
                        {
                            result = String.Format(
                                "unsupported match mode {0}", mode);

                            return ReturnCode.Error;
                        }
                }
            }

            result = false;
            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>maybeEvaluate</c> flow-control command, which
        /// provides if/else semantics: the boolean expression is evaluated
        /// and, when true, the first body is evaluated; when false and an
        /// else clause is supplied, the else body is evaluated.  Returns the
        /// result of whichever body was chosen.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode MaybeEvaluate( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 3) || (argumentCount > 5))
            {
                result = String.Format(
                    "wrong # args: should be " +
                    "\"{0} expr1 body1 ?else? ?body2?\"",
                    Constants.MaybeEvaluateCommandName);

                return ReturnCode.Error;
            }

            if ((argumentCount == 5) &&
                !DataOps.StringEquals(
                    arguments[argumentCount - 2], "else"))
            {
                result = "expected \"else\" before \"body2\"";
                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;

            string errorInfo = String.Format(
                "{0}    (\"{1}\" test expression)", "{0}",
                Constants.MaybeEvaluateCommandName);

            bool value = false;

            if (Helpers.ExpressionToBoolean(interpreter,
                    cultureInfo, arguments[1], errorInfo,
                    ref value, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            return (value || (argumentCount == 5)) ?
                interpreter.EvaluateScript(
                    arguments[value ? 2 : argumentCount - 1],
                    ref result) :
                ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>maybeIterateUsingExpression</c> iteration
        /// command, a general for-loop construct.  The optional list supplies
        /// zero to four sub-expressions interpreted as (in order) the start,
        /// test, next, and final clauses, so an empty list yields an infinite
        /// loop and longer lists add the test, increment, and finalization
        /// phases.  Break and continue are honored and a configured iteration
        /// limit is enforced; the result of the last body evaluation is
        /// returned.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode MaybeIterateUsingExpression( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            string commandName =
                Constants.MaybeIterateUsingExpressionCommandName;

            int argumentCount = arguments.Count;

            if ((argumentCount < 2) || (argumentCount > 3))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} ?list? body\"",
                    commandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            //
            // TODO: Maybe this should not be required?  This command
            //       does not actually modify any important state by
            //       itself.
            //
            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            //
            // NOTE: Start out with the loop sub-expressions being set
            //       to null and then populate them based on the count
            //       of the expression list, per specification.
            //
            string start = null;
            string test = null;
            string next = null;
            string final = null;

            if (argumentCount == 3)
            {
                StringList list = null;

                if (Parser.SplitList(
                        interpreter, arguments[1], 0, Length.Invalid,
                        true, ref list, ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                switch (list.Count)
                {
                    case 0: /* infinite */
                        {
                            break;
                        }
                    case 1: /* test */
                        {
                            test = list[0];
                            break;
                        }
                    case 2: /* test next */
                        {
                            test = list[0];
                            next = list[1];
                            break;
                        }
                    case 3: /* start test next */
                        {
                            start = list[0];
                            test = list[1];
                            next = list[2];
                            break;
                        }
                    case 4: /* start test next final */
                        {
                            start = list[0];
                            test = list[1];
                            next = list[2];
                            final = list[3];
                            break;
                        }
                    default:
                        {
                            result = String.Format(
                                "wrong # loop args: should be \"{0} " +
                                "{1}?start? ?test? ?next? ?final?{2} " +
                                "body\"", commandName, Characters.OpenBrace,
                                Characters.CloseBrace);

                            return ReturnCode.Error;
                        }
                }

                if (String.IsNullOrEmpty(start))
                    start = null;

                if (String.IsNullOrEmpty(test))
                    test = null;

                if (String.IsNullOrEmpty(next))
                    next = null;

                if (String.IsNullOrEmpty(final))
                    final = null;
            }

            ReturnCode code; /* REUSED */
            Result localResult; /* REUSED */

            if (start != null)
            {
                localResult = null;

                code = interpreter.EvaluateScript(
                    start, ref localResult);

                if (code != ReturnCode.Ok)
                {
                    result = localResult;
                    return code;
                }
            }

            string varName = Constants.IterationCountVariableName;

            int iterationLimit = interpreter.IterationLimit;
            int iterationCount = 0;

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;

            string errorInfo = String.Format(
                "{0}    (\"{1}\" test expression)", "{0}",
                commandName);

            string body = arguments[argumentCount - 1];

            if (String.IsNullOrEmpty(body))
                body = null;

            try
            {
                while (true)
                {
                    localResult = null;

                    if (interpreter.SetVariableValue(
                            varName, iterationCount.ToString(),
                            ref localResult) != ReturnCode.Ok)
                    {
                        /* IGNORED */
                        Engine.AddErrorInformation(
                            interpreter, localResult, String.Format(
                                "{0}    (setting {1} loop variable \"{2}\")",
                                Environment.NewLine, commandName, varName));

                        code = ReturnCode.Error;
                        break;
                    }

                    if (test != null)
                    {
                        bool value = false;

                        localResult = null;

                        code = Helpers.ExpressionToBoolean(
                            interpreter, cultureInfo, test,
                            errorInfo, ref value, ref localResult);

                        if (code != ReturnCode.Ok)
                            break;

                        if (!value)
                            break;
                    }

                    if (body != null)
                    {
                        localResult = null;

                        code = interpreter.EvaluateScript(
                            body, ref localResult);

                        if (code == ReturnCode.Error)
                        {
                            /* IGNORED */
                            Engine.AddErrorInformation(
                                interpreter, localResult, String.Format(
                                    "{0}    (\"{1}\" body line {2})",
                                    Environment.NewLine, commandName,
                                    interpreter.ErrorLine));

                            break;
                        }
                        else if ((code != ReturnCode.Ok) &&
                            (code != ReturnCode.Continue))
                        {
                            break;
                        }
                    }

                    if (next != null)
                    {
                        localResult = null;

                        code = interpreter.EvaluateScript(
                            next, ref localResult);

                        if (code == ReturnCode.Error)
                        {
                            /* IGNORED */
                            Engine.AddErrorInformation(
                                interpreter, localResult, String.Format(
                                    "{0}    (\"{1}\" loop-end command)",
                                    Environment.NewLine, commandName));

                            break;
                        }
                        else if (code != ReturnCode.Ok)
                        {
                            break;
                        }
                    }

                    iterationCount++;

                    if ((iterationLimit != Limits.Unlimited) &&
                        (iterationCount > iterationLimit))
                    {
                        localResult = String.Format(
                            "iteration limit {0} exceeded",
                            iterationLimit);

                        code = ReturnCode.Error;
                        break;
                    }
                }

                if ((code == ReturnCode.Ok) && (final != null))
                {
                    localResult = null;

                    code = interpreter.EvaluateScript(
                        final, ref localResult);

                    if (code == ReturnCode.Error)
                    {
                        /* IGNORED */
                        Engine.AddErrorInformation(
                            interpreter, localResult, String.Format(
                                "{0}    (\"{1}\" final command)",
                                Environment.NewLine, commandName));
                    }
                }

                Helpers.MaybeSetResultToCode(code, ref localResult);

                if (code == ReturnCode.Break)
                    code = ReturnCode.Ok;

                result = localResult;
            }
            finally
            {
                if (interpreter.UnsetVariable(
                        Constants.UnsetVariableFlags, varName,
                        ref result) != ReturnCode.Ok)
                {
                    code = ReturnCode.Error;
                }
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>maybeRecordResult</c> command, which executes a
        /// command or evaluates a script according to the record-result flags
        /// (treat as a command, treat as a script, or auto-detect), recording
        /// the outcome under the supplied tag.  Returns the execution result.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode MaybeRecordResult( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            long entryId = 0;

            /* NO RESULT */
            Helpers.Trace(
                interpreter, clientData, arguments, ref entryId);

            bool noTrace = false;
            ReturnCode? code = null;

            try
            {
                if (interpreter == null)
                {
                    result = "invalid interpreter";
                    code = ReturnCode.Error;

                    return (ReturnCode)code;
                }

                if (arguments == null)
                {
                    result = "invalid argument list";
                    code = ReturnCode.Error;

                    return (ReturnCode)code;
                }

                int argumentCount = arguments.Count;

                if (argumentCount < 4)
                {
                    result = String.Format(
                        "wrong # args: should be \"{0} flags tag arg ?arg ...?\"",
                        Constants.MaybeRecordResultCommandName);

                    code = ReturnCode.Error;
                    return (ReturnCode)code;
                }

                EvaluateClientData evaluateClientData =
                    clientData as EvaluateClientData;

                if (evaluateClientData == null)
                {
                    result = "missing context clientData";
                    return ReturnCode.Error;
                }

                ///////////////////////////////////////////////////////////////

                //
                // NOTE: The "tag" argument is not used by this within the
                //       command implementation itself; however, it *will*
                //       show up in trace log lines, thus fulfilling its
                //       role as a trace log "tag".
                //
                CultureInfo cultureInfo = evaluateClientData.CultureInfo;
                RecordResultType resultType = RecordResultType.Default;
                string enumString = arguments[1];
                object enumValue;

                if (String.IsNullOrEmpty(enumString))
                    enumString = null;

                if (enumString != null)
                {
                    enumValue = Utility.TryParseFlagsEnum(
                        interpreter, typeof(RecordResultType),
                        resultType.ToString(), enumString,
                        cultureInfo, true, true, true,
                        ref result);

                    if (!(enumValue is RecordResultType))
                    {
                        code = ReturnCode.Error;
                        return (ReturnCode)code;
                    }

                    resultType = (RecordResultType)enumValue;
                }

                ///////////////////////////////////////////////////////////////

                ArgumentList localArguments = ArgumentList.GetRange(arguments, 3);

                if ((localArguments == null) || (localArguments.Count < 1))
                {
                    result = "wrong # args: should be \"arg ?arg ...?\"";
                    code = ReturnCode.Error;

                    return (ReturnCode)code;
                }

                ///////////////////////////////////////////////////////////////

                //
                // HACK: When using the 'ForAutomatic' mode for the result
                //       type, this is the target for the goto statement.
                //
            retry:

                noTrace = false;

                ///////////////////////////////////////////////////////////////

                ReturnCode localCode = ReturnCode.Error; /* REUSED */
                Result localResult = Constants.NothingDoneError; /* REUSED */

                ///////////////////////////////////////////////////////////////

                if (SharedOps.HasFlags(
                        resultType, RecordResultType.ForCommand, true))
                {
                    try
                    {
                        string commandName = localArguments[0];
                        IExecute execute = null;

                        localResult = null;

                        localCode = interpreter.GetIExecuteViaResolvers(
                            null, interpreter.GetResolverEngineFlags(true),
                            commandName, localArguments, LookupFlags.Default,
                            ref execute, ref localResult);

                        if (localCode == ReturnCode.Ok)
                        {
                            localResult = null;

                            localCode = Engine.ExternalExecuteWithFrame(
                                commandName, execute, interpreter, clientData,
                                localArguments, null, null, null, null, true,
                                ref localResult);
                        }
                    }
                    finally
                    {
                        result = localResult;
                        code = localCode;
                    }

                    return (ReturnCode)code;
                }

                ///////////////////////////////////////////////////////////////

                if (SharedOps.HasFlags(
                        resultType, RecordResultType.ForScript, true))
                {
                    try
                    {
                        if (localArguments.Count == 1)
                        {
                            localResult = null;

                            localCode = interpreter.EvaluateScript(
                                localArguments[0], ref localResult);
                        }
                        else
                        {
                            localResult = "wrong # args: should be \"script\"";
                            localCode = ReturnCode.Error;
                        }
                    }
                    finally
                    {
                        result = localResult;
                        code = localCode;
                    }

                    return (ReturnCode)code;
                }

                ///////////////////////////////////////////////////////////////

                if (SharedOps.HasFlags(
                        resultType, RecordResultType.ForAutomatic, true))
                {
                    noTrace = true; /* HACK: Prevent two traces. */

                    if (localArguments.Count == 1)
                        resultType |= RecordResultType.ForScript;
                    else
                        resultType |= RecordResultType.ForCommand;

                    resultType &= ~RecordResultType.ForAutomatic;
                    goto retry;
                }

                ///////////////////////////////////////////////////////////////

                result = String.Format(
                    "cannot record result, unsupported type {0}",
                    Utility.FormatWrapOrNull(resultType));

                code = ReturnCode.Error;
                return (ReturnCode)code;
            }
            catch (Exception e) /* IMPOSSIBLE? */
            {
                result = e;
                code = ReturnCode.Error;

                return (ReturnCode)code;
            }
            finally
            {
                if (!noTrace)
                {
                    /* NO RESULT */
                    Helpers.Trace(
                        interpreter, clientData, arguments, code, result,
                        ref entryId);
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>notAfter</c> time-validation command, which
        /// requires that the current UTC time is at or before the given
        /// date/time.  When the time has passed, a multi-stage grace and
        /// fallback policy selected by the command flags is applied: enforce
        /// only under a debugger, warn only, apply successive grace periods,
        /// open the configured out-of-time web page, verify remotely against
        /// time servers, fail immediately, or always succeed.  Fails with a
        /// "not valid after" error when the deadline is exceeded and no
        /// fallback permits continuing.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode NotAfter( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 2) || (argumentCount > 3))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} dateTime ?flags?\"",
                    Constants.NotAfterCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo;

#if MONO || MONO_HACKS
            if (Utility.IsMono() && !Utility.IsDefaultAppDomain())
                cultureInfo = null;
            else
#endif
                cultureInfo = evaluateClientData.CultureInfo;

            DateTime dateTime;

            if (!DateTime.TryParseExact(
                    arguments[1], Constants.DefaultTimeStampFormat,
                    cultureInfo, Constants.DefaultDateTimeStyles,
                    out dateTime))
            {
                result = String.Format(
                    "unable to parse date-time string {0}",
                    Utility.FormatWrapOrNull(arguments[1]));

                return ReturnCode.Error;
            }

            object enumValue; /* REUSED */
            NotCommandFlags notCommandFlags = NotCommandFlags.Default;

            enumValue = Configuration.GetVariable<NotCommandFlags>(
                interpreter, Constants.NotCommandFlagsEnvVarName,
                notCommandFlags, ref result);

            if (!(enumValue is NotCommandFlags))
                return ReturnCode.Error;

            notCommandFlags = (NotCommandFlags)enumValue;

            string enumString;

            if (argumentCount == 3)
            {
                enumString = arguments[2];

                if (String.IsNullOrEmpty(enumString))
                    enumString = null;

                if (enumString != null)
                {
                    enumValue = Utility.TryParseFlagsEnum(
                        interpreter, typeof(NotCommandFlags),
                        notCommandFlags.ToString(), enumString,
                        cultureInfo, true, true, true,
                        ref result);

                    if (!(enumValue is NotCommandFlags))
                        return ReturnCode.Error;

                    notCommandFlags = (NotCommandFlags)enumValue;
                }
            }

            DateTime now = Utility.GetUtcNow();

            if (now < dateTime)
                return ReturnCode.Ok;

            TimeSpan grace = Constants.GraceDuration;

            string message = String.Format(
                "not valid after {0}", DataOps.FormatTimeStamp(
                dateTime));

#if DEBUG || FORCE_TRACE
            CertificateTraceOps.MaybeLogAndDebugTrace(
                String.Format("NotAfter: {0}", message),
                typeof(Callbacks).Name, TracePriority.Highest |
                TracePriority.Error, 0);
#endif

            if (SharedOps.HasFlags(notCommandFlags,
                    NotCommandFlags.DebuggerOnly, true) &&
                !Configuration.IsThereAnyDebugger())
            {
                return ReturnCode.Ok;
            }

            if (!SharedOps.HasFlags(notCommandFlags,
                    NotCommandFlags.FailFast, true))
            {
                if (SharedOps.HasFlags(notCommandFlags,
                        NotCommandFlags.WarnOnly, true))
                {
                    return ReturnCode.Ok;
                }

                TimeSpan elapsed; /* REUSED */

                if (SharedOps.HasFlags(notCommandFlags,
                        NotCommandFlags.Grace1, true))
                {
                    elapsed = now.Subtract(dateTime);

                    if (elapsed <= grace)
                        return ReturnCode.Ok;
                }

                int? timeout = SharedOps.GetTimeout(
                    interpreter, null);

                if (SharedOps.HasFlags(notCommandFlags,
                        NotCommandFlags.Web, true))
                {
                    string uri = Constants.OutOfTimeUri;

                    if (Utility.IsRemoteUri(uri))
                    {
                        try
                        {
                            Process process = Process.Start(uri);

                            if (SharedOps.HasFlags(notCommandFlags,
                                    NotCommandFlags.WaitForWeb, true) &&
                                (timeout != null))
                            {
                                process.WaitForExit((int)timeout);
                            }

                            return ReturnCode.Ok;
                        }
                        catch (Exception e)
                        {
                            CertificateTraceOps.DebugTrace(
                                e, typeof(Callbacks).Name,
                                TracePriority.Highest);
                        }
                    }
                }

                if (SharedOps.HasFlags(notCommandFlags,
                        NotCommandFlags.Grace2, true))
                {
                    elapsed = now.Subtract(dateTime);
                    grace += grace;

                    if (elapsed <= grace)
                        return ReturnCode.Ok;
                }

#if NETWORK
                if (SharedOps.HasFlags(notCommandFlags,
                        NotCommandFlags.Remote, true))
                {
                    //
                    // HACK: Wait a while for the "asynchronous"
                    //       time server checks to complete and
                    //       then see if one is available.
                    //
                    if (SharedOps.HasFlags(notCommandFlags,
                            NotCommandFlags.WaitForRemote, true) &&
                        (timeout != null))
                    {
                        try
                        {
                            /* NO RESULT */
                            Thread.Sleep((int)timeout); /* throw */
                        }
                        catch (Exception e)
                        {
                            CertificateTraceOps.DebugTrace(
                                e, typeof(Callbacks).Name,
                                TracePriority.Highest);
                        }
                    }

                    if (NetworkState.IsNtpOk() ||
                        NetworkState.IsHttpsOk())
                    {
                        return ReturnCode.Ok;
                    }
                }
#endif

                if (SharedOps.HasFlags(notCommandFlags,
                        NotCommandFlags.Grace3, true))
                {
                    elapsed = now.Subtract(dateTime);
                    grace += grace;

                    if (elapsed <= grace)
                        return ReturnCode.Ok;
                }
            }

            if (SharedOps.HasFlags(notCommandFlags,
                    NotCommandFlags.FailSafe, true))
            {
                return ReturnCode.Ok;
            }

            result = message;
            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>notBefore</c> time-validation command, which
        /// requires that the current UTC time is at or after the given
        /// date/time, applying the same grace and fallback policy as
        /// <c>notAfter</c>.  Fails with a "not valid before" error when
        /// invoked too early and no fallback permits continuing.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode NotBefore( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 2) || (argumentCount > 3))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} dateTime ?flags?\"",
                    Constants.NotBeforeCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo;

#if MONO || MONO_HACKS
            if (Utility.IsMono() && !Utility.IsDefaultAppDomain())
                cultureInfo = null;
            else
#endif
                cultureInfo = evaluateClientData.CultureInfo;

            DateTime dateTime;

            if (!DateTime.TryParseExact(
                    arguments[1], Constants.DefaultTimeStampFormat,
                    cultureInfo, Constants.DefaultDateTimeStyles,
                    out dateTime))
            {
                result = String.Format(
                    "unable to parse date-time string {0}",
                    Utility.FormatWrapOrNull(arguments[1]));

                return ReturnCode.Error;
            }

            object enumValue; /* REUSED */
            NotCommandFlags notCommandFlags = NotCommandFlags.Default;

            enumValue = Configuration.GetVariable<NotCommandFlags>(
                interpreter, Constants.NotCommandFlagsEnvVarName,
                notCommandFlags, ref result);

            if (!(enumValue is NotCommandFlags))
                return ReturnCode.Error;

            notCommandFlags = (NotCommandFlags)enumValue;

            string enumString;

            if (argumentCount == 3)
            {
                enumString = arguments[2];

                if (String.IsNullOrEmpty(enumString))
                    enumString = null;

                if (enumString != null)
                {
                    enumValue = Utility.TryParseFlagsEnum(
                        interpreter, typeof(NotCommandFlags),
                        notCommandFlags.ToString(), enumString,
                        cultureInfo, true, true, true,
                        ref result);

                    if (!(enumValue is NotCommandFlags))
                        return ReturnCode.Error;

                    notCommandFlags = (NotCommandFlags)enumValue;
                }
            }

            DateTime now = Utility.GetUtcNow();

            if (now > dateTime)
                return ReturnCode.Ok;

            TimeSpan grace = Constants.GraceDuration;

            string message = String.Format(
                "not valid before {0}", DataOps.FormatTimeStamp(
                dateTime));

#if DEBUG || FORCE_TRACE
            CertificateTraceOps.MaybeLogAndDebugTrace(
                String.Format("NotBefore: {0}", message),
                typeof(Callbacks).Name, TracePriority.Highest |
                TracePriority.Error, 0);
#endif

            if (SharedOps.HasFlags(notCommandFlags,
                    NotCommandFlags.DebuggerOnly, true) &&
                !Configuration.IsThereAnyDebugger())
            {
                return ReturnCode.Ok;
            }

            if (!SharedOps.HasFlags(notCommandFlags,
                    NotCommandFlags.FailFast, true))
            {
                if (SharedOps.HasFlags(notCommandFlags,
                        NotCommandFlags.WarnOnly, true))
                {
                    return ReturnCode.Ok;
                }

                TimeSpan elapsed; /* REUSED */

                if (SharedOps.HasFlags(notCommandFlags,
                        NotCommandFlags.Grace1, true))
                {
                    elapsed = dateTime.Subtract(now);

                    if (elapsed <= grace)
                        return ReturnCode.Ok;
                }

                int? timeout = SharedOps.GetTimeout(
                    interpreter, null);

                if (SharedOps.HasFlags(notCommandFlags,
                        NotCommandFlags.Web, true))
                {
                    string uri = Constants.OutOfTimeUri;

                    if (Utility.IsRemoteUri(uri))
                    {
                        try
                        {
                            Process process = Process.Start(uri);

                            if (SharedOps.HasFlags(notCommandFlags,
                                    NotCommandFlags.WaitForWeb, true) &&
                                (timeout != null))
                            {
                                process.WaitForExit((int)timeout);
                            }

                            return ReturnCode.Ok;
                        }
                        catch (Exception e)
                        {
                            CertificateTraceOps.DebugTrace(
                                e, typeof(Callbacks).Name,
                                TracePriority.Highest);
                        }
                    }
                }

                if (SharedOps.HasFlags(notCommandFlags,
                        NotCommandFlags.Grace2, true))
                {
                    elapsed = dateTime.Subtract(now);
                    grace += grace;

                    if (elapsed <= grace)
                        return ReturnCode.Ok;
                }

#if NETWORK
                if (SharedOps.HasFlags(notCommandFlags,
                        NotCommandFlags.Remote, true))
                {
                    //
                    // HACK: Wait a while for the "asynchronous"
                    //       time server checks to complete and
                    //       then see if one is available.
                    //
                    if (SharedOps.HasFlags(notCommandFlags,
                            NotCommandFlags.WaitForRemote, true) &&
                        (timeout != null))
                    {
                        try
                        {
                            /* NO RESULT */
                            Thread.Sleep((int)timeout); /* throw */
                        }
                        catch (Exception e)
                        {
                            CertificateTraceOps.DebugTrace(
