                    grace += grace;

                    if (elapsed <= grace)
                        return ReturnCode.Ok;
                }
            }

            if (SharedOps.HasFlags(notCommandFlags,
                    NotCommandFlags.FailSafe, true))
            {
                return ReturnCode.Ok;
            }

            result = message;
            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>peekOnFlags</c> introspection command, which
        /// reads a certificate from the named file and inspects the requested
        /// category of its flags.  When a set of flags to test is supplied, a
        /// boolean indicating their presence is returned; otherwise the flags
        /// themselves are returned.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode PeekOnFlags( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 3) || (argumentCount > 4))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} " +
                    "fileName flagType ?hasFlags?\"",
                    Constants.PeekOnFlagsCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo;

#if MONO || MONO_HACKS
            if (Utility.IsMono() && !Utility.IsDefaultAppDomain())
                cultureInfo = null;
            else
#endif
                cultureInfo = evaluateClientData.CultureInfo;

            FlagType flagType = FlagType.Default;
            string enumString; /* REUSED */
            object enumValue; /* REUSED */

            enumString = arguments[2];

            if (String.IsNullOrEmpty(enumString))
                enumString = null;

            if (enumString != null)
            {
                enumValue = Utility.TryParseFlagsEnum(
                    interpreter, typeof(FlagType),
                    flagType.ToString(), enumString,
                    cultureInfo, true, true, true,
                    ref result);

                if (!(enumValue is FlagType))
                    return ReturnCode.Error;

                flagType = (FlagType)enumValue;
            }

            ExecutionPolicy policy;

#if CERTIFICATE_PLUGIN && CERTIFICATE_POLICY
            policy = PolicyOps.GetPolicy(
                interpreter, PolicyType.License);
#else
            policy = Constants.DefaultLicenseExecutionPolicy;
#endif

            bool skipThisAssembly = Utility.HasFlags(
                policy, ExecutionPolicy.SkipThisAssembly,
                true);

            IPlugin plugin = evaluateClientData.Plugin;

            bool isForThisAssembly = !skipThisAssembly ?
                VerifyOps.MatchThisAssembly(null, null,
                plugin) : false;

            ICertificate certificate = null;
            Result localResult; /* REUSED */

#if XML && SERIALIZATION
            localResult = null;

            if (VerifyOps.Import(interpreter,
                    plugin, evaluateClientData.Encoding,
                    evaluateClientData, arguments[1],
                    cultureInfo, evaluateClientData.Timeout,
                    true, true, true, isForThisAssembly,
                    true, ref certificate,
                    ref localResult) != ReturnCode.Ok)
            {
                result = localResult;
                return ReturnCode.Error;
            }
#else
            result = "not implemented";
            return ReturnCode.Error;
#endif

            string hasFlags = null;

            if (argumentCount == 4)
            {
                hasFlags = arguments[3];

                if (String.IsNullOrEmpty(hasFlags))
                    hasFlags = null;

                long flagsKey = Utility.DefaultAttributeFlagsKey();

                if (SharedOps.MatchFlags(
                        certificate, flagType, flagsKey, hasFlags,
                        null, true, false, true) == ReturnCode.Ok)
                {
                    result = true;
                }
                else
                {
                    result = false;
                }
            }
            else
            {
                string flags = SharedOps.GetFlags(
                    certificate, flagType, ref localResult);

                if (flags != null)
                {
                    result = flags;
                }
                else
                {
                    result = localResult;
                    return ReturnCode.Error;
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>queueScript</c> command, which queues a script
        /// together with its byte-array signature for deferred execution,
        /// generating a name automatically when one is not supplied.  Returns
        /// the identifier of the queued script.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode QueueScript( /* CORE */ /* STATE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 3) || (argumentCount > 4))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} " +
                    "script signature ?name?\"",
                    Constants.QueueScriptCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            byte[] signature = null;

            if (!DataOps.TryParseSignature(
                    arguments[2], true, ref signature,
                    ref result))
            {
                return ReturnCode.Error;
            }

            string text = arguments[1];

            if (String.IsNullOrEmpty(text))
                text = null;

            string name = null;

            if (argumentCount == 4)
            {
                name = arguments[3];

                if (String.IsNullOrEmpty(name))
                    name = null;
            }

            if (name == null)
            {
                name = Helpers.MakeScriptName(
                    text, signature, ref result);

                if (name == null)
                    return ReturnCode.Error;
            }

            result = evaluateClientData.QueueScript(
                text, signature, name);

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>queryStatus</c> introspection command, which
        /// returns a single status value selected by name from the
        /// query-status flags.  A wide range of values is supported,
        /// including the configuration phase, public key token, change count,
        /// script type and location, plugin and context identity, machine and
        /// key-pair details, storage type, the various mode flags (SDK, demo,
        /// test, fail-safe, offline), trust levels, runtime and
        /// operating-system identity, version and time stamp, durations,
        /// version ranges, and timeouts.  Returns the string form of the
        /// queried value.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode QueryStatus( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if (argumentCount != 2)
            {
                result = String.Format(
                    "wrong # args: should be \"{0} name\"",
                    Constants.QueryStatusCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            QueryStatusFlags flags = QueryStatusFlags.None;
            string enumString; /* REUSED */
            object enumValue; /* REUSED */

            enumString = arguments[1];

            if (String.IsNullOrEmpty(enumString))
                enumString = null;

            if (enumString != null)
            {
                enumValue = Utility.TryParseFlagsEnum(
                    interpreter, typeof(QueryStatusFlags),
                    flags.ToString(), enumString,
                    cultureInfo, true, true, true,
                    ref result);

                if (!(enumValue is QueryStatusFlags))
                    return ReturnCode.Error;

                flags = (QueryStatusFlags)enumValue;
            }

            switch (flags)
            {
                case QueryStatusFlags.ConfigurationPhase:
                    {
                        result = evaluateClientData.ConfigurationPhase.ToString();
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.PublicKeyToken:
                    {
                        result = AssemblyOps.GetPublicKeyTokenString();
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.ChangeCount:
                    {
                        result = CertificateGlobalState.GetChangeCount();
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.ScriptType:
                    {
                        result = evaluateClientData.Type;
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.ScriptSubType:
                    {
                        result = evaluateClientData.SubType;
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.ScriptDirectory:
                    {
                        result = Path.GetDirectoryName(
                            evaluateClientData.FileName);

                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.ScriptFileId:
                    {
                        result = DataOps.FormatHexadecimal(
                            evaluateClientData.HashValue, false);

                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.ScriptFileName:
                    {
                        result = evaluateClientData.FileName;
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.PluginType:
                    {
                        Type type = evaluateClientData.PluginType;

                        if (type != null)
                            result = type.ToString();
                        else
                            result = null;

                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.ContextName:
                    {
                        result = evaluateClientData.ContextName;
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.VariantName:
                    {
                        result = evaluateClientData.VariantName;
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.Isolated:
                    {
                        result = SharedOps.IsCrossAppDomain(
                            interpreter, evaluateClientData.Plugin);

                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.MustHaveSecurity:
                    {
                        result = CertificateGlobalState.GetMustHaveSecurityAsString();
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.PluginCount:
                    {
#if CERTIFICATE_PLUGIN
                        result = AssemblyOps.GetReferences(
                            interpreter, evaluateClientData.Plugin, true);

                        return ReturnCode.Ok;
#else
                        result = "not implemented";
                        return ReturnCode.Error;
#endif
                    }
                case QueryStatusFlags.Machine:
                    {
#if CERTIFICATE_PLUGIN && CERTIFICATE_POLICY
                        StringList list = null;

                        if (PolicyOps.GetMachine(
                                interpreter, cultureInfo,
                                LicenseState.GetPathFlagsOrDefault(),
                                ref list, ref result) == ReturnCode.Ok)
                        {
                            result = list;
                            return ReturnCode.Ok;
                        }
                        else
                        {
                            return ReturnCode.Error;
                        }
#else
                        result = "not implemented";
                        return ReturnCode.Error;
#endif
                    }
                case QueryStatusFlags.PendingKeyRing:
                    {
#if CERTIFICATE_PLUGIN && CERTIFICATE_POLICY
                        result = CertificateKeyRingState.IsAnyPending();
                        return ReturnCode.Ok;
#else
                        result = "not implemented";
                        return ReturnCode.Error;
#endif
                    }
                case QueryStatusFlags.PendingLicense:
                    {
#if CERTIFICATE_PLUGIN && CERTIFICATE_POLICY
                        result = LicenseState.IsPending();
                        return ReturnCode.Ok;
#else
                        result = "not implemented";
                        return ReturnCode.Error;
#endif
                    }

                case QueryStatusFlags.KeyPair:
                    {
#if CERTIFICATE_PLUGIN && CERTIFICATE_POLICY
                        IKeyPair keyPair = evaluateClientData.KeyPair;

                        result = (keyPair != null) ?
                            DataOps.FormatPublicKeyToken(
                                keyPair.PublicKeyToken,
                                false, false) : null;

                        return ReturnCode.Ok;
#else
                        result = "not implemented";
                        return ReturnCode.Error;
#endif
                    }
                case QueryStatusFlags.KeyPairs:
                    {
#if CERTIFICATE_PLUGIN && CERTIFICATE_POLICY
                        result = DataOps.FormatKeyPairs(
                            evaluateClientData.KeyPairs, false);

                        return ReturnCode.Ok;
#else
                        result = "not implemented";
                        return ReturnCode.Error;
#endif
                    }
                case QueryStatusFlags.PendingDemo:
                    {
#if CERTIFICATE_PLUGIN && CERTIFICATE_POLICY && (DEMO_KEY_PAIRS || DEMO_EDITION)
                        result = CertificateDemoState.IsLicensePending();
                        return ReturnCode.Ok;
#else
                        result = "not implemented";
                        return ReturnCode.Error;
#endif
                    }
                case QueryStatusFlags.PendingRenewal:
                    {
#if CERTIFICATE_PLUGIN && CERTIFICATE_POLICY && NETWORK && CERTIFICATE_RENEWAL
                        result = CertificateKeyRingState.IsRenewalPending();
                        return ReturnCode.Ok;
#else
                        result = "not implemented";
                        return ReturnCode.Error;
#endif
                    }
                case QueryStatusFlags.ForceNetworkLicense:
                    {
                        result = LicenseState.GetForceNetwork();
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.SkipLicense:
                    {
                        result = LicenseState.HaveSkip();
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.Snippet:
                    {
                        IEnumerable<string> names = null;

                        if (interpreter.ListSnippets(null, false,
                                SnippetFlags.QueryStatusMask,
                                LookupFlags.Default, ref names,
                                ref result) == ReturnCode.Ok)
                        {
                            result = (names != null) ?
                                new StringList(names) : null;

                            return ReturnCode.Ok;
                        }
                        else
                        {
                            return ReturnCode.Error;
                        }
                    }
                case QueryStatusFlags.StorageType:
                    {
                        result = CertificateGlobalState.GetStorageTypeAsString();
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.SdkMode:
                    {
                        result = CertificateSdkMode.IsEnabled();
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.DemoMode:
                    {
#if DEMO_KEY_PAIRS || DEMO_EDITION
                        result = CertificateDemoMode.IsEnabled();
                        return ReturnCode.Ok;
#else
                        result = "not implemented";
                        return ReturnCode.Error;
#endif
                    }
                case QueryStatusFlags.TestMode:
                    {
                        result = CertificateTestMode.IsEnabled();
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.FailSafeMode:
                    {
                        result = CertificateFailSafeMode.IsEnabled();
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.OfflineMode:
                    {
#if NETWORK
                        result = Utility.InOfflineMode().ToString();
                        return ReturnCode.Ok;
#else
                        result = "not implemented";
                        return ReturnCode.Error;
#endif
                    }
                case QueryStatusFlags.ExtraFeatures:
                    {
#if CERTIFICATE_PLUGIN && !LIMITED_EDITION
                        result = CertificateGlobalState.GetExtraFeatures();
                        return ReturnCode.Ok;
#else
                        result = "not implemented";
                        return ReturnCode.Error;
#endif
                    }
                case QueryStatusFlags.LicensePathFlags:
                    {
                        result = LicenseState.GetPathFlagsToString();
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.ScriptPathFlags:
                    {
#if CERTIFICATE_PLUGIN && CERTIFICATE_POLICY
                        result = PolicyState.GetPathFlagsToString();
                        return ReturnCode.Ok;
#else
                        result = "not implemented";
                        return ReturnCode.Error;
#endif
                    }
                case QueryStatusFlags.LicenseNetworkFlags:
                    {
                        result = LicenseState.GetNetworkFlagsToString();
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.ScriptNetworkFlags:
                    {
#if CERTIFICATE_PLUGIN && CERTIFICATE_POLICY
                        result = PolicyState.GetNetworkFlagsToString();
                        return ReturnCode.Ok;
#else
                        result = "not implemented";
                        return ReturnCode.Error;
#endif
                    }
                case QueryStatusFlags.ShellFlags:
                    {
#if SHELL && CERTIFICATE_PLUGIN && CERTIFICATE_POLICY && PLUGIN_COMMANDS
                        result = CertificateShellState.GetFlagsToString(
                            interpreter);

                        return ReturnCode.Ok;
#else
                        result = "not implemented";
                        return ReturnCode.Error;
#endif
                    }
                case QueryStatusFlags.ForceNetworkPolicy:
                    {
#if CERTIFICATE_PLUGIN && CERTIFICATE_POLICY
                        result = PolicyState.GetForceNetwork();
                        return ReturnCode.Ok;
#else
                        result = "not implemented";
                        return ReturnCode.Error;
#endif
                    }
                case QueryStatusFlags.ForceNetworkKeyPair:
                    {
#if CERTIFICATE_PLUGIN && CERTIFICATE_POLICY
                        result = CertificateKeyPairState.GetForceNetwork();
                        return ReturnCode.Ok;
#else
                        result = "not implemented";
                        return ReturnCode.Error;
#endif
                    }
                case QueryStatusFlags.CreationDisabled:
                    {
#if CERTIFICATE_PLUGIN && CERTIFICATE_POLICY
                        result = ScriptContext.IsInterpreterCreationDisabled();
                        return ReturnCode.Ok;
#else
                        result = "not implemented";
                        return ReturnCode.Error;
#endif
                    }
                case QueryStatusFlags.Levels:
                    {
                        result = interpreter.Levels;
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.TrustedLevels:
                    {
                        result = interpreter.TrustedLevels;
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.ShellTrustedLevels:
                    {
#if SHELL && CERTIFICATE_PLUGIN && CERTIFICATE_POLICY && PLUGIN_COMMANDS
                        result = ShellOps.GetTrustedLevels();
                        return ReturnCode.Ok;
#else
                        result = "not implemented";
                        return ReturnCode.Error;
#endif
                    }
                case QueryStatusFlags.ShellFallbackLevels:
                    {
#if SHELL && CERTIFICATE_PLUGIN && CERTIFICATE_POLICY && PLUGIN_COMMANDS
                        result = ShellOps.GetFallbackLevels();
                        return ReturnCode.Ok;
#else
                        result = "not implemented";
                        return ReturnCode.Error;
#endif
                    }
                case QueryStatusFlags.IsAdministrator:
                    {
                        result = Utility.IsAdministrator();
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.IsInteractive:
                    {
                        result = Utility.IsInteractive();
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.Runtime:
                    {
                        result = Utility.GetRuntimeNameAndVersion();
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.OperatingSystem:
                    {
                        result = Utility.GetOperatingSystemNameAndVersion();
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.Version:
                    {
                        //
                        // BUGBUG: Is this technically wrong?  Should
                        //         the version of the core library or
                        //         this plugin be returned here?
                        //
                        result = Utility.GetVersion();
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.TemporaryDirectory:
                    {
                        result = Utility.GetTempPath(interpreter);
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.Context:
                    {
                        Result context = null;

                        if (interpreter.GetContext(
                                ref context) == ReturnCode.Ok)
                        {
                            result = StringList.MakeList(
                                "process", Utility.GetCurrentProcessId(),
                                "appDomain", Utility.GetCurrentAppDomainId(),
                                "thread", Utility.GetCurrentThreadId(),
                                "interpreter", interpreter.Id,
                                "context", context);

                            return ReturnCode.Ok;
                        }
                        else
                        {
                            return ReturnCode.Error;
                        }
                    }
                case QueryStatusFlags.TimeStamp:
                    {
                        result = DataOps.FormatTimeStamp(Utility.GetUtcNow());
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.Duration:
                    {
                        result = CertificateTimeState.GetDurations();
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.VersionRange:
                    {
                        result = CertificateVersionState.GetRanges();
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.Timeout:
                    {
                        result = SharedOps.GetTimeout(interpreter, null);
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.LicenseFailureCount:
                    {
                        result = CertificateProcessOps.GetPendingCount(
                            Constants.LicenseFailureCountEnvVarName);

                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.NormalizeErrors:
                    {
#if CERTIFICATE_PLUGIN
                        result = IsolatedState.GetNormalizeErrors();
                        return ReturnCode.Ok;
#else
                        result = "not implemented";
                        return ReturnCode.Error;
#endif
                    }
                case QueryStatusFlags.IncludePublicKeyToken:
                    {
#if CERTIFICATE_PLUGIN
                        result = IsolatedState.GetIncludePublicKeyToken();
                        return ReturnCode.Ok;
#else
                        result = "not implemented";
                        return ReturnCode.Error;
#endif
                    }
                case QueryStatusFlags.RsaProviderCount:
                    {
                        result = SharedOps.GetRsaProviderCount();
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.DsaProviderCount:
                    {
                        result = SharedOps.GetDsaProviderCount();
                        return ReturnCode.Ok;
                    }
                case QueryStatusFlags.UseBigCrypto:
                    {
#if NET_20 || NET_30 || NET_35 || NET_40 || NET_STANDARD_20 || NET_STANDARD_21
                        result = BigRSACryptoServiceProvider.IsEnabled();
                        return ReturnCode.Ok;
#else
                        result = "not implemented";
                        return ReturnCode.Error;
#endif
                    }
                default:
                    {
                        result = String.Format(
                            "unsupported status name {0}", flags);

                        return ReturnCode.Error;
                    }
            }
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>readScript</c> command, which reads a script
        /// file and, when verification is requested, validates its detached
        /// signature file before returning.  Returns a {hexHash scriptText}
        /// list pairing the script's hash with its text.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode ReadScript( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if (argumentCount != 3)
            {
                result = String.Format(
                    "wrong # args: should be \"{0} verify name\"",
                    Constants.ReadScriptCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            bool verify = false;

            if (Value.GetBoolean2(
                    arguments[1], ValueFlags.AnyBoolean, cultureInfo,
                    ref verify, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            string name = arguments[2];

            if (String.IsNullOrEmpty(name))
                name = null;

            string text = null;
            byte[] hashValue = null;

            if (verify)
            {
                byte[] signature = null;

                if (!DataOps.TryReadSignatureFile(
                        interpreter, evaluateClientData.Encoding,
                        DataOps.FormatSignatureFileName(name),
                        evaluateClientData.Timeout,
                        evaluateClientData.AllowRemoteUri,
                        ref signature, ref result))
                {
                    return ReturnCode.Error;
                }

                IKeyPair keyPair = null;

                if (ScriptOps.VerifyFile(
                        interpreter, evaluateClientData, name,
                        signature, evaluateClientData.Timeout,
                        evaluateClientData.AllowRemoteUri,
                        true /* NO-XML */, ref text, ref hashValue,
                        ref keyPair, ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                string keyUsage = __KeyUsage.ReadData;

                if ((keyUsage != null) &&
                    (ScriptOps.CheckKeyUsage(
                        keyPair, keyUsage, EntityType.File,
                        ref result) != ReturnCode.Ok))
                {
                    return ReturnCode.Error;
                }
            }
            else
            {
                if (Engine.ReadScriptFile(
                        interpreter, name, Constants.ReadEngineFlags,
                        ref text, ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }
            }

            result = StringList.MakeList(
                DataOps.FormatHexadecimal(hashValue), text);

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>redeemTicket</c> configuration command, which
        /// validates and consumes a previously issued security ticket for a
        /// given scope and policy type, reading it from the environment using
        /// the supplied key.  Returns the validated ticket string.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode RedeemTicket( /* CORE */ /* STATE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if (argumentCount != 5)
            {
                result = String.Format(
                    "wrong # args: should be \"{0} " +
                    "scope policyType ticket key\"",
                    Constants.RedeemTicketCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            TicketScope scope = TicketScope.Default;
            string enumString; /* REUSED */
            object enumValue; /* REUSED */

            enumString = arguments[1];

            if (String.IsNullOrEmpty(enumString))
                enumString = null;

            if (enumString != null)
            {
                enumValue = Utility.TryParseFlagsEnum(
                    interpreter, typeof(TicketScope),
                    scope.ToString(), enumString,
                    cultureInfo, true, true, true,
                    ref result);

                if (!(enumValue is TicketScope))
                    return ReturnCode.Error;

                scope = (TicketScope)enumValue;
            }

            PolicyType policyType = PolicyType.License;

            enumString = arguments[2];

            if (String.IsNullOrEmpty(enumString))
                enumString = null;

            if (enumString != null)
            {
                enumValue = Utility.TryParseFlagsEnum(
                    interpreter, typeof(PolicyType),
                    policyType.ToString(), enumString,
                    cultureInfo, true, true, true,
                    ref result);

                if (!(enumValue is PolicyType))
                    return ReturnCode.Error;

                policyType = (PolicyType)enumValue;
            }

            byte[] key = null;

            if (Utility.GetBytesFromString(
                    arguments[4], cultureInfo, ref key,
                    ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            SharedOps.ObfuscateKey(
                Utility.GetCurrentProcessId(), ref key);

            Guid? id = null;
            string idString = null;

            if (Utility.DoesEnvironmentVariableExist(
                    Constants.TicketIdEnvVarName, ref idString))
            {
                id = Helpers.GetGuid(
                    cultureInfo, idString, ref result);

                if (id == null)
                    return ReturnCode.Error;
            }

            string ticket = arguments[3];

            if (Helpers.ValidateTicket(interpreter,
                    cultureInfo, DataOps.GetDefaultEncoding(),
                    policyType, scope, key, id, ref ticket,
                    ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            string envVarName = String.Format(
                Constants.TicketEnvVarFormat, policyType);

            if (!Utility.DoesEnvironmentVariableExist(envVarName))
            {
                result = "ticket does not exist in environment";
                return ReturnCode.Error;
            }

            //
            // HACK: Remove validated ticket from the environment,
            //       which we will consider to be "redeeming" the
            //       ticket.
            //
            /* IGNORED */
            Utility.UnsetEnvironmentVariable(envVarName);

            if (id != null)
            {
                /* IGNORED */
                Utility.UnsetEnvironmentVariable(
                    Constants.TicketIdEnvVarName);
            }

            /* IGNORED */
            CertificateGlobalState.IncrementChangeCount();

            result = ticket;
            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>refreshContextVariables</c> command, which
        /// refreshes the context variables in the current call frame from the
        /// full evaluation context data.  The optional read-only argument
        /// (defaulting to true) controls whether the refreshed variables are
        /// made read-only.  Returns the sorted list of refreshed variable
        /// names.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode RefreshContextVariables( /* CORE */ /* RD-CTX */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 1) || (argumentCount > 2))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} ?readOnly?\"",
                    Constants.RefreshContextVariablesCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            if (ScriptOps.IsCallFrameGlobal(interpreter, null))
            {
                result = "current call frame must be local";
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            bool readOnly = true; // TODO: Good default?

            if (argumentCount == 2)
            {
                string valueString = arguments[1];

                if (String.IsNullOrEmpty(valueString))
                    valueString = null;

                if (valueString != null)
                {
                    if (Value.GetBoolean2(
                            valueString, ValueFlags.AnyBoolean,
                            cultureInfo, ref readOnly,
                            ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
                }
            }

            ObjectDictionary variables = null;

            if (ScriptContext.RefreshVariables(
                    interpreter, evaluateClientData.Plugin,
                    evaluateClientData.PluginType,
                    evaluateClientData.ContextName,
                    evaluateClientData.VariantName,
                    Constants.ScriptTypeUnknown,
                    Constants.ScriptSubTypeText,
                    evaluateClientData.HashValue,
                    evaluateClientData.FileName,
                    evaluateClientData.KeyPairs,
                    evaluateClientData.KeyPair, cultureInfo,
                    evaluateClientData.ConfigurationPhase,
                    evaluateClientData.NoGlobalOnly,
                    evaluateClientData.AllowLocalPolicy,
                    false, readOnly, ref variables,
                    ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            if (variables != null)
            {
                StringList list = new StringList(variables.Keys);

                list.Sort(); /* O(N log N) */

                result = list;
            }
            else
            {
                result = null;
            }

            return ReturnCode.Ok;
        }

