        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>requireComponent</c> requirement command, which
        /// requires that a command or define constant with the given name
        /// exists, failing with an "unavailable" error when it does not.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode RequireComponent( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if (argumentCount != 2)
            {
                result = String.Format(
                    "wrong # args: should be \"{0} name\"",
                    Constants.RequireComponentCommandName);

                return ReturnCode.Error;
            }

            StringList list = null;

            if (Helpers.ListCommands(
                    interpreter, clientData, ref list,
                    ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

#if CERTIFICATE_PLUGIN
            CertificatePluginOps.AddDefineConstants(ref list);
#endif

            string name = arguments[1];

            if (list.Contains(name)) /* O(N) */
            {
                return ReturnCode.Ok;
            }
            else
            {
                result = String.Format(
                    "required component {0} is unavailable",
                    Utility.FormatWrapOrNull(name));

                return ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>requireData</c> requirement command, which
        /// retrieves a required value from the current application domain's
        /// data.  The name is a format string parameterized by the process
        /// and application-domain identifiers.  Fails when the data is
        /// unavailable.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode RequireData( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if (argumentCount != 2)
            {
                result = String.Format(
                    "wrong # args: should be \"{0} name\"",
                    Constants.RequireDataCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            AppDomain appDomain = SharedOps.GetAppDomainFromPlugin(
                evaluateClientData.Plugin);

            if (appDomain == null)
            {
                result = "no application domain";
                return ReturnCode.Error;
            }

            string name = arguments[1];

            try
            {
                object value = appDomain.GetData(String.Format(
                    name, Utility.GetCurrentProcessId(),
                    Utility.GetCurrentAppDomainId())); /* throw */

                if (value is string)
                {
                    result = (string)value;
                    return ReturnCode.Ok;
                }
                else
                {
                    result = String.Format(
                        "required data {0} is unavailable (1)",
                        Utility.FormatWrapOrNull(name));

                    return ReturnCode.Error;
                }
            }
#if DEBUG || FORCE_TRACE
            catch (FormatException e)
#else
            catch (FormatException)
#endif
            {
#if DEBUG || FORCE_TRACE
                CertificateTraceOps.DebugTrace(
                    e, typeof(Callbacks).Name,
                    TracePriority.Highest);
#endif

                result = String.Format(
                    "required data {0} is unavailable (2)",
                    Utility.FormatWrapOrNull(name));

                return ReturnCode.Error;
            }
#if DEBUG || FORCE_TRACE
            catch (AppDomainUnloadedException e)
#else
            catch (AppDomainUnloadedException)
#endif
            {
#if DEBUG || FORCE_TRACE
                CertificateTraceOps.DebugTrace(
                    e, typeof(Callbacks).Name,
                    TracePriority.Highest);
#endif

                result = String.Format(
                    "required data {0} is unavailable (3)",
                    Utility.FormatWrapOrNull(name));

                return ReturnCode.Error;
            }
        }

