        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode RequireEnvironment( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if (argumentCount != 2)
            {
                result = String.Format(
                    "wrong # args: should be \"{0} name\"",
                    Constants.RequireEnvironmentCommandName);

                return ReturnCode.Error;
            }

            string name = arguments[1];
            string value = Utility.GetEnvironmentVariable(name);

            if (value != null)
            {
                result = value;
                return ReturnCode.Ok;
            }
            else
            {
                result = String.Format(
                    "required environment {0} is unavailable",
                    Utility.FormatWrapOrNull(name));

                return ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>requireIdentifier</c> requirement command, which
        /// requires that a named identifier (a command, procedure, or
        /// executable entity, optionally narrowed by kind) exists, failing
        /// when it is missing.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode RequireIdentifier( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 2) || (argumentCount > 5))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} " +
                    "name ?package? ?version? ?kind?\"",
                    Constants.RequireIdentifierCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            string identifierName = arguments[1];

            if (String.IsNullOrEmpty(identifierName))
                identifierName = null;

            string packageName = null;

            if (argumentCount >= 3)
            {
                packageName = arguments[2];

                if (String.IsNullOrEmpty(packageName))
                    packageName = null;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            Version version = null;

            if (argumentCount >= 4)
            {
                string valueString = arguments[3];

                if (String.IsNullOrEmpty(valueString))
                    valueString = null;

                if (valueString != null)
                {
                    if (Value.GetVersion(valueString,
                            cultureInfo, ref version,
                            ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
                }
            }

            IdentifierKind kind = IdentifierKind.AnyIExecute;
            string enumString;
            object enumValue;

            if (argumentCount == 5)
            {
                enumString = arguments[4];

                if (String.IsNullOrEmpty(enumString))
                    enumString = null;

                if (enumString != null)
                {
                    enumValue = Utility.TryParseFlagsEnum(
                        interpreter, typeof(IdentifierKind),
                        kind.ToString(), enumString,
                        cultureInfo, true, true, true,
                        ref result);

                    if (!(enumValue is IdentifierKind))
                        return ReturnCode.Error;

                    kind = (IdentifierKind)enumValue;
                }
            }

            ResultList errors = null;

        retry:

            if (identifierName != null)
            {
                if (Helpers.LookupIdentifier(interpreter,
                        kind, arguments, ref identifierName,
                        ref errors) == ReturnCode.Ok)
                {
                    result = identifierName;
                    return ReturnCode.Ok;
                }
            }

            if (packageName != null)
            {
                Result localResult = null;

                if (interpreter.RequirePackage(
                        packageName, version, false,
                        ref localResult) == ReturnCode.Ok)
                {
                    packageName = null;
                    goto retry;
                }
                else
                {
                    if (localResult != null)
                    {
                        if (errors == null)
                            errors = new ResultList();

                        errors.Add(localResult);
                    }
                }
            }

            result = errors;
            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>requireLicense</c> requirement command, which
        /// requires a valid license, optionally loaded from a specific file
        /// and/or validated for a specific policy type, failing the
        /// configuration when no valid license is found.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode RequireLicense( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 1) || (argumentCount > 7))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} " +
                    "?fileName? ?publicKeyToken? ?features? " +
                    "?restrictions? ?addObject? ?plugin?\"",
                    Constants.RequireLicenseCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            string fileName = null;

            if (argumentCount >= 2)
            {
                fileName = arguments[1];

                if (String.IsNullOrEmpty(fileName))
                    fileName = null;
            }

            byte[] publicKeyToken = null;

            if (argumentCount >= 3)
            {
                string valueString = arguments[2];

                if (String.IsNullOrEmpty(valueString))
                    valueString = null;

                if (valueString != null)
                {
                    if (DataOps.ParsePublicKeyToken(
                            valueString, ref publicKeyToken,
                            ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
                }
            }

            string features = null;

            if (argumentCount >= 4)
            {
                features = arguments[3];

                if (String.IsNullOrEmpty(features))
                    features = null;
            }

            string restrictions = null;

            if (argumentCount >= 5)
            {
                restrictions = arguments[4];

                if (String.IsNullOrEmpty(restrictions))
                    restrictions = null;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            bool addObject = false;

            if (argumentCount >= 6)
            {
                string valueString = arguments[5];

                if (String.IsNullOrEmpty(valueString))
                    valueString = null;

                if (valueString != null)
                {
                    if (Value.GetBoolean2(
                            valueString, ValueFlags.AnyBoolean,
                            cultureInfo, ref addObject,
                            ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
                }
            }

            IPlugin plugin = evaluateClientData.Plugin;

            if (argumentCount == 7)
            {
                string valueString = arguments[6];

                if (String.IsNullOrEmpty(valueString))
                    valueString = null;

                if ((valueString != null) ||
                    (publicKeyToken != null))
                {
                    plugin = interpreter.FindPlugin(
                        null, MatchMode.Glob, valueString, null,
                        publicKeyToken, false, ref result);

                    if (plugin == null)
                        return ReturnCode.Error;
                }
            }

            return Helpers.RequireLicense(
                interpreter, plugin, clientData, fileName,
                publicKeyToken, features, restrictions,
                addObject, ref result);
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>requireNetwork</c> requirement command, which
        /// gets or sets whether network access is enabled for a specific
        /// policy type.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode RequireNetwork( /* CORE */ /* WR-CTX */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 2) || (argumentCount > 3))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} policyType ?enable?\"",
                    Constants.RequireNetworkCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            object enumValue;

            enumValue = Utility.TryParseFlagsEnum(
                interpreter, typeof(PolicyType), null,
                arguments[1], cultureInfo, true, true,
                true, ref result);

            if (!(enumValue is PolicyType))
                return ReturnCode.Error;

            PolicyType policyType = (PolicyType)enumValue;
            Result value; /* REUSED */
            bool? oldEnable;

            value = null; /* bool */

            if (interpreter.GetVariableValue(
                    Constants.ContextGetVariableFlags,
                    String.Format(
                        Constants.PluginForceNetworkVariableFormat,
                        Constants.PluginForceNetworkVariableName,
                        policyType),
                    ref value, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            if (String.IsNullOrEmpty(value))
            {
                oldEnable = null;
            }
            else
            {
                oldEnable = null;

                if (Value.GetNullableBoolean2(
                        value, ValueFlags.AnyBoolean, cultureInfo,
                        ref oldEnable, ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }
            }

            if (argumentCount == 3)
            {
                bool? newEnable = null;

                if (Value.GetNullableBoolean2(
                        arguments[2], ValueFlags.AnyBoolean, cultureInfo,
                        ref newEnable, ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                value = newEnable;

                if (interpreter.SetVariableValue(
                        Constants.ContextSetVariableFlags,
                        String.Format(
                            Constants.PluginForceNetworkVariableFormat,
                            Constants.PluginForceNetworkVariableName,
                            policyType),
                        value, null, ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                /* IGNORED */
                ScriptContext.SignalChanged(clientData,
                    String.Format(
                        Constants.PluginForceNetworkVariableFormat,
                        Constants.PluginForceNetworkVariableName,
                        policyType));

                result = newEnable;
            }
            else
            {
                result = oldEnable;
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>requireProcess</c> requirement command, which
        /// verifies the current process against a list of allowed process
        /// identifiers, returning the identifier that matched.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode RequireProcess( /* CORE? */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 2) || (argumentCount > 3))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} list ?flags?\"",
                    Constants.RequireProcessCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            PluginFlags pluginFlags = Constants.ProcessPluginFlags;
            object enumValue;

            if (argumentCount == 3)
            {
                enumValue = Utility.TryParseFlagsEnum(
                    interpreter, typeof(PluginFlags),
                    pluginFlags.ToString(), arguments[2],
                    cultureInfo, true, true, true, ref result);

                if (!(enumValue is PluginFlags))
                    return ReturnCode.Error;

                pluginFlags = (PluginFlags)enumValue;
            }

            GuidList ids = Helpers.GetGuidList(
                interpreter, cultureInfo, arguments[1], ref result);

            if (ids == null)
                return ReturnCode.Error;

            Guid? id = SharedOps.TryExtractProcessId(
                interpreter, cultureInfo, pluginFlags, ref result);

            if (id == null)
                return ReturnCode.Error;

            if (ids.ContainsKey(Guid.Empty)) /* ANY VALID */
            {
                result = Guid.Empty;
                return ReturnCode.Ok;
            }

            if (ids.ContainsKey((Guid)id))
            {
                result = (Guid)id;
                return ReturnCode.Ok;
            }

            result = String.Format(
                "wrong process identifier {0}",
                Utility.FormatWrapOrNull(id));

            return ReturnCode.Error;
        }

