        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>requireTrusted</c> requirement command, which
        /// requires that the current configuration script (or the specified
        /// file) is trusted, failing otherwise.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode RequireTrusted( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 1) || (argumentCount > 2))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} ?fileName?\"",
                    Constants.RequireTrustedCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            string fileNameString = null;

            if (argumentCount == 2)
            {
                fileNameString = arguments[1];

                if (!String.IsNullOrEmpty(fileNameString))
                {
                    fileNameString = Utility.ExpandEnvironmentVariables(
                        fileNameString);
                }
                else
                {
                    fileNameString = null;
                }
            }

            StringList fileNames = new StringList();

            if (fileNameString != null)
            {
                fileNames.Add(fileNameString);
            }
            else
            {
                fileNames.Add(Utility.GetAssemblyLocation());
                fileNames.Add(AssemblyOps.GetFileName());
            }

            StringList subjects = null;

            foreach (string fileName in fileNames)
            {
                if (String.IsNullOrEmpty(fileName))
                {
                    result = "file name is invalid or empty";
                    return ReturnCode.Error;
                }

                if (!File.Exists(fileName))
                {
                    result = String.Format(
                        "file {0} does not exist",
                        Utility.FormatWrapOrNull(fileName));

                    return ReturnCode.Error;
                }

                //
                // BUGBUG: On some platform and operating system
                //         combinations, this will _never_ work,
                //         e.g. .NET Core on Linux, because they
                //         do not have the underlying operating
                //         system API, i.e. WinVerifyTrust.
                //
                if (!Utility.IsFileTrusted(interpreter, fileName))
                {
                    result = String.Format("file {0} is not " +
                        "Authenticode signed or cannot be trusted",
                        Utility.FormatWrapOrNull(fileName));

                    return ReturnCode.Error;
                }

                X509Certificate2 certificate = null;

                if (Utility.GetAssemblyCertificate2(
                        fileName, false, ref certificate,
                        ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                if (certificate != null)
                {
                    string subject = certificate.GetNameInfo(
                        X509NameType.SimpleName, false);

                    if (!String.IsNullOrEmpty(subject))
                    {
                        if (subjects == null)
                            subjects = new StringList();

                        subjects.Add(subject);
                    }
                }
            }

            result = subjects;
            return ReturnCode.Ok;
        }

