        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>requireVariable</c> requirement command, which
        /// requires that a context variable with the given name exists,
        /// failing the configuration when it is missing.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode RequireVariable( /* CORE */ /* RD-CTX */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if (argumentCount != 2)
            {
                result = String.Format(
                    "wrong # args: should be \"{0} name\"",
                    Constants.RequireVariableCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            StringList list = ScriptContext.GetVariableNames(
                evaluateClientData.NoGlobalOnly);

            if (list == null)
            {
                result = "context variables are unavailable";
                return ReturnCode.Error;
            }

            string name = arguments[1];

            if (!list.Contains(name)) /* O(N) */
            {
                result = String.Format(
                    "required variable {0} is unavailable",
                    Utility.FormatWrapOrNull(name));

                return ReturnCode.Error;
            }

            if (interpreter.DoesVariableExist(
                    Constants.ContextExistVariableFlags,
                    name) != ReturnCode.Ok)
            {
                result = String.Format(
                    "required variable {0} not in interpreter {1}",
                    Utility.FormatWrapOrNull(name),
                    DataOps.FormatInterpreter(
                        interpreter, true, false));

                return ReturnCode.Error;
            }

            return ReturnCode.Ok;
        }

