            int count = 0;

            if (ScriptContext.RestoreVariables(
                    interpreter, clientData, arguments[1],
                    evaluateClientData.NoGlobalOnly, false,
                    true, false, true, ref count,
                    ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            result = count;
            return ReturnCode.Ok;
