        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>snippet</c> ensemble command, which manages
        /// reusable code snippets.  Its sub-commands add a snippet
        /// (auto-naming it when needed), clear snippets matching the given
        /// flags, dump a snippet's full details, and evaluate a named
        /// snippet.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode Snippet( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if (argumentCount < 2)
            {
                result = String.Format(
                    Constants.SnippetWrongNumArgsFormat,
                    Constants.SnippetCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            //
            // TODO: At some point, add support for other major
            //       operations exposed via the ISnippetManager
            //       interface, e.g. clear, get, and remove.
            //
            // NOTE: The list operation is already provided via
            //       the [queryStatus] configuration command.
            //
            EnsembleDictionary subCommands = new EnsembleDictionary();

            subCommands.Add("add", null);
            subCommands.Add("clear", null);
            subCommands.Add("dump", null);
            subCommands.Add("evaluate", null);

            string subCommand = arguments[1];

            if (Utility.SubCommandFromEnsemble(
                    interpreter, subCommands, null, true, null,
                    ref subCommand, ref result) == ReturnCode.Ok)
            {
                CultureInfo cultureInfo = evaluateClientData.CultureInfo;
                SnippetFlags snippetFlags = SnippetFlags.Default;
                LookupFlags lookupFlags = LookupFlags.Default;

                switch (subCommand)
                {
                    case "add":
                        {
                            if ((argumentCount < 3) ||
                                (argumentCount > 6))
                            {
                                result = String.Format(
                                    Constants.SnippetWrongNumArgsFormat,
                                    Constants.SnippetCommandName);

                                return ReturnCode.Error;
                            }

                            if (Helpers.GetSnippetFlags(
                                    interpreter, arguments, cultureInfo, 3,
                                    true, ref snippetFlags, ref lookupFlags,
                                    ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }

                            string name = null;

                            if (argumentCount == 6)
                            {
                                name = arguments[5];

                                if (String.IsNullOrEmpty(name))
                                    name = null;
                            }

                            string text = arguments[2];

                            if (interpreter.AddSnippet(text,
                                    snippetFlags, lookupFlags, ref name,
                                    ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }

                            result = name;
                            return ReturnCode.Ok;
                        }
                    case "clear":
                        {
                            if ((argumentCount < 2) ||
                                (argumentCount > 4))
                            {
                                result = String.Format(
                                    Constants.SnippetWrongNumArgsFormat,
                                    Constants.SnippetCommandName);

                                return ReturnCode.Error;
                            }

                            if (Helpers.GetSnippetFlags(
                                    interpreter, arguments, cultureInfo, 2,
                                    true, ref snippetFlags, ref lookupFlags,
                                    ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }

                            int count = 0;

                            if (interpreter.ClearSnippets(
                                    snippetFlags, lookupFlags, ref count,
                                    ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }

                            result = count;
                            return ReturnCode.Ok;
                        }
                    case "dump":
                        {
                            if ((argumentCount < 3) ||
                                (argumentCount > 5))
                            {
                                result = String.Format(
                                    Constants.SnippetWrongNumArgsFormat,
                                    Constants.SnippetCommandName);

                                return ReturnCode.Error;
                            }

                            if (Helpers.GetSnippetFlags(
                                    interpreter, arguments, cultureInfo, 3,
                                    true, ref snippetFlags, ref lookupFlags,
                                    ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }

                            string name = arguments[2];
                            ISnippet snippet = null;

                            if (interpreter.GetSnippet(
                                    name, snippetFlags,
                                    lookupFlags, ref snippet,
                                    ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }

                            if (snippet == null)
                            {
                                result = "invalid snippet";
                                return ReturnCode.Error;
                            }

                            result = (StringPairList)snippet.ToList();
                            return ReturnCode.Ok;
                        }
                    case "evaluate":
                        {
                            if ((argumentCount < 3) ||
                                (argumentCount > 5))
                            {
                                result = String.Format(
                                    Constants.SnippetWrongNumArgsFormat,
                                    Constants.SnippetCommandName);

                                return ReturnCode.Error;
                            }

                            if (Helpers.GetSnippetFlags(
                                    interpreter, arguments, cultureInfo, 3,
                                    true, ref snippetFlags, ref lookupFlags,
                                    ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }

                            string name = arguments[2];

                            return interpreter.EvaluateSnippet(
                                name, snippetFlags, lookupFlags,
                                ref result);
                        }
                    default:
                        {
                            result = String.Format(
                                Constants.SnippetWrongNumArgsFormat,
                                Constants.SnippetCommandName);

                            return ReturnCode.Error;
                        }
                }
            }
            else
            {
                return ReturnCode.Error;
            }
        }

