        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>swapCommands</c> utility command, which swaps
        /// command implementations according to the optional flags, returning
        /// the result of the swap operation.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode SwapCommands( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 1) || (argumentCount > 2))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} ?flags?\"",
                    Constants.SwapCommandsCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            SwapFlags swapFlags = SwapFlags.Default;
            string enumString;
            object enumValue; /* REUSED */

            if (argumentCount >= 2)
            {
                enumString = arguments[1];

                if (String.IsNullOrEmpty(enumString))
                    enumString = null;

                if (enumString != null)
                {
                    enumValue = Utility.TryParseFlagsEnum(
                        interpreter, typeof(SwapFlags),
                        swapFlags.ToString(), enumString,
                        cultureInfo, true, true, true,
                        ref result);

                    if (!(enumValue is SwapFlags))
                        return ReturnCode.Error;

                    swapFlags = (SwapFlags)enumValue;
                }
            }

            string commandName = arguments[0]; /* "swapCommands" */

            if (!DataOps.StringEquals(
                    commandName, Constants.SwapCommandsCommandName))
            {
                result = String.Format(
                    "command name mismatch, want {0}, have {1}",
                    Constants.SwapCommandsCommandName, commandName);

                return ReturnCode.Error;
            }

            long token = 0; /* NOT USED */
            ICommand command = null;

            if (interpreter.GetCommand(
                    commandName, LookupFlags.Default, ref token,
                    ref command, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            if (!SharedOps.IsCommandForPlugin(command))
            {
                result = "command does not belong to plugin";
                return ReturnCode.Error;
            }

            try
            {
                StringList list = new StringList();
                Result error = null;

                if (interpreter.SwapCommands(swapFlags,
                        ref list, ref error) == ReturnCode.Ok)
                {
                    result = list;
                    return ReturnCode.Ok;
                }
                else
                {
                    result = error;
                    return ReturnCode.Error;
                }
            }
            finally
            {
                if (!Utility.HasFlags(
                        swapFlags, SwapFlags.NoRestore, true) &&
                    interpreter.DoesCommandExist(
                        commandName) != ReturnCode.Ok)
                {
                    ReturnCode restoreCode;
                    Result restoreError = null;

                    restoreCode = Helpers.RestoreSwapCommand(
                        interpreter, command, evaluateClientData,
                        clientData, ref restoreError);

                    if (restoreCode != ReturnCode.Ok)
                    {
                        Utility.Complain(
                            interpreter, restoreCode,
                            restoreError);
                    }
                }
            }
        }

