        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>writeStatus</c> output command, which produces
        /// and writes a formatted status report whose included sections are
        /// selected by the status flags: the configured time servers, the
        /// shell flags, the extra feature flags, the per-policy-type policy
        /// detail (key names, execution flags, path and network flags, and
        /// key-ring contents), and a dump of all context variables.  Returns
        /// the formatted status string.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode WriteStatus( /* CORE */ /* RD-CTX */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 1) || (argumentCount > 3))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} ?flags? ?tag?\"",
                    Constants.WriteStatusCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            StatusFlags statusFlags = StatusFlags.Default;
            string enumString;
            object enumValue; /* REUSED */

            if (argumentCount >= 2)
            {
                enumString = arguments[1];

                if (String.IsNullOrEmpty(enumString))
                    enumString = null;

                if (enumString != null)
                {
                    enumValue = Utility.TryParseFlagsEnum(
                        interpreter, typeof(StatusFlags),
                        statusFlags.ToString(), enumString,
                        cultureInfo, true, true, true,
                        ref result);

                    if (!(enumValue is StatusFlags))
                        return ReturnCode.Error;

                    statusFlags = (StatusFlags)enumValue;
                }
            }

            string tag = null;

            if (argumentCount == 3)
            {
                string tagString = arguments[2];

                if (String.IsNullOrEmpty(tagString))
                    tagString = null;

                if (tagString != null)
                    tag = String.Format("[{0}] ", tagString);
            }

            long changeCount = CertificateGlobalState.GetChangeCount();

            bool useContext = SharedOps.HasFlags(
                statusFlags, StatusFlags.Context, true);

            StringBuilder builder = null;
            Result value; /* REUSED */
            StringList list; /* REUSED */

            if (SharedOps.HasFlags(
                    statusFlags, StatusFlags.TimeServers, true))
            {
                if (useContext)
                {
                    value = null;

                    if (interpreter.GetVariableValue(
                            Constants.ContextGetVariableFlags,
                            Constants.PluginTimeServersVariableName,
                            ref value, ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    string servers = value;

                    list = null;

                    if ((servers != null) && Parser.SplitList(
                            interpreter, servers, 0, Length.Invalid, true,
                            ref list, ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
                }
                else
                {
                    IEnumerable<string> collection =
                        interpreter.TimeServers;

                    list = (collection != null) ?
                        new StringList(collection) : null;
                }

                if (builder == null)
                    builder = new StringBuilder();

                builder.AppendFormat(
                    Constants.StatusTimeServersFormat,
                    DataOps.FormatInterpreter(
                        interpreter, true, false), tag,
                    Utility.FormatWrapOrNull(
                        evaluateClientData.PluginType),
                    useContext ?
                        "context " : String.Empty,
                    Utility.FormatWrapOrNull(list),
                    evaluateClientData.Type,
                    evaluateClientData.SubType,
                    Utility.FormatWrapOrNull(
                        evaluateClientData.FileName),
                    Utility.FormatMaybeNull(
                        DataOps.FormatHexadecimal(
                            evaluateClientData.HashValue,
                            false)),
                    changeCount);

                builder.AppendLine();
            }

#if SHELL && CERTIFICATE_PLUGIN && CERTIFICATE_POLICY && PLUGIN_COMMANDS
            if (SharedOps.HasFlags(
                    statusFlags, StatusFlags.ShellFlags, true))
            {
                ShellFlags shellFlags;

                if (useContext)
                {
                    value = null;

                    if (interpreter.GetVariableValue(
                            Constants.ContextGetVariableFlags,
                            Constants.PluginShellFlagsVariableName,
                            ref value, ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    enumValue = Utility.TryParseFlagsEnum(
                        interpreter, typeof(ShellFlags),
                        null, value, cultureInfo, true, true,
                        true, ref result);

                    if (!(enumValue is ShellFlags))
                        return ReturnCode.Error;

                    shellFlags = (ShellFlags)enumValue;
                }
                else
                {
                    shellFlags = CertificateShellState.GetFlags();
                }

                if (builder == null)
                    builder = new StringBuilder();

                builder.AppendFormat(
                    Constants.StatusShellFlagsFormat,
                    DataOps.FormatInterpreter(
                        interpreter, true, false), tag,
                    Utility.FormatWrapOrNull(
                        evaluateClientData.PluginType),
                    useContext ?
                        "context " : String.Empty,
                    Utility.FormatWrapOrNull(shellFlags),
                    evaluateClientData.Type,
                    evaluateClientData.SubType,
                    Utility.FormatWrapOrNull(
                        evaluateClientData.FileName),
                    Utility.FormatMaybeNull(
                        DataOps.FormatHexadecimal(
                            evaluateClientData.HashValue,
                            false)),
                    changeCount);

                builder.AppendLine();
            }
#endif

#if CERTIFICATE_PLUGIN && !LIMITED_EDITION
            if (SharedOps.HasFlags(
                    statusFlags, StatusFlags.ExtraFeatures, true))
            {
                string features;

                if (useContext)
                {
                    value = null;

                    if (interpreter.GetVariableValue(
                            Constants.ContextGetVariableFlags,
                            Constants.PluginFeaturesVariableName,
                            ref value, ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    features = value;
                }
                else
                {
                    features = CertificateGlobalState.GetExtraFeatures();
                }

                if (builder == null)
                    builder = new StringBuilder();

                builder.AppendFormat(
                    Constants.StatusExtraFeaturesFormat,
                    DataOps.FormatInterpreter(
                        interpreter, true, false), tag,
                    Utility.FormatWrapOrNull(
                        evaluateClientData.PluginType),
                    useContext ?
                        "context " : String.Empty,
                    Utility.FormatWrapOrNull(features),
                    evaluateClientData.Type,
                    evaluateClientData.SubType,
                    Utility.FormatWrapOrNull(
                        evaluateClientData.FileName),
                    Utility.FormatMaybeNull(
                        DataOps.FormatHexadecimal(
                            evaluateClientData.HashValue,
                            false)),
                    changeCount);

                builder.AppendLine();
            }
#endif

#if CERTIFICATE_PLUGIN && CERTIFICATE_POLICY
            if (SharedOps.HasFlags(
                    statusFlags, StatusFlags.Policy, true))
            {
                IEnumerable<PolicyType> policyTypes =
                    PolicyOps.GetPolicyTypes();

                if (policyTypes != null)
                {
                    foreach (PolicyType policyType in policyTypes)
                    {
                        //
                        // WARNING: Directly cast policy type to appropriate
                        //          (parallel) status flags value.
                        //
                        if (!SharedOps.HasFlags(
                                statusFlags, (StatusFlags)policyType, true))
                        {
                            continue;
                        }

                        string keyName;
                        string keyRingName;
                        ExecutionPolicy? policy;
                        ScriptFlags? scriptFlags;
                        PathFlags? pathFlags;
                        NetworkFlags? networkFlags;
                        IKeyRing keyRing;
                        IEnumerable<IKeyPair> keyPairs;

                        if (useContext)
                        {
                            value = null;

                            if (PolicyConfiguration.GetPropertyValue(
                                    interpreter, policyType,
                                    Constants.KeyNamePropertyName,
                                    ref value, ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }

                            keyName = value;
                            value = null;

                            if (PolicyConfiguration.GetPropertyValue(
                                    interpreter, policyType,
                                    Constants.KeyRingNamePropertyName,
                                    ref value, ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }

                            keyRingName = value;
                            value = null;

                            if (PolicyConfiguration.GetPropertyValue(
                                    interpreter, policyType,
                                    Constants.CurrentPolicyPropertyName,
                                    ref value, ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }

                            enumValue = Utility.TryParseFlagsEnum(
                                interpreter, typeof(ExecutionPolicy),
                                null, value, cultureInfo, true, true,
                                true, ref result);

                            if (!(enumValue is ExecutionPolicy))
                                return ReturnCode.Error;

                            policy = (ExecutionPolicy)enumValue;
                            value = null;

                            if (PolicyConfiguration.GetPropertyValue(
                                    interpreter, policyType,
                                    Constants.ScriptFlagsPropertyName,
                                    ref value, ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }

                            enumValue = Utility.TryParseFlagsEnum(
                                interpreter, typeof(ScriptFlags),
                                null, value, cultureInfo, true, true,
                                true, ref result);

                            if (!(enumValue is ScriptFlags))
                                return ReturnCode.Error;

                            scriptFlags = (ScriptFlags)enumValue;
                            value = null;

                            if (PolicyConfiguration.GetPropertyValue(
                                    interpreter, policyType,
                                    Constants.PathFlagsPropertyName,
                                    ref value, ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }

                            enumValue = Utility.TryParseFlagsEnum(
                                interpreter, typeof(PathFlags),
                                null, value, cultureInfo, true, true,
                                true, ref result);

                            if (!(enumValue is PathFlags))
                                return ReturnCode.Error;

                            pathFlags = (PathFlags)enumValue;
                            value = null;

                            if (PolicyConfiguration.GetPropertyValue(
                                    interpreter, policyType,
                                    Constants.NetworkFlagsPropertyName,
                                    ref value, ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }

                            enumValue = Utility.TryParseFlagsEnum(
                                interpreter, typeof(NetworkFlags),
                                null, value, cultureInfo, true, true,
                                true, ref result);

                            if (!(enumValue is NetworkFlags))
                                return ReturnCode.Error;

                            networkFlags = (NetworkFlags)enumValue;

                            //
                            // HACK: There is no context key ring; use
                            //       key pairs from the context directly.
                            //
                            keyPairs = evaluateClientData.KeyPairs;
                        }
                        else
                        {
                            PolicyConfiguration.GetState(
                                evaluateClientData.Plugin, policyType,
                                evaluateClientData.AllowLocalPolicy,
                                out keyName, out keyRingName,
                                out policy, out scriptFlags,
                                out pathFlags, out networkFlags);

                            keyRing = null;

                            if (KeyRingOps.GetKeyRing(
                                    interpreter, keyRingName,
                                    policyType, ref keyRing,
                                    ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }

                            keyPairs = null;

                            if ((keyRing != null) &&
                                keyRing.List(ref keyPairs,
                                    ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }
                        }

                        if (SharedOps.HasFlags(
                                statusFlags, StatusFlags.KeyName, true))
                        {
                            if (builder == null)
                                builder = new StringBuilder();

                            builder.AppendFormat(
                                Constants.StatusPolicyKeyNameFormat,
                                DataOps.FormatInterpreter(
                                    interpreter, true, false), tag,
                                Utility.FormatWrapOrNull(
                                    evaluateClientData.PluginType),
                                policyType, useContext ?
                                    "context " : String.Empty,
                                Utility.FormatWrapOrNull(keyName),
                                evaluateClientData.Type,
                                evaluateClientData.SubType,
                                Utility.FormatWrapOrNull(
                                    evaluateClientData.FileName),
                                Utility.FormatMaybeNull(
                                    DataOps.FormatHexadecimal(
                                        evaluateClientData.HashValue,
                                        false)),
                                changeCount);

                            builder.AppendLine();
                        }

                        if (SharedOps.HasFlags(
                                statusFlags, StatusFlags.KeyRingName, true))
                        {
                            if (builder == null)
                                builder = new StringBuilder();

                            builder.AppendFormat(
                                Constants.StatusPolicyKeyRingNameFormat,
                                DataOps.FormatInterpreter(
                                    interpreter, true, false), tag,
                                Utility.FormatWrapOrNull(
                                    evaluateClientData.PluginType),
                                policyType, useContext ?
                                    "context " : String.Empty,
                                Utility.FormatWrapOrNull(keyRingName),
                                evaluateClientData.Type,
                                evaluateClientData.SubType,
                                Utility.FormatWrapOrNull(
                                    evaluateClientData.FileName),
                                Utility.FormatMaybeNull(
                                    DataOps.FormatHexadecimal(
                                        evaluateClientData.HashValue,
                                        false)),
                                changeCount);

                            builder.AppendLine();
                        }

                        if (SharedOps.HasFlags(
                                statusFlags, StatusFlags.ExecutionFlags, true))
                        {
                            if (builder == null)
                                builder = new StringBuilder();

                            builder.AppendFormat(
                                Constants.StatusPolicyExecutionFlagsFormat,
                                DataOps.FormatInterpreter(
                                    interpreter, true, false), tag,
                                Utility.FormatWrapOrNull(
                                    evaluateClientData.PluginType),
                                policyType, useContext ?
                                    "context " : String.Empty,
                                Utility.FormatWrapOrNull(policy),
                                evaluateClientData.Type,
                                evaluateClientData.SubType,
                                Utility.FormatWrapOrNull(
                                    evaluateClientData.FileName),
                                Utility.FormatMaybeNull(
                                    DataOps.FormatHexadecimal(
                                        evaluateClientData.HashValue,
                                        false)),
                                changeCount);

                            builder.AppendLine();
                        }

                        if (SharedOps.HasFlags(
                                statusFlags, StatusFlags.ScriptFlags, true))
                        {
                            if (builder == null)
                                builder = new StringBuilder();

                            builder.AppendFormat(
                                Constants.StatusPolicyScriptFlagsNameFormat,
                                DataOps.FormatInterpreter(
                                    interpreter, true, false), tag,
                                Utility.FormatWrapOrNull(
                                    evaluateClientData.PluginType),
                                policyType, useContext ?
                                    "context " : String.Empty,
                                Utility.FormatWrapOrNull(scriptFlags),
                                evaluateClientData.Type,
                                evaluateClientData.SubType,
                                Utility.FormatWrapOrNull(
                                    evaluateClientData.FileName),
                                Utility.FormatMaybeNull(
                                    DataOps.FormatHexadecimal(
                                        evaluateClientData.HashValue,
                                        false)),
                                changeCount);

                            builder.AppendLine();
                        }

                        if (SharedOps.HasFlags(
                                statusFlags, StatusFlags.PathFlags, true))
                        {
                            if (builder == null)
                                builder = new StringBuilder();

                            builder.AppendFormat(
                                Constants.StatusPolicyPathFlagsNameFormat,
                                DataOps.FormatInterpreter(
                                    interpreter, true, false), tag,
                                Utility.FormatWrapOrNull(
                                    evaluateClientData.PluginType),
                                policyType, useContext ?
                                    "context " : String.Empty,
                                Utility.FormatWrapOrNull(pathFlags),
                                evaluateClientData.Type,
                                evaluateClientData.SubType,
                                Utility.FormatWrapOrNull(
                                    evaluateClientData.FileName),
                                Utility.FormatMaybeNull(
                                    DataOps.FormatHexadecimal(
                                        evaluateClientData.HashValue,
                                        false)),
                                changeCount);

                            builder.AppendLine();
                        }

                        if (SharedOps.HasFlags(
                                statusFlags, StatusFlags.NetworkFlags, true))
                        {
                            if (builder == null)
                                builder = new StringBuilder();

                            builder.AppendFormat(
                                Constants.StatusPolicyNetworkFlagsNameFormat,
                                DataOps.FormatInterpreter(
                                    interpreter, true, false), tag,
                                Utility.FormatWrapOrNull(
                                    evaluateClientData.PluginType),
                                policyType, useContext ?
                                    "context " : String.Empty,
                                Utility.FormatWrapOrNull(networkFlags),
                                evaluateClientData.Type,
                                evaluateClientData.SubType,
                                Utility.FormatWrapOrNull(
                                    evaluateClientData.FileName),
                                Utility.FormatMaybeNull(
                                    DataOps.FormatHexadecimal(
                                        evaluateClientData.HashValue,
                                        false)),
                                changeCount);

                            builder.AppendLine();
                        }

                        if (SharedOps.HasFlags(
                                statusFlags, StatusFlags.KeyRing, true))
                        {
                            if (builder == null)
                                builder = new StringBuilder();

                            builder.AppendFormat(
                                Constants.StatusPolicyKeyRingFormat,
                                DataOps.FormatInterpreter(
                                    interpreter, true, false), tag,
                                Utility.FormatWrapOrNull(
                                    evaluateClientData.PluginType),
                                policyType, useContext ?
                                    "context " : String.Empty,
                                DataOps.FormatKeyPairs(
                                    keyPairs, true),
                                evaluateClientData.Type,
                                evaluateClientData.SubType,
                                Utility.FormatWrapOrNull(
                                    evaluateClientData.FileName),
                                Utility.FormatMaybeNull(
                                    DataOps.FormatHexadecimal(
                                        evaluateClientData.HashValue,
                                        false)),
                                changeCount);

                            builder.AppendLine();
                        }
                    }
                }
            }

            if (SharedOps.HasFlags(
                    statusFlags, StatusFlags.DumpState, true))
            {
                ObjectDictionary variables = ScriptContext.GetVariables(
                    interpreter, evaluateClientData.Plugin,
                    evaluateClientData.PluginType,
                    evaluateClientData.ContextName,
                    evaluateClientData.VariantName,
                    evaluateClientData.Type,
                    evaluateClientData.SubType,
                    evaluateClientData.HashValue,
                    evaluateClientData.FileName,
                    evaluateClientData.KeyPairs,
                    evaluateClientData.KeyPair, cultureInfo,
                    evaluateClientData.ConfigurationPhase,
                    evaluateClientData.NoGlobalOnly,
                    evaluateClientData.AllowLocalPolicy,
                    false, false);

                if (variables != null)
                {
                    string prefix = DataOps.FormatHexadecimal(
                        RuntimeHelpers.GetHashCode(clientData));

                    foreach (VariablePair pair in variables)
                    {
                        if (builder == null)
                            builder = new StringBuilder();

                        builder.AppendFormat(
                            Constants.NameValuePairFormat,
                            Utility.FormatMaybeNull(prefix),
                            Characters.Space, pair.Key,
                            Characters.EqualSign,
                            Utility.FormatWrapOrNull(
                                pair.Value));

                        builder.AppendLine();
                    }
                }
            }
#endif

            return Helpers.WriteBuilder(
                interpreter, clientData, builder, ref result);
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>writeWithoutFail</c> output command, which
        /// concatenates all of its arguments into a single output string with
        /// separators and writes it, returning the concatenated text.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode WriteWithoutFail( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if (argumentCount < 2)
            {
                result = String.Format(
                    "wrong # args: should be \"{0} arg ?arg ...?\"",
                    Constants.WriteWithoutFailCommandName);

                return ReturnCode.Error;
            }

            /* NO RESULT */
            Helpers.MaybeInsertSeriousSeparators(
                interpreter, arguments, 1, Characters.NumberSign);

            StringBuilder builder = null;

            /* NO RESULT */
            Helpers.BuildOutput(arguments, 1, ref builder);

            return Helpers.WriteBuilder(
                interpreter, clientData, builder, ref result);
        }

        ///////////////////////////////////////////////////////////////////////

#if CERTIFICATE_PLUGIN && PLUGIN_COMMANDS
        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>changeLicenseProperty</c> configuration command,
        /// a getter/setter for the named properties of a license.  With only
        /// an identifier the property names of the license are listed; with
        /// an identifier and name a specific property value is read; with an
        /// identifier, name, and value the property is set.  Available only
        /// when compiled with certificate plugin and plugin command support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode ChangeLicenseProperty( /* STATE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 2) || (argumentCount > 4))
            {
                result = String.Format(
                    Constants.ChangeLicensePropertyWrongNumArgsFormat,
                    Constants.ChangeLicensePropertyCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            Guid id = Guid.Empty;

            if (!String.IsNullOrEmpty(arguments[1]))
            {
                if (Value.GetGuid(
                        arguments[1], cultureInfo, ref id,
                        ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                if (id.Equals(Guid.Empty))
                {
                    result = "empty guid value not allowed";
                    return ReturnCode.Error;
                }
            }

            switch (argumentCount)
            {
                case 2:
                    {
                        if (Helpers.GetLicenseProperties(id, ref result))
                        {
                            return ReturnCode.Ok;
                        }
                        else
                        {
                            return ReturnCode.Error;
                        }
                    }
                case 3:
                    {
                        if (Helpers.GetLicensePropertyValue(
                                interpreter, evaluateClientData.Plugin,
                                id, arguments[2], ref result))
                        {
                            return ReturnCode.Ok;
                        }
                        else
                        {
                            return ReturnCode.Error;
                        }
                    }
                case 4:
                    {
                        if (!Helpers.ChangeLicensePropertyValue(
                                interpreter, evaluateClientData.Plugin,
                                id, arguments[2], arguments[3].Value,
                                cultureInfo, ref result))
                        {
                            return ReturnCode.Error;
                        }

                        goto case 3;
                    }
                default:
                    {
                        result = String.Format(
                            Constants.ChangeLicensePropertyWrongNumArgsFormat,
                            Constants.ChangeLicensePropertyCommandName);

                        return ReturnCode.Error;
                    }
            }
        }
#endif

        ///////////////////////////////////////////////////////////////////////

#if TEST
        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>cleanupForSandbox</c> command, which releases
        /// the resources associated with a completed sandbox evaluation: it
        /// verifies the sandbox has finished, removes it, and unsets its
        /// related variables, failing when the sandbox is still active.
        /// Available only when compiled with test support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode CleanupForSandbox( /* CORE */ /* STATE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if (argumentCount != 2)
            {
                result = String.Format(
                    "wrong # args: should be \"{0} id\"",
                    Constants.CleanupForSandboxCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                ScriptOps.GetClientData(interpreter);

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            long nextId = 0;

            if (Value.GetWideInteger2((IGetValue)arguments[1],
                    ValueFlags.AnyInteger, cultureInfo,
                    ref nextId, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            Interpreter parentInterpreter = null;
            string parentVarName = null;
            long parentNextId = 0;
            EventWaitHandle parentEvent = null;
            string parentEventToString = null;
            bool success = false;
            ResultList errors = null;

            try
            {
                SandboxData sandboxData;

                if (!evaluateClientData.TryGetSandbox(
                        nextId, out sandboxData))
                {
                    result = String.Format(
                        "missing evaluation sandbox {0}", nextId);

                    return ReturnCode.Error;
                }

                if (sandboxData == null)
                {
                    result = String.Format(
                        "invalid evaluation sandbox {0}", nextId);

                    return ReturnCode.Error;
                }

                parentInterpreter = evaluateClientData.Interpreter;
                parentVarName = sandboxData.VarName;
                parentNextId = sandboxData.NextId;
                parentEvent = sandboxData.Event;

                success = SandboxOps.MaybeWaitEvent(
                    parentEvent, 0, ref parentEventToString,
                    ref errors);

                if (!success)
                {
                    if (errors == null)
                        errors = new ResultList();

                    errors.Insert(0, String.Format(
                        "cannot cleanup for active sandbox {0}",
                        parentNextId));

                    result = errors;
                    return ReturnCode.Error;
                }

                if (!evaluateClientData.RemoveSandbox(sandboxData))
                {
                    if (errors == null)
                        errors = new ResultList();

                    errors.Insert(0, String.Format(
                        "could not remove evaluation sandbox {0}",
                        nextId));
                }

                /* IGNORED */
                SandboxOps.MaybeCloseEvent(
                    ref parentEvent, ref parentEventToString,
                    ref errors);

                int timeout = Constants.SandboxVariableTimeout;

                /* IGNORED */
                SandboxOps.MaybeUnsetVariable(
                    parentInterpreter,
                    Constants.SandboxReturnCodeVarNameFormat,
                    parentVarName, parentNextId, timeout,
                    ref errors);

                /* IGNORED */
                SandboxOps.MaybeUnsetVariable(
                    parentInterpreter,
                    Constants.SandboxResultVarNameFormat,
                    parentVarName, parentNextId, timeout,
                    ref errors);

                /* IGNORED */
                SandboxOps.MaybeUnsetVariable(
                    parentInterpreter,
                    Constants.SandboxWaitVarNameFormat,
                    parentVarName, parentNextId, timeout,
                    ref errors);

                return ReturnCode.Ok;
            }
            catch (Exception e)
            {
                result = e;
                return ReturnCode.Error;
            }
            finally
            {
#if DEBUG || FORCE_TRACE
                if (errors != null)
                {
                    CertificateTraceOps.DebugTrace(String.Format(
                        "CleanupForSandbox: interpreter = {0}, " +
                        "varName = {1}, nextId = {2}, parentNextId = {3}, " +
                        "event = {4}, success = {5}, result = {6}, " +
                        "errors = {7}",
                        DataOps.FormatInterpreter(
                            parentInterpreter, true, false),
                        Utility.FormatWrapOrNull(parentVarName),
                        nextId, parentNextId,
                        Utility.FormatWrapOrNull(parentEventToString),
                        success,
                        Utility.FormatWrapOrNull(result),
                        Utility.FormatWrapOrNull(errors)),
                        typeof(Callbacks).Name, TracePriority.MediumLow);
                }
#endif
            }
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>evaluateInSandbox</c> command, which begins
        /// asynchronous evaluation of a script file in an isolated
        /// child-interpreter sandbox by queuing the work item on the thread
        /// pool, optionally recording the sandbox identifier in the named
        /// variable.  Returns the sandbox identifier.  Available only when
        /// compiled with test support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode EvaluateInSandbox( /* CORE */ /* STATE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 2) || (argumentCount > 3))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} fileName ?varName?\"",
                    Constants.EvaluateInSandboxCommandName);

                return ReturnCode.Error;
            }

            try
            {
                EvaluateClientData evaluateClientData =
                    ScriptOps.GetClientData(interpreter);

                if (evaluateClientData == null)
                {
                    result = "missing context clientData";
                    return ReturnCode.Error;
                }

                string varName = null;

                if (argumentCount == 3)
                    varName = arguments[2];

                long nextId = interpreter.NextId();

                SandboxData sandboxData = new SandboxData(
                    varName, nextId, new ManualResetEvent(false));

                if (!evaluateClientData.AddSandbox(sandboxData))
                {
                    result = String.Format(
                        "could not add evaluation sandbox {0} (1)",
                        nextId);

                    return ReturnCode.Error;
                }

                bool queued = false;
                EvaluateClientData newEvaluateClientData = null;

                try
                {
                    ResultList errors = null;

                    newEvaluateClientData = EvaluateClientData.ForNewScript(
                        evaluateClientData, interpreter, arguments[1],
                        ref errors); /* EXEMPT */

                    //
                    // BUGFIX: The required version was ALWAYS intended to be
                    //         checked on a per-file basis.
                    //
                    /* IGNORED */
                    EvaluateClientData.ResetRequiredVersion(
                        newEvaluateClientData, true);

                    if (!newEvaluateClientData.AddSandbox(sandboxData))
                    {
                        result = String.Format(
                            "could not add evaluation sandbox {0} (2)",
                            nextId);

                        return ReturnCode.Error;
                    }

                    if (errors == null)
                    {
                        Utility.QueueUserWorkItem(
                            new WaitCallback(
                                SandboxOps.EvaluateWithin),
                            new SandboxPair(
                                newEvaluateClientData, nextId),
                            QueueFlags.Default);

                        queued = true;
                        result = nextId;

                        return ReturnCode.Ok;
                    }
                    else
                    {
                        result = errors;
                        return ReturnCode.Error;
                    }
                }
                finally
                {
                    if (!queued && (newEvaluateClientData != null))
                    {
                        newEvaluateClientData.Dispose();
                        newEvaluateClientData = null;
                    }
                }
            }
            catch (Exception e)
            {
                result = e;
                return ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>waitForSandbox</c> command, which waits for a
        /// sandbox evaluation to complete, up to the optional timeout
        /// (defaulting to the configured sandbox timeout).  Returns a boolean
        /// indicating whether the wait succeeded within the timeout.
        /// Available only when compiled with test support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode WaitForSandbox( /* CORE */ /* STATE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 2) || (argumentCount > 3))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} id ?timeout?\"",
                    Constants.WaitForSandboxCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                ScriptOps.GetClientData(interpreter);

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            long nextId = 0;

            if (Value.GetWideInteger2((IGetValue)arguments[1],
                    ValueFlags.AnyInteger, cultureInfo,
                    ref nextId, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            int timeout = Constants.EvaluateInSandboxTimeout;

            if (argumentCount == 3)
            {
                string valueString = arguments[2];

                if (String.IsNullOrEmpty(valueString))
                    valueString = null;

                if (valueString != null)
                {
                    if (Value.GetInteger2(
                            valueString, ValueFlags.AnyInteger,
                            cultureInfo, ref timeout,
                            ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
                }
            }

            Interpreter parentInterpreter = null;
            string parentVarName = null;
            long parentNextId = 0;
            EventWaitHandle parentEvent = null;
            string parentEventToString = null;
            bool success = false;
            ResultList errors = null;

            try
            {
                SandboxData sandboxData;

                if (!evaluateClientData.TryGetSandbox(
                        nextId, out sandboxData))
                {
                    result = String.Format(
                        "missing evaluation sandbox {0}", nextId);

                    return ReturnCode.Error;
                }

                if (sandboxData == null)
                {
                    result = String.Format(
                        "invalid evaluation sandbox {0}", nextId);

                    return ReturnCode.Error;
                }

                parentInterpreter = evaluateClientData.Interpreter;
                parentVarName = sandboxData.VarName;
                parentNextId = sandboxData.NextId;
                parentEvent = sandboxData.Event;

                success = SandboxOps.MaybeWaitEvent(
                    parentEvent, timeout, ref parentEventToString,
                    ref errors);

                result = success;
                return ReturnCode.Ok;
            }
            catch (Exception e)
            {
                result = e;
                return ReturnCode.Error;
            }
            finally
            {
                /* IGNORED */
                SandboxOps.MaybeSetVariableValue(
                    parentInterpreter, Constants.SandboxWaitVarNameFormat,
                    parentVarName, success.ToString(), parentNextId,
                    Constants.SandboxVariableTimeout, ref errors);

#if DEBUG || FORCE_TRACE
                if (errors != null)
                {
                    CertificateTraceOps.DebugTrace(String.Format(
                        "WaitForSandbox: interpreter = {0}, " +
                        "varName = {1}, nextId = {2}, parentNextId = {3}, " +
                        "event = {4}, success = {5}, result = {6}, " +
                        "errors = {7}",
                        DataOps.FormatInterpreter(
                            parentInterpreter, true, false),
                        Utility.FormatWrapOrNull(parentVarName),
                        nextId, parentNextId,
                        Utility.FormatWrapOrNull(parentEventToString),
                        success,
                        Utility.FormatWrapOrNull(result),
                        Utility.FormatWrapOrNull(errors)),
                        typeof(Callbacks).Name, TracePriority.MediumLow);
                }
#endif
            }
        }
#endif

