        ///////////////////////////////////////////////////////////////////////

#if NETWORK && WEB
        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>downloadAndInstall</c> command, which downloads
        /// a package from the given URI, extracts it, and installs it into
        /// the target directory (optionally for a specific plugin) subject to
        /// the install flags.  The operation is refused while offline mode is
        /// active.  Available only when compiled with XML, network, and web
        /// support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode DownloadAndInstall( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (Utility.InOfflineMode())
            {
                result = "cannot download package in offline mode";
                return ReturnCode.Error;
            }

            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 2) || (argumentCount > 5))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} " +
                    "uri ?flags? ?targetDirectory? ?plugin?\"",
                    Constants.DownloadAndInstallCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            Uri uri = null;

            if (Value.GetUri(
                    arguments[1], UriKind.Absolute, cultureInfo,
                    ref uri, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            string fileNameOnly = Path.GetFileName(uri.LocalPath);

            if (String.IsNullOrEmpty(fileNameOnly))
            {
                result = "invalid local file name from uri";
                return ReturnCode.Error;
            }

            InstallFlags installFlags = InstallFlags.Default;
            string enumString;
            object enumValue;

            if (argumentCount >= 3)
            {
                enumString = arguments[2];

                if (String.IsNullOrEmpty(enumString))
                    enumString = null;

                if (enumString != null)
                {
                    enumValue = Utility.TryParseFlagsEnum(
                        interpreter, typeof(InstallFlags),
                        installFlags.ToString(), enumString,
                        cultureInfo, true, true, true,
                        ref result);

                    if (!(enumValue is InstallFlags))
                        return ReturnCode.Error;

                    installFlags = (InstallFlags)enumValue;
                }
            }

            string targetDirectory = null; /* TODO: Good default? */

            if (argumentCount >= 4)
            {
                targetDirectory = arguments[3];

                if (String.IsNullOrEmpty(targetDirectory))
                    targetDirectory = null;
            }

            IPlugin plugin = evaluateClientData.Plugin;

            if (argumentCount == 5)
            {
                string valueString = arguments[4];

                if (String.IsNullOrEmpty(valueString))
                    valueString = null;

                if (valueString != null)
                {
                    plugin = interpreter.FindPlugin(
                        null, MatchMode.Glob, valueString, null,
                        null, false, ref result);

                    if (plugin == null)
                        return ReturnCode.Error;
                }
            }

            int? timeout = evaluateClientData.Timeout;

            if (timeout == null)
                timeout = SharedOps.GetTimeout(interpreter, null);

            DateTime started = Utility.GetUtcNow();
            string temporaryPath = null;
            string temporaryDirectory = null;
            string downloadDirectory = null;
            string extractDirectory = null;

            try
            {
                temporaryPath = Utility.GetTempPath(interpreter);

                if (String.IsNullOrEmpty(temporaryPath))
                {
                    result = "invalid temporary path";
                    return ReturnCode.Error;
                }

                if (!Directory.Exists(temporaryPath))
                {
                    result = "temporary path does not exist";
                    return ReturnCode.Error;
                }

                if (Utility.GetPathType(
                        temporaryPath) != PathType.Absolute)
                {
                    result = "temporary path is not absolute";
                    return ReturnCode.Error;
                }

                temporaryDirectory = Utility.GetUniquePath(
                    interpreter, temporaryPath, null, null,
                    ref result);

                if (temporaryDirectory == null)
                    return ReturnCode.Error;

                downloadDirectory = Path.Combine(
                    temporaryDirectory,
                    Constants.DownloadDirectoryName);

                extractDirectory = Path.Combine(
                    temporaryDirectory,
                    Constants.ExtractDirectoryName);

                Directory.CreateDirectory(
                    temporaryDirectory); /* throw */

                Directory.CreateDirectory(
                    downloadDirectory); /* throw */

                Directory.CreateDirectory(
                    extractDirectory); /* throw */

                string downloadFileName = Path.Combine(
                    downloadDirectory, fileNameOnly);

                try
                {
#if TEST
                    if (Utility.SetWebSecurityProtocol(
                            false, ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
#endif

                    if (Utility.DownloadFile(
                            interpreter, clientData, uri,
                            downloadFileName,
                            NetworkState.GetMaximumRetries(),
                            timeout, null,
                            ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    if (Utility.ExtractZipFileToDirectory(
                            interpreter, clientData,
                            downloadDirectory, downloadFileName,
                            extractDirectory, null, null,
                            ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    if (targetDirectory == null)
                    {
                        /* IGNORED */
                        CertificatePathOps.GetDirectory(
                            plugin, ref targetDirectory);
                    }

                    //
                    // HACK: Wait until now to actually allocate
                    //       a new GUID value; previously, this
                    //       was (sometimes) done when calling
                    //       the EvaluateClientData constructor;
                    //       however, that was seen as a "waste"
                    //       of resources.
                    //
                    /* NO RESULT */
                    evaluateClientData.NeedUniqueId(
                        SharedOps.HasFlags(installFlags,
                            InstallFlags.ForceUniqueId, true));

                    if (Helpers.PerformInstall(
                            interpreter, evaluateClientData,
                            extractDirectory, targetDirectory,
                            timeout, installFlags,
                            ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    return ReturnCode.Ok;
                }
                finally
                {
                    //
                    // BUGFIX: Why was this file always being
                    //         left behind before?  Actually,
                    //         it was not, due to the primary
                    //         cleanup call (in the outermost
                    //         finally block) below; however,
                    //         that is not quite right either
                    //         because it may have prevented
                    //         the (empty?) download directory
                    //         from being cleaned up and maybe
                    //         even cause issues with primary
                    //         cleanup.
                    //
                    if ((downloadFileName != null) &&
                        File.Exists(downloadFileName))
                    {
                        try
                        {
                            File.Delete(downloadFileName);
                        }
#if DEBUG || FORCE_TRACE
                        catch (Exception e)
#else
                        catch
#endif
                        {
#if DEBUG || FORCE_TRACE
                            CertificateTraceOps.DebugTrace(
                                e, typeof(Callbacks).Name,
                                TracePriority.Highest);
#endif
                        }
                    }
                }
            }
            catch (Exception e)
            {
                result = e;
                return ReturnCode.Error;
            }
            finally
            {
                if ((extractDirectory != null) &&
                    Directory.Exists(extractDirectory))
                {
                    try
                    {
                        Directory.Delete(extractDirectory, false);
                    }
#if DEBUG || FORCE_TRACE
                    catch (Exception e)
#else
                    catch
#endif
                    {
#if DEBUG || FORCE_TRACE
                        CertificateTraceOps.DebugTrace(
                            e, typeof(Callbacks).Name,
                            TracePriority.Highest);
#endif
                    }
                }

                if ((downloadDirectory != null) &&
                    Directory.Exists(downloadDirectory))
                {
                    try
                    {
                        Directory.Delete(downloadDirectory, false);
                    }
#if DEBUG || FORCE_TRACE
                    catch (Exception e)
#else
                    catch
#endif
                    {
#if DEBUG || FORCE_TRACE
                        CertificateTraceOps.DebugTrace(
                            e, typeof(Callbacks).Name,
                            TracePriority.Highest);
#endif
                    }
                }

                if ((temporaryDirectory != null) &&
                    (temporaryPath != null) &&
                    Utility.IsUnderPath(
                        interpreter, temporaryDirectory, temporaryPath))
                {
                    //
                    // HACK: *WARNING* Yes, this is somewhat "dangerous"
                    //       because it will delete all files within our
                    //       created temporary directory; however, it is
                    //       a secure temporary directory created by us,
                    //       which should never be used by the user -OR-
                    //       any other process.
                    //
                    /* IGNORED */
                    Utility.CleanupDirectory(
                        temporaryDirectory, new string[] {
                            Characters.Asterisk.ToString()
                        }, true
                    );
                }

#if DEBUG || FORCE_TRACE
                CertificateTraceOps.MaybeLogAndDebugTrace(
                    String.Format(
                        "DownloadAndInstall: completed in about {0}: {1}",
                        Utility.GetUtcNow().Subtract(started),
                        Utility.FormatWrapOrNull(result)),
                    typeof(Callbacks).Name, TracePriority.Highest, 0);
#endif
            }
        }

