        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>makeUriRequest</c> command, which performs an
        /// HTTP request to the given URI with the optional request data,
        /// method, and raw-response selector.  When a file name is supplied
        /// the response content is downloaded to that file and its signature
        /// is verified, in which case a {hexHash filePath signatureText} list
        /// is returned; otherwise the response text is returned.  Available
        /// only when compiled with XML, network, and web support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode MakeUriRequest( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 2) || (argumentCount > 6))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} " +
                    "uri ?data? ?method? ?raw? ?fileName?\"",
                    Constants.MakeUriRequestCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            Uri contentUri = null;

            if (Value.GetUri(
                    arguments[1], UriKind.Absolute, cultureInfo,
                    ref contentUri, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            string method = null; /* TODO: Good default? */

            if (argumentCount >= 4)
            {
                method = arguments[3];

                if (String.IsNullOrEmpty(method))
                    method = null;
            }

            bool raw = false; /* TODO: Good default? */

            if (argumentCount >= 5)
            {
                string valueString = arguments[4];

                if (String.IsNullOrEmpty(valueString))
                    valueString = null;

                if (valueString != null)
                {
                    if (Value.GetBoolean2(
                            valueString, ValueFlags.AnyBoolean,
                            cultureInfo, ref raw,
                            ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
                }
            }

            string contentFileName = null;

            if (argumentCount == 6)
            {
                contentFileName = arguments[5];

                if (String.IsNullOrEmpty(contentFileName))
                    contentFileName = null;
            }

            StringDictionary data = null;

            if (argumentCount >= 3)
            {
                string valueString = arguments[2];

                if (String.IsNullOrEmpty(valueString))
                    valueString = null;

                if (valueString != null)
                {
                    if (Helpers.GetRequestData(
                            interpreter, valueString, ref data,
                            ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
                }
            }

            string contentText = null;

            if (Helpers.MakeUriRequest(
                    interpreter, contentUri, null, method, data,
                    evaluateClientData.Encoding, contentFileName,
                    evaluateClientData.Timeout, false, raw,
                    ref contentText, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            if (contentFileName == null)
            {
                result = contentText;
                return ReturnCode.Ok;
            }

            string signatureFileName =
                DataOps.FormatSignatureFileName(contentFileName);

            Uri signatureUri;

            if (!Uri.TryCreate(
                    DataOps.FormatSignatureFileName(
                    contentUri.ToString()), UriKind.Absolute,
                    out signatureUri))
            {
                result = "could not create signature uri";
                return ReturnCode.Error;
            }

            string signatureText = null;

            if (Helpers.MakeUriRequest(
                    interpreter, signatureUri, null, method, data,
                    evaluateClientData.Encoding, signatureFileName,
                    evaluateClientData.Timeout, false, raw,
                    ref signatureText, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            byte[] signatureBytes = null;

            if (!DataOps.TryReadSignatureFile(
                    interpreter, evaluateClientData.Encoding,
                    signatureText, evaluateClientData.Timeout,
                    evaluateClientData.AllowRemoteUri,
                    ref signatureBytes, ref result))
            {
                return ReturnCode.Error;
            }

            byte[] contentBytes = null;

            try
            {
                contentBytes = File.ReadAllBytes(
                    contentText); /* throw */
            }
            catch (Exception e)
            {
                result = e;
                return ReturnCode.Error;
            }

            byte[] hashValue = null;
            IKeyPair keyPair = null;

            if (ScriptOps.VerifyBytes(
                    evaluateClientData.HashAlgorithmName,
                    evaluateClientData.HashKey, contentBytes,
                    evaluateClientData.KeyPairs, signatureBytes,
                    ref hashValue, ref keyPair,
                    ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            string keyUsage = __KeyUsage.ReadData;

            if ((keyUsage != null) &&
                (ScriptOps.CheckKeyUsage(
                    keyPair, keyUsage, EntityType.File,
                    ref result) != ReturnCode.Ok))
            {
                return ReturnCode.Error;
            }

            result = StringList.MakeList(
                DataOps.FormatHexadecimal(hashValue), contentText,
                signatureText);

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>removeLicense</c> command, which removes the
        /// license certificate identified by the given GUID.  Available only
        /// when compiled with XML, network, and web support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode RemoveLicense( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if (argumentCount != 2)
            {
                result = String.Format(
                    "wrong # args: should be \"{0} id\"",
                    Constants.RemoveLicenseCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            Guid id = Guid.Empty;

            if (Value.GetGuid(arguments[1],
                    cultureInfo, ref id, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            if (LicenseState.RemoveCertificate(id, ref result))
            {
                result = String.Empty;
                return ReturnCode.Ok;
            }
            else
            {
                return ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////

        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>requestLicense</c> command, which requests a
        /// license for the given GUID from a remote server (using the
        /// optional base URI and assembly name), returning the file name of
        /// the downloaded license.  Available only when compiled with XML,
        /// network, and web support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode RequestLicense( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 2) || (argumentCount > 4))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} " +
                    "id ?baseUri? ?assemblyName?\"",
                    Constants.RequestLicenseCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            if (EvaluateClientData.CheckRequiredVersion(
                    evaluateClientData, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            Guid id = Guid.Empty;

            if (Value.GetGuid(arguments[1],
                    cultureInfo, ref id, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            Uri baseUri = null;

            if (argumentCount >= 3)
            {
                string valueString = arguments[2];

                if (String.IsNullOrEmpty(valueString))
                    valueString = null;

                if (valueString != null)
                {
                    if (Value.GetUri(
                            valueString, UriKind.Absolute, cultureInfo,
                            ref baseUri, ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
                }
            }

            if (baseUri == null)
            {
                Assembly assembly = null;

                if (argumentCount == 4)
                {
                    string valueString = arguments[3];

                    if (String.IsNullOrEmpty(valueString))
                        valueString = null;

                    if (valueString != null)
                    {
                        assembly = Helpers.GetRequestAssembly(
                            valueString, evaluateClientData.Plugin,
                            ref result);

                        if (assembly == null)
                            return ReturnCode.Error;
                    }
                }

                if (assembly == null)
                    assembly = AssemblyOps.GetObject();

                baseUri = Helpers.GetRequestBaseUri(
                    assembly, cultureInfo, ref result);

                if (baseUri == null)
                    return ReturnCode.Error;
            }

            string fileName = null;

            if (Helpers.RequestLicense(interpreter,
                    baseUri, evaluateClientData.Encoding, id,
                    evaluateClientData.Timeout, ref fileName,
                    ref result) == ReturnCode.Ok)
            {
                result = fileName;
                return ReturnCode.Ok;
            }

            return ReturnCode.Error;
        }
#endif
#endif

