#if WEB
        /* Eagle._Components.Public.Delegates.ExecuteCallback */
        /// <summary>
        /// Implements the <c>joinUriParts</c> command, which joins a base URI
        /// with a relative URI, optionally incorporating query parameters
        /// drawn from the named variable, returning the combined URI.
        /// Available only when compiled with web support.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the operation is being performed.
        /// </param>
        /// <param name="clientData">
        /// The extra data supplied by the caller, if any.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments supplied to the command.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result of the operation, or an error
        /// message describing why it failed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> value that indicates the type of
        /// failure.
        /// </returns>
        public static ReturnCode JoinUriParts( /* CORE */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            ref Result result        /* out */
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                result = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if ((argumentCount < 3) || (argumentCount > 4))
            {
                result = String.Format(
                    "wrong # args: should be \"{0} " +
                    "baseUri relativeUri ?varName?\"",
                    Constants.JoinUriPartsCommandName);

                return ReturnCode.Error;
            }

            EvaluateClientData evaluateClientData =
                clientData as EvaluateClientData;

            if (evaluateClientData == null)
            {
                result = "missing context clientData";
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = evaluateClientData.CultureInfo;
            Uri baseUri = null;

            if (Value.GetUri(
                    arguments[1], UriKind.Absolute, cultureInfo,
                    ref baseUri, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            StringDictionary data = null;

            if (argumentCount == 4)
            {
                Result value = null;

                if (interpreter.GetVariableValue(
                        Constants.GetVariableFlags,
                        arguments[3], ref value,
                        ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                data = StringDictionary.FromString(
                    value, true, ref result);

                if (data == null)
                    return ReturnCode.Error;
            }

            Uri uri = null;

            if (Helpers.JoinUriParts(
                    baseUri, arguments[2], data,
                    evaluateClientData.Encoding,
                    Constants.RequestUriFlags, ref uri,
                    ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            result = uri;
            return ReturnCode.Ok;
        }
#endif
